                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Mahmya Island day trip?" }, { "de", "Was ist im Tagesausflug zur Insel Mahmya enthalten?" }, { "it", "Cosa è incluso nell'escursione di un giorno all'isola di Mahmya?" }, { "fr", "Qu'est-ce qui est inclus dans l'excursion d'une journée à l'île de Mahmya ?" }, { "ru", "Что входит в стоимость однодневной экскурсии на остров Махмея?" } }, Answers = new Dictionary<string, string> { { "en", "The trip includes hotel pickup and drop-off, scenic boat transfers across the Red Sea, national park conservation fees, reserved beach loungers and shaded pergolas, a freshly prepared buffet lunch at Mahmya restaurant, and a guided offshore boat snorkeling stop with equipment." }, { "de", "Der Ausflug beinhaltet Hin- und Rücktransfer vom Hotel, malerische Bootstransfers im Roten Meer, Nationalparkgebühren, reservierte Strandliegen und Pergolen, ein frisch zubereitetes Mittagsbuffet im Mahmya-Restaurant sowie einen geführten Schnorchelstopp vom Boot inklusive Ausrüstung." }, { "it", "Il tour comprende transfer da e per l'hotel, navigazione panoramica nel Mar Rosso, tasse del parco marino protetto, lettini e ombrelloni riservati sulla spiaggia, pranzo a buffet preparato al ristorante di Mahmya e una sosta guidata di snorkeling in barca con attrezzatura inclusa." }, { "fr", "L'excursion comprend les transferts hôtel aller-retour, la traversée en bateau, les taxes du parc national, les transats et parasols réservés, un déjeuner buffet frais au restaurant de Mahmya, ainsi qu'un arrêt de snorkeling guidé en pleine mer avec prêt de matériel." }, { "ru", "В тур включены трансфер из отеля и обратно, морская прогулка на комфортабельном катере, сборы национального заповедника, шезлонги с навесами на пляже, обед 'шведский стол' в ресторане Махмея и остановка для снорклинга на рифах с гидом и снаряжением." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I bring and wear for Mahmya Island?" }, { "de", "Was sollte ich für den Ausflug zur Insel Mahmya mitbringen und anziehen?" }, { "it", "Cosa portare e come vestirsi per l'escursione a Mahmya Island?" }, { "fr", "Que faut-il apporter et porter pour l'excursion sur l'île de Mahmya ?" }, { "ru", "Что взять с собой и как одеться для поездки на остров Махмея?" } }, Answers = new Dictionary<string, string> { { "en", "Bring your hotel beach towel, swimwear, sunglasses, high-SPF reef-safe sunscreen, a sun hat, and cash for drinks or personal souvenirs. We also recommend water shoes for the shore and a light cover-up or cardigan for breezy boat rides." }, { "de", "Bringen Sie ein Badehandtuch aus Ihrem Hotel, Badebekleidung, Sonnenbrille, riffsichere Sonnencreme mit hohem LSF, einen Sonnenhut und Bargeld für Getränke oder Souvenirs mit. Badeschuhe für den Uferbereich und eine leichte Weste für die Bootsfahrt sind ebenfalls ratsam." }, { "it", "Portate il telo mare dell'hotel, costume da bagno, occhiali da sole, crema solare rispettosa dei coralli, cappello e contanti per bevande extra o mance. Consigliamo scarpette da scoglio e una giacca leggera per il tragitto in barca esposto alla brezza marina." }, { "fr", "Apportez votre serviette de bain d'hôtel, maillot de bain, lunettes de soleil, crème solaire biodégradable, chapeau et de la monnaie pour les boissons supplémentaires. Des chaussures d'eau et un gilet léger pour la brise en mer sont également recommandés." }, { "ru", "Возьмите пляжное полотенце из отеля, купальник, солнцезащитные очки, безопасный для рифов крем от солнца, головной убор и наличные на напитки и чаевые. Рекомендуются коралловые тапочки и легкая ветровка для морской прогулки с ветерком." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "How does hotel pick-up work and how long is the Mahmya tour?" }, { "de", "Wie funktioniert die Hotelabholung und wie lange dauert die Mahmya-Tour?" }, { "it", "Come si svolge il pick-up in hotel e quanto dura il tour di Mahmya?" }, { "fr", "Comment s'organise la prise en charge et quelle est la durée de la visite de Mahmya ?" }, { "ru", "Как организован трансфер из отеля и сколько длится экскурсия на остров Махмея?" } }, Answers = new Dictionary<string, string> { { "en", "Pick-up from Hurghada hotels takes place around 08:00 to 08:45 AM (exact time sent via WhatsApp the evening before). The total excursion lasts approximately 7 to 8 hours, returning to your resort around 16:30 PM." }, { "de", "Die Abholung an Hurghada-Hotels erfolgt meist zwischen 08:00 und 08:45 Uhr (genaue Zeit am Vorabend per WhatsApp). Der Gesamtausflug dauert etwa 7 bis 8 Stunden mit Rückkehr zum Hotel gegen 16:30 Uhr." }, { "it", "Il pick-up negli hotel di Hurghada avviene generalmente tra le 08:00 e le 08:45 (l'orario esatto viene comunicato su WhatsApp la sera prima). L'escursione dura circa 7-8 ore, con rientro in struttura previsto verso le 16:30." }, { "fr", "La prise en charge aux hôtels d'Hurghada a lieu entre 08h00 et 08h45 (l'horaire précis vous est envoyé sur WhatsApp la veille au soir). L'excursion dure environ 7 à 8 heures, pour un retour vers 16h30." }, { "ru", "Сбор туристов из отелей Хургады проходит с 08:00 до 08:45 (точное время подтверждается накануне вечером в WhatsApp). Экскурсия длится около 7-8 часов, возвращение в отель около 16:30." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is Mahmya Island suitable for non-swimmers and families with children?" }, { "de", "Ist die Insel Mahmya für Nichtschwimmer und Familien mit Kindern geeignet?" }, { "it", "L'isola di Mahmya è adatta a non nuotatori e a famiglie con bambini?" }, { "fr", "L'île de Mahmya convient-elle aux non-nageurs et aux familles avec enfants ?" }, { "ru", "Подходит ли остров Махмея для тех, кто не умеет плавать, и семей с детьми?" } }, Answers = new Dictionary<string, string> { { "en", "Yes, absolutely. Mahmya features very gentle shallow sandy lagoons perfect for paddling, toddlers, and non-swimmers. Life vests are readily provided free of charge for boat snorkeling, and professional lifeguards oversee the beach." }, { "de", "Ja, absolut. Mahmya bietet sehr flache, sanft abfallende Sandlagunen, ideal für Kinder und Nichtschwimmer. Schwimmwesten werden für das Bootsschnorcheln kostenlos gestellt, und Rettungsschwimmer überwachen den Strand." }, { "it", "Sì, assolutamente. Mahmya vanta lagune di sabbia bianca con acque basse e tranquille, ideali per bambini e non nuotatori. I giubbotti salvagente sono forniti gratuitamente per lo snorkeling in barca e la spiaggia è sorvegliata da bagnini." }, { "fr", "Oui, tout à fait. Mahmya possède des lagons sablonneux aux eaux peu profondes, idéaux pour barboter en famille ou pour les non-nageurs. Des gilets de sauvetage sont fournis gratuitement pour le snorkeling et des maîtres-nageurs surveillent la plage." }, { "ru", "Да, безусловно. На острове пологий песчаный заход и прозрачное мелководье, что идеально для детей и тех, кто не плавает. Спасательные жилеты выдаются бесплатно, а за безопасностью следят профессиональные спасатели." } } } },
