                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What makes Eden Island special and what is included in the trip?" }, { "de", "Was macht Eden Island besonders und was ist im Ausflug enthalten?" }, { "it", "Cosa rende speciale Eden Island e cosa è incluso nel tour?" }, { "fr", "Qu'est-ce qui rend Eden Island unique et qu'est-ce qui est inclus dans le voyage ?" }, { "ru", "Чем уникален остров Иден (Eden Island) и что входит в тур?" } }, Answers = new Dictionary<string, string> { { "en", "Eden Island is known for its chic bohemian beach club ambiance, aesthetic photo swings, and crystal lagoons. The trip includes round-trip hotel transfers, boat cruise, island entry and loungers, a delicious buffet lunch, soft drinks on board, and two guided snorkeling stops at pristine coral reefs." }, { "de", "Eden Island besticht durch seine stilvolle Boho-Beach-Club-Atmosphäre, Fotoschaukeln im seichten Wasser und türkisblaue Lagunen. Im Preis enthalten sind Hoteltransfers, Bootsfahrt, Inseleintritt mit Liegen, Mittagsbuffet, alkoholfreie Getränke an Bord sowie zwei geführte Schnorchelstopps." }, { "it", "Eden Island si distingue per lo stile raffinato boho-chic, le celebri altalene sull'acqua e le lagune cristalline. Il tour include transfer, navigazione, ingresso con lettini, pranzo a buffet, bevande analcoliche a bordo e due soste di snorkeling guidato tra barriere coralline incontaminate." }, { "fr", "Eden Island est réputée pour son ambiance de club de plage bohème chic, ses balançoires aquatiques pour photos et ses lagons turquoise. L'excursion inclut les transferts, la traversée, l'accès à l'île avec transats, le buffet du midi, les boissons sans alcool et deux arrêts snorkeling." }, { "ru", "Остров Иден славится стильной атмосферой бохо-бич-клаба, фотогеничными качелями в море и бирюзовой водой. В тур входят трансферы, морская прогулка, вход на остров с шезлонгами, обед 'шведский стол', безалкогольные напитки на яхте и 2 остановки на коралловых рифах для снорклинга." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I pack for the Eden Island excursion?" }, { "de", "Was sollte ich für den Ausflug nach Eden Island einpacken?" }, { "it", "Cosa mettere in borsa per la gita a Eden Island?" }, { "fr", "Que dois-je emporter pour l'excursion à Eden Island ?" }, { "ru", "Что взять с собой в поездку на остров Иден?" } }, Answers = new Dictionary<string, string> { { "en", "Pack your swimwear, a beach towel, sunglasses, reef-friendly sunscreen, a waterproof phone pouch for photo opportunities on the water swings, and cash for specialty cocktails or fresh fruit juices at the island bar." }, { "de", "Packen Sie Badebekleidung, Strandtuch, Sonnenbrille, riffsichere Sonnencreme, eine wasserdichte Handyhülle für Aufnahmen auf den Wasserschaukeln und etwas Bargeld für Cocktails oder frische Fruchtsäfte an der Inselbar ein." }, { "it", "Mettete in borsa costume, telo mare, occhiali da sole, crema solare eco-compatibile, custodia impermeabile per smartphone (ottima per foto sulle altalene) e contanti per cocktail speciali o succhi freschi al bar dell'isola." }, { "fr", "Emportez maillot, serviette, lunettes de soleil, crème solaire respectueuse de la mer, pochette étanche pour vos photos sur les balançoires marines et un peu d'argent liquide pour les cocktails ou jus frais au bar de la plage." }, { "ru", "Возьмите купальник, полотенце, солнцезащитные очки, безопасный крем от солнца, водонепроницаемый чехол для телефона (для фото на водных качелях) и наличные для коктейлей и свежевыжатых соков в баре острова." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the schedule and pickup time for Eden Island?" }, { "de", "Wie sind Zeitplan und Abholzeiten für Eden Island?" }, { "it", "Quali sono gli orari e il punto di incontro per Eden Island?" }, { "fr", "Quels sont les horaires et l'heure de départ pour Eden Island ?" }, { "ru", "Какое расписание и время выезда на остров Иден?" } }, Answers = new Dictionary<string, string> { { "en", "Pickup begins from 08:15 to 09:00 AM across Hurghada hotels. You will spend around 2 to 2.5 hours on the island and enjoy two 45-minute reef snorkeling sessions. You will return to your hotel marina around 16:30 PM." }, { "de", "Die Abholung erfolgt zwischen 08:15 und 09:00 Uhr. Sie verbringen etwa 2 bis 2,5 Stunden auf der Insel und genießen zwei 45-minütige Schnorchelstopps am Riff. Rückkehr zum Hafen und Hotel gegen 16:30 Uhr." }, { "it", "Il prelievo negli hotel si effettua tra le 08:15 e le 09:00. Trascorrerete circa 2 - 2,5 ore sull'isola e parteciperete a due sessioni di snorkeling di 45 minuti ciascuna. Rientro in hotel programmato per le 16:30 circa." }, { "fr", "Le ramassage a lieu entre 08h15 et 09h00. Vous profiterez d'environ 2h à 2h30 sur l'île ainsi que de deux sessions de snorkeling de 45 minutes chacune. Le retour à l'hôtel se fait vers 16h30." }, { "ru", "Трансфер забирает гостей с 08:15 до 09:00. На самом острове вы проведете 2-2,5 часа, а также будет 2 остановки по 45 минут для снорклинга на рифах. Возвращение в отель к 16:30." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is snorkeling gear provided on the Eden Island trip?" }, { "de", "Wird auf der Eden Island Tour Schnorchelausrüstung bereitgestellt?" }, { "it", "L'attrezzatura da snorkeling è fornita durante l'escursione a Eden Island?" }, { "fr", "Le matériel de snorkeling est-il fourni lors du tour à Eden Island ?" }, { "ru", "Предоставляется ли снаряжение для снорклинга на экскурсии в Иден?" } }, Answers = new Dictionary<string, string> { { "en", "Yes, masks, snorkels, fins, and buoyancy life jackets are fully provided on board. If you prefer to use your own personal snorkel or prescription mask, you are welcome to bring it along." }, { "de", "Ja, Masken, Schnorchel, Flossen und Schwimmwesten werden an Bord kostenlos bereitgestellt. Sie können selbstverständlich auch Ihre eigene Schnorchelausrüstung oder optische Maske mitbringen." }, { "it", "Sì, maschere, boccagli, pinne e giubbotti di galleggiamento sono forniti a bordo senza costi aggiuntivi. Siete comunque liberi di portare la vostra attrezzatura personale o maschere graduate." }, { "fr", "Oui, masques, tubas, palmes et gilets de flottabilité sont mis à disposition gratuitement à bord. Vous êtes libre d'apporter votre propre équipement personnel si vous préférez." }, { "ru", "Да, маски, трубки, ласты и спасательные жилеты предоставляются на яхте бесплатно. Если у вас есть свое любимое снаряжение или маска с диоптриями, вы можете взять ее с собой." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193197.jpg", Captions = new Dictionary<string, string> { { "en", "Eden Island - Experience" }, { "de", "Insel Eden – Traumhafter Inselausflug - Erlebnis" }, { "it", "Isola di Eden – Relax e Barriera Corallina - Esperienza" }, { "fr", "Échappée à Eden Island - Expérience" }, { "ru", "Остров Эдем — Морское путешествие и релакс - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193198.jpg", Captions = new Dictionary<string, string> { { "en", "Eden Island - Experience" }, { "de", "Insel Eden – Traumhafter Inselausflug - Erlebnis" }, { "it", "Isola di Eden – Relax e Barriera Corallina - Esperienza" }, { "fr", "Échappée à Eden Island - Expérience" }, { "ru", "Остров Эдем — Морское путешествие и релакс - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193205.jpg", Captions = new Dictionary<string, string> { { "en", "Eden Island - Experience" }, { "de", "Insel Eden – Traumhafter Inselausflug - Erlebnis" }, { "it", "Isola di Eden – Relax e Barriera Corallina - Esperienza" }, { "fr", "Échappée à Eden Island - Expérience" }, { "ru", "Остров Эдем — Морское путешествие и релакс - Впечатления" } } } }
