            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Ozirea Island" }, { "de", "Insel Ozirea – Erholung & Schnorcheln" }, { "it", "Isola di Ozirea – Giornata Relax e Mare" }, { "fr", "Journée Détente sur l'Île Ozirea" }, { "ru", "Остров Озирея — Морской круиз и отдых" } },
                Descriptions = new Dictionary<string, string> { { "en", "Spend a relaxing day at Ozirea Island with a mix of snorkeling, beach time and leisure facilities. The experience typically combines a boat trip, reef snorkeling, lunch and time to enjoy the island at your own pace." }, { "de", "Verbringen Sie einen unbeschwerten Tag auf der Insel Ozirea. Die Tour verbindet eine angenehme Schifffahrt mit Schnorchelstopps an lebendigen Riffen, einem köstlichen Mittagessen und ausgiebiger Zeit zum Entspannen am Strand nach Ihrem eigenen Rhythmus." }, { "it", "Trascorrete una piacevole giornata sull'isola di Ozirea, combinando mare cristallino e ottimi servizi. L'esperienza include la navigazione in barca, soste di snorkeling sui coralli, un delizioso pranzo a bordo e tempo libero per vivere l'isola in totale tranquillità." }, { "fr", "Passez une journée de détente sur l'île Ozirea, combinant plaisirs balnéaires et découverte marine. Au programme : croisière en mer, plongée avec tuba sur les récifs coralliens, savoureux déjeuner et temps libre pour profiter de l'île à votre rythme." }, { "ru", "Проведите безмятежный день на острове Озирея в окружении лазурных вод. Программа включает комфортную морскую прогулку на яхте, снорклинг у красочных рифов, аппетитный обед и свободное время для отдыха на пляже в собственном темпе." } },
