                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Ozirea Island excursion?" }, { "de", "Was ist im Ausflug zur Ozirea-Insel enthalten?" }, { "it", "Cosa è incluso nell'escursione a Ozirea Island?" }, { "fr", "Qu'est-ce qui est inclus dans l'excursion sur l'île d'Ozirea ?" }, { "ru", "Что входит в программу экскурсии на остров Озиреа?" } }, Answers = new Dictionary<string, string> { { "en", "The excursion includes hotel transport, a Red Sea cruise, entrance tickets to Ozirea Island, sun loungers and umbrella shades, an open-buffet lunch, mineral water and soft drinks, and guided snorkeling at vibrant coral reef gardens." }, { "de", "Der Ausflug umfasst den Hoteltransfer, eine Bootsfahrt auf dem Roten Meer, Inseleintritt mit Sonnenliegen und Sonnenschirmen, ein Mittagsbuffet, Erfrischungsgetränke sowie geführtes Schnorcheln an Korallenriffen." }, { "it", "L'escursione include navetta dall'hotel, crociera sul Mar Rosso, ingresso a Ozirea Island con lettini e ombrelloni, pranzo a buffet, acqua e soft drink, e snorkeling guidato presso giardini di corallo." }, { "fr", "L'excursion inclut le transport depuis l'hôtel, la croisière, l'entrée à l'île avec transats et parasols, le déjeuner buffet, eau et rafraîchissements, ainsi que du snorkeling guidé sur de magnifiques récifs." }, { "ru", "Экскурсия включает трансфер из отеля, морскую прогулку, входной билет на остров Озиреа с лежаками и зонтиками, обед 'шведский стол', прохладительные напитки и снорклинг с гидом на коралловых рифах." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "How is Ozirea Island different from Orange Bay or Mahmya?" }, { "de", "Wie unterscheidet sich die Ozirea-Insel von Orange Bay oder Mahmya?" }, { "it", "In cosa differisce Ozirea Island da Orange Bay o Mahmya?" }, { "fr", "En quoi l'île d'Ozirea se différencie-t-elle d'Orange Bay ou de Mahmya ?" }, { "ru", "Чем остров Озиреа отличается от Оранж Бэй или Махмеи?" } }, Answers = new Dictionary<string, string> { { "en", "Ozirea Island offers a more peaceful, unhurried atmosphere with fewer tourist crowds, making it ideal for couples and travelers seeking serene relaxation, spacious sunbeds, and pristine shallow waters." }, { "de", "Ozirea Island bietet eine ruhigere, entspanntere Atmosphäre mit weniger Besuchern als größere Strände. Ideal für Paare und Erholungssuchende, die viel Platz, Komfort und ungestörte Ruhe am Meer schätzen." }, { "it", "Ozirea Island offre un'atmosfera più intima e rilassata, con minor affollamento rispetto alle spiagge più famose. È la scelta perfetta per coppie e viaggiatori in cerca di tranquillità e spazi ampi." }, { "fr", "L'île d'Ozirea propose une ambiance plus intime et paisible, loin de la grande foule touristique. C'est l'option idéale pour les couples et les vacanciers désirant calme, sérénité et espace." }, { "ru", "Остров Озиреа отличается более спокойной, камерной атмосферой без лишнего шума и скопления людей, что делает его отличным выбором для пар и любителей уединенного комфортного отдыха." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I bring for the day at Ozirea Island?" }, { "de", "Was sollte ich für einen Tag auf der Insel Ozirea mitbringen?" }, { "it", "Cosa portare per la giornata a Ozirea Island?" }, { "fr", "Que faut-il emporter pour la journée à l'île d'Ozirea ?" }, { "ru", "Что взять с собой на остров Озиреа?" } }, Answers = new Dictionary<string, string> { { "en", "Bring your towel, swimwear, high-factor sunscreen, sunglasses, a hat, a book or e-reader for relaxed lounging, and some Egyptian pounds or euros for bar extras and tips." }, { "de", "Bringen Sie Ihr Strandtuch, Badekleidung, Sonnencreme mit hohem Lichtschutzfaktor, Sonnenbrille, Kopfbedeckung sowie Bargeld für Zusatzbestellungen an der Bar und Trinkgelder mit." }, { "it", "Portate telo da spiaggia, costume da bagno, crema solare ad alta protezione, occhiali da sole, cappellino e contanti (lire egiziane o euro) per eventuali consumazioni extra al bar e mance." }, { "fr", "Prenez votre serviette, maillot de bain, crème solaire haute protection, lunettes, chapeau et un peu d'argent liquide pour vos consommations personnelles au bar ou les pourboires." }, { "ru", "Возьмите пляжное полотенце, купальник, солнцезащитный крем с высоким SPF, очки, панаму и наличные деньги (египетские фунты или евро) для бара и чаевых команде." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What are the timings and pickup details for Ozirea Island?" }, { "de", "Wie sind die Abholzeiten und die Dauer der Ozirea-Tour?" }, { "it", "Quali sono i dettagli su orari e transfer per Ozirea Island?" }, { "fr", "Quels sont les détails des horaires et transferts pour Ozirea ?" }, { "ru", "Каковы время трансфера и общая продолжительность поездки на Озиреа?" } }, Answers = new Dictionary<string, string> { { "en", "Pickup is between 08:00 and 08:45 AM from Hurghada. The boat leaves the pier at approximately 09:30 AM and returns at 16:00 PM. Total duration is roughly 7 to 8 hours." }, { "de", "Die Abholung erfolgt zwischen 08:00 und 08:45 Uhr ab Hurghada. Das Boot legt gegen 09:30 Uhr ab und kehrt um 16:00 Uhr zum Hafen zurück. Gesamtdauer ca. 7 bis 8 Stunden." }, { "it", "Il prelievo in hotel avviene tra le 08:00 e le 08:45. La barca salpa alle 09:30 circa e rientra in porto verso le 16:00, per una durata totale di circa 7-8 ore." }, { "fr", "Le ramassage s'effectue entre 08h00 et 08h45. Le départ du bateau a lieu vers 09h30 pour un retour au port vers 16h00. La durée globale est d'environ 7 à 8 heures." }, { "ru", "Трансфер из отелей Хургады с 08:00 до 08:45. Корабль отправляется из марины около 09:30 и возвращается в 16:00. Общая длительность около 7-8 часов." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193210.jpg", Captions = new Dictionary<string, string> { { "en", "Ozirea Island - Experience" }, { "de", "Insel Ozirea – Erholung & Schnorcheln - Erlebnis" }, { "it", "Isola di Ozirea – Giornata Relax e Mare - Esperienza" }, { "fr", "Journée Détente sur l'Île Ozirea - Expérience" }, { "ru", "Остров Озирея — Морской круиз и отдых - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193219.jpg", Captions = new Dictionary<string, string> { { "en", "Ozirea Island - Experience" }, { "de", "Insel Ozirea – Erholung & Schnorcheln - Erlebnis" }, { "it", "Isola di Ozirea – Giornata Relax e Mare - Esperienza" }, { "fr", "Journée Détente sur l'Île Ozirea - Expérience" }, { "ru", "Остров Озирея — Морской круиз и отдых - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193224.jpg", Captions = new Dictionary<string, string> { { "en", "Ozirea Island - Experience" }, { "de", "Insel Ozirea – Erholung & Schnorcheln - Erlebnis" }, { "it", "Isola di Ozirea – Giornata Relax e Mare - Esperienza" }, { "fr", "Journée Détente sur l'Île Ozirea - Expérience" }, { "ru", "Остров Озирея — Морской круиз и отдых - Впечатления" } } } }
