            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Hula Hula Island" }, { "de", "Insel Hula Hula – Lebendige Bootstour & Strand" }, { "it", "Isola di Hula Hula – Escursione in Barca e Spiaggia" }, { "fr", "Échappée Hula Hula Island & Snorkeling" }, { "ru", "Остров Хула-Хула — Яркий морской круиз" } },
                Descriptions = new Dictionary<string, string> { { "en", "A fun and easy-going island day combining a boat cruise, snorkeling and time on Hula Hula Island. Guests can enjoy the beach, swim in the Red Sea and relax between snorkeling stops, making it a strong option for families and first-time visitors." }, { "de", "Ein sonniger, unbeschwerter Tagesausflug mit Bootsfahrt, Schnorchelerlebnissen und Strandzeit auf der Insel Hula Hula. Ideal für Familien und Erstbesucher, die das Rote Meer in freundlicher Atmosphäre beim Schwimmen und Sonnenbaden genießen möchten." }, { "it", "Una divertente e spensierata gita in barca che unisce snorkeling, mare aperto e relax sull'isola di Hula Hula. Ideale per famiglie e per chi visita Hurghada per la prima volta, con splendide soste bagno e tanto sole." }, { "fr", "Une escapade maritime conviviale et ensoleillée combinant croisière en bateau, snorkeling et détente sur les plages de l'île Hula Hula. Une formule idéale pour les familles et les vacanciers désireux de goûter aux joies de la mer Rouge." }, { "ru", "Увлекательный морской день, объединяющий прогулку на корабле, плавание с маской и отдых на пляже острова Хула-Хула. Замечательный вариант для семей с детьми и тех, кто впервые открывает для себя красоты Красного моря." } },
