                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Hula Hula Island trip?" }, { "de", "Was ist im Hula Hula Island Ausflug inbegriffen?" }, { "it", "Cosa è compreso nel tour di Hula Hula Island?" }, { "fr", "Que comprend l'excursion sur l'île de Hula Hula ?" }, { "ru", "Что входит в поездку на остров Хула Хула (Hula Hula Island)?" } }, Answers = new Dictionary<string, string> { { "en", "This fun island excursion includes return transfers, a cruise across the Red Sea, admission to Hula Hula beach, shaded loungers, a freshly prepared buffet lunch, soft drinks and water on board, and guided snorkeling with complimentary gear." }, { "de", "Dieser erlebnisreiche Ausflug umfasst Hin- und Rücktransfers, Bootsfahrt auf dem Roten Meer, Eintritt zum Hula-Hula-Strand, schattige Liegestühle, Mittagsbuffet, Softdrinks und Wasser an Bord sowie Schnorchelstopps mit Ausrüstung." }, { "it", "Questa divertente escursione comprende trasferimenti a/r, navigazione nel Mar Rosso, ingresso alla spiaggia di Hula Hula, lettini ombreggiati, pranzo a buffet, bevande analcoliche e soste snorkeling con equipaggiamento." }, { "fr", "Cette sortie conviviale comprend les transferts, la croisière, l'entrée à la plage d'Hula Hula avec transats ombragés, un déjeuner buffet, boissons fraîches à bord et des arrêts snorkeling avec matériel fourni." }, { "ru", "Этот увлекательный тур включает трансфер из отеля и обратно, морскую прогулку, вход на оборудованный пляж Хула Хула, шезлонги с тенью, обед 'шведский стол', напитки на яхте и снорклинг на коралловых рифах со снаряжением." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Why is Hula Hula Island recommended for families with children?" }, { "de", "Warum wird Hula Hula Island besonders für Familien mit Kindern empfohlen?" }, { "it", "Perché Hula Hula Island è consigliata per le famiglie con bambini?" }, { "fr", "Pourquoi Hula Hula Island est-elle conseillée aux familles avec enfants ?" }, { "ru", "Почему остров Хула Хула так популярен среди семей с детьми?" } }, Answers = new Dictionary<string, string> { { "en", "Hula Hula Island features a very safe, gently sloping sandy shoreline with zero rocks, warm shallow waters, lively tropical music, and helpful staff that make swimming and playing effortless for kids and beginners." }, { "de", "Hula Hula Island bietet einen flach abfallenden, feinsandigen Strand ohne scharfe Steine, warmes Flachwasser und fröhliche Musik. Das freundliche Team sorgt dafür, dass sich Kinder und Schwimmanfänger rundum wohlfühlen." }, { "it", "La spiaggia di Hula Hula vanta un fondale sabbioso che digrada dolcemente senza rocce, acque calde e calme e un'atmosfera allegra. È l'ambiente ideale e sicuro per il divertimento dei più piccoli." }, { "fr", "L'île offre une plage de sable fin en pente très douce sans rochers, une eau chaude et peu profonde ainsi qu'une ambiance musicale joyeuse, idéale pour les enfants et les baigneurs débutants." }, { "ru", "Пляж Хула Хула имеет пологий песчаный вход без камней и кораллов у берега, теплую мелкую воду и жизнерадостную музыку. Здесь максимально комфортно и безопасно детям и тем, кто только учится плавать." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should we wear and bring to Hula Hula Island?" }, { "de", "Was sollten wir anziehen und für Hula Hula Island mitnehmen?" }, { "it", "Come vestirsi e cosa portare a Hula Hula Island?" }, { "fr", "Que porter et emporter pour l'île de Hula Hula ?" }, { "ru", "Как одеться и что взять с собой на остров Хула Хула?" } }, Answers = new Dictionary<string, string> { { "en", "Wear your swimwear under casual light summer clothes. Bring your hotel beach towels, sunglasses, sunscreen, sandals or water shoes, a hat, and a camera or phone for tropical holiday photos." }, { "de", "Ziehen Sie Ihre Badekleidung direkt unter leichter Sommerkleidung an. Nehmen Sie Strandtücher aus dem Hotel, Sonnenbrille, Sonnencreme, Sandalen oder Badeschuhe, Sonnenhut und Ihr Smartphone für tolle Urlaubsfotos mit." }, { "it", "Indossate il costume sotto abiti estivi leggeri. Portate teli mare dell'hotel, occhiali da sole, protezione solare, ciabattine o scarpette da scoglio, cappellino e la fotocamera per immortalare i colori tropicali." }, { "fr", "Mettez votre maillot sous des vêtements d'été légers. Emportez vos serviettes d'hôtel, lunettes, crème solaire, sandales, chapeau et appareil photo pour capturer ces moments ensoleillés." }, { "ru", "Наденьте купальник под легкую летнюю одежду. Возьмите пляжные полотенца, солнцезащитные очки, крем от загара, сланцы, панаму и телефон для ярких тропических фотоснимков." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What are the timings for the Hula Hula Island trip?" }, { "de", "Wie sind die Zeiten für den Ausflug nach Hula Hula Island?" }, { "it", "Qual è la durata e l'orario del tour di Hula Hula Island?" }, { "fr", "Quels sont les horaires de l'excursion à Hula Hula Island ?" }, { "ru", "Какое расписание поездки на остров Хула Хула?" } }, Answers = new Dictionary<string, string> { { "en", "Pick-up is between 08:15 and 09:00 AM depending on your hotel location. The full day runs around 7 to 8 hours with arrival back at your resort around 16:30 PM." }, { "de", "Die Abholung erfolgt zwischen 08:15 und 09:00 Uhr je nach Lage Ihres Hotels. Der Tagesausflug dauert ca. 7 bis 8 Stunden mit Rückkehr zum Hotel gegen 16:30 Uhr." }, { "it", "Il prelievo avviene tra le 08:15 e le 09:00 in base alla posizione del resort. Il tour dura circa 7-8 ore, con rientro in struttura previsto verso le 16:30." }, { "fr", "Départ de l'hôtel entre 08h15 et 09h00 selon votre hébergement. L'excursion dure 7 à 8 heures avec un retour à votre hôtel aux alentours de 16h30." }, { "ru", "Сбор гостей из отелей проходит с 08:15 до 09:00. Вся экскурсия длится около 7-8 часов, возвращение в отель к 16:30." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193229.jpg", Captions = new Dictionary<string, string> { { "en", "Hula Hula Island - Experience" }, { "de", "Insel Hula Hula – Lebendige Bootstour & Strand - Erlebnis" }, { "it", "Isola di Hula Hula – Escursione in Barca e Spiaggia - Esperienza" }, { "fr", "Échappée Hula Hula Island & Snorkeling - Expérience" }, { "ru", "Остров Хула-Хула — Яркий морской круиз - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193225.jpg", Captions = new Dictionary<string, string> { { "en", "Hula Hula Island - Experience" }, { "de", "Insel Hula Hula – Lebendige Bootstour & Strand - Erlebnis" }, { "it", "Isola di Hula Hula – Escursione in Barca e Spiaggia - Esperienza" }, { "fr", "Échappée Hula Hula Island & Snorkeling - Expérience" }, { "ru", "Остров Хула-Хула — Яркий морской круиз - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Orange Bay & White Island" }, { "de", "Orange Bay & White Island – Die Malediven Ägyptens" }, { "it", "Orange Bay & White Island – I Caraibi del Mar Rosso" }, { "fr", "Orange Bay & White Island – Lagons Turquoise" }, { "ru", "Оранж Бэй и Белый Остров — Двойной круиз" } },
                Descriptions = new Dictionary<string, string> { { "en", "Discover two beautiful Red Sea stops in one day. Cruise to Orange Bay for turquoise water, beach time and snorkeling, then continue to White Island when sea and weather conditions allow. A great choice for guests who want scenery, swimming and a lively boat-day atmosphere." }, { "de", "Entdecken Sie zwei der spektakulärsten Buchten des Roten Meeres an einem Tag. Gleiten Sie über das Wasser zur weltbekannten Orange Bay mit ihren seichten Lagunen und Holzschaukeln, gefolgt von der strahlend weißen Sandbank White Island (wetterabhängig). Ein unverzichtbares Erlebnis für Naturliebhaber und Sonnenanbeter." }, { "it", "Scoprite due delle destinazioni più suggestive del Mar Rosso in un'unica escursione. Raggiungete la celebre Orange Bay per godervi acque turchesi, sabbia chiara e snorkeling, proseguendo poi verso la candida White Island (condizioni meteo permettendo). Perfetto per foto mozzafiato e bagni memorabili." }, { "fr", "Découvrez deux des plus beaux lagons de la mer Rouge en une seule journée. Naviguez vers la célèbre plage d'Orange Bay avec ses eaux cristallines peu profondes, puis poursuivez vers le banc de sable immaculé de White Island (selon la météo). Un décor paradisiaque digne des Caraïbes." }, { "ru", "Откройте для себя две жемчужины Красного моря за один день. Насладитесь лазурными мелководными лагунами и знаменитыми качелями в бухте Оранж Бэй, а затем отправьтесь к белоснежной песчаной косе Белого Острова (при благоприятной погоде). Потрясающие виды, яркие фото и великолепный снорклинг." } },
                Price = 30,
                Currency = "EUR",
                Duration = "Approx. 7-8 hours",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000011"),
