                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Orange Bay & White Island day tour?" }, { "de", "Was ist in der Tagestour Orange Bay & White Island enthalten?" }, { "it", "Cosa è compreso nel tour combinato Orange Bay & White Island?" }, { "fr", "Qu'est-ce qui est inclus dans le tour Orange Bay & White Island ?" }, { "ru", "Что включено в морской тур Оранж Бэй и Белый Остров (Orange Bay & White Island)?" } }, Answers = new Dictionary<string, string> { { "en", "The excursion includes hotel transport, a double-decker boat cruise, 2 hours on iconic Orange Bay with wooden boardwalks and swings, a visit to the natural sandbank of White Island (subject to tides/weather), two guided coral reef snorkeling stops, a buffet lunch with seafood and barbecue, soft drinks, and water sports rides (banana boat and sofa tube)." }, { "de", "Die Tour umfasst Hoteltransfer, Bootsfahrt, ca. 2 Stunden Aufenthalt in der bekannten Orange Bay mit Holzstegen und Schaukeln, Besuch der Sandbank White Island (wetter- und gezeitenabhängig), zwei geführte Schnorchelstopps, Mittagsbuffet, Softdrinks sowie Funsport (Bananenboot und Crazy Sofa)." }, { "it", "Il tour comprende transfer da/per l'hotel, crociera su yacht, 2 ore alla celebre Orange Bay tra passerelle in legno e altalene marine, sosta alla lingua di sabbia di White Island (meteo/maree permettendo), due soste snorkeling guidate, pranzo a buffet, bevande e giochi d'acqua (banana boat e ciambellone)." }, { "fr", "L'excursion inclut les transferts, la croisière en bateau, 2 heures à Orange Bay avec pontons et balançoires dans l'eau, une halte au banc de sable de White Island (selon météo/marée), deux arrêts snorkeling guidés, déjeuner buffet, boissons et activités nautiques (banane et bouée tractée)." }, { "ru", "Тур включает трансфер, круиз на яхте, 2 часа на знаменитом пляже Оранж Бэй с деревянными дорожками и качелями в море, высадку на песчаную косу Белый Остров (по погоде и приливам), 2 снорклинга на рифах, обед 'шведский стол', безалкогольные напитки и катание на банане и таблетке." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Why is Orange Bay called the 'Egyptian Maldives'?" }, { "de", "Warum wird Orange Bay auch als 'Ägyptische Malediven' bezeichnet?" }, { "it", "Perché Orange Bay viene definita le 'Maldive d'Egitto'?" }, { "fr", "Pourquoi surnomme-t-on Orange Bay les 'Maldives égyptiennes' ?" }, { "ru", "Почему Оранж Бэй называют 'Египетскими Мальдивами'?" } }, Answers = new Dictionary<string, string> { { "en", "Orange Bay is famous for its glowing cyan-turquoise lagoons, powder-soft white sand, wooden overwater paths, and hammock swings planted directly into the shallow sea, creating breathtaking Maldives-like scenery." }, { "de", "Orange Bay ist berühmt für seine leuchtend türkisfarbenen Lagunen, feinsten weißen Sand, Holzstege über dem Wasser und Hängematten direkt im seichten Meer – eine Szenerie wie auf den Malediven." }, { "it", "Orange Bay è celebre per le sue lagune turchesi trasparenti, la sabbia bianca candida, le passerelle in legno a pelo d'acqua e le amache posizionate in mezzo al mare, che rievocano paesaggi maldiviani." }, { "fr", "Orange Bay doit son surnom à ses eaux turquoise éblouissantes, son sable blanc immaculé, ses pontons en bois suspendus et ses balançoires plantées au milieu de l'eau rappelant les paysages des Maldives." }, { "ru", "Оранж Бэй заслужил это имя благодаря ослепительно бирюзовым лагунам, белоснежному песку, живописным деревянным мостикам и гамакам прямо в кристально чистой воде, как на тропических атоллах." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I bring and wear for Orange Bay & White Island?" }, { "de", "Was sollte ich für die Tour nach Orange Bay & White Island anziehen und mitnehmen?" }, { "it", "Cosa portare e come vestirsi per Orange Bay & White Island?" }, { "fr", "Que faut-il apporter et porter pour Orange Bay & White Island ?" }, { "ru", "Что взять с собой и в чем поехать на Оранж Бэй и Белый Остров?" } }, Answers = new Dictionary<string, string> { { "en", "Wear swimwear and comfortable beach attire. Pack hotel beach towels, high-SPF sunscreen, sunglasses, a hat, a waterproof phone case for spectacular photos, and some cash for drinks at the island bars." }, { "de", "Badekleidung und legere Strandbekleidung anziehen. Strandtücher, Sonnencreme, Sonnenbrille, Sonnenhut, eine wasserdichte Handyhülle für Traumfotos und Bargeld für Getränke an den Strandbars mitnehmen." }, { "it", "Indossate costume e abbigliamento da spiaggia. Portate teli mare dell'hotel, crema solare protettiva, occhiali, cappellino, custodia impermeabile per foto spettacolari e contanti per bevande ai bar dell'isola." }, { "fr", "Venez en tenue de plage avec votre maillot. Prenez les serviettes de l'hôtel, crème solaire, lunettes de soleil, chapeau, pochette étanche pour vos photos et des espèces pour les bars de plage." }, { "ru", "Оденьтесь в пляжную одежду поверх купальника. Не забудьте пляжные полотенца из отеля, крем с высоким фактором защиты, очки, головной убор, чехол для подводной съемки и наличные для бара на острове." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the duration, schedule, and safety advice for this trip?" }, { "de", "Wie sind Dauer, Zeitplan und Sicherheitshinweise für diese Tour?" }, { "it", "Quali sono durata, orari e consigli di sicurezza per questo tour?" }, { "fr", "Quelle est la durée, le déroulement et les consignes de sécurité ?" }, { "ru", "Какова продолжительность, расписание и правила безопасности в этой поездке?" } }, Answers = new Dictionary<string, string> { { "en", "Pick-up is around 08:00 to 08:45 AM, and the trip lasts approximately 7 to 8 hours. Life jackets are supplied and mandatory during water sports. If prone to seasickness, we advise taking motion sickness medication 30 minutes before boarding." }, { "de", "Abholung zwischen 08:00 und 08:45 Uhr, Tourdauer ca. 7-8 Stunden. Schwimmwesten sind an Bord vorhanden und bei den Wassersportaktivitäten Pflicht. Bei Neigung zu Seekrankheit empfehlen wir eine Reisetablette vor Abfahrt." }, { "it", "Prelievo tra le 08:00 e le 08:45, durata totale circa 7-8 ore. I giubbotti salvagente sono obbligatori durante i giochi d'acqua. Per chi soffre il mal di mare, si consiglia una pastiglia mezz'ora prima dell'imbarco." }, { "fr", "Ramassage de 08h00 à 08h45, durée totale d'environ 7 à 8 heures. Gilets de sauvetage fournis et obligatoires sur la banane gonflable. Si vous êtes sensible au mal de mer, prenez un cachet préventif avant d'embarquer." }, { "ru", "Выезд из отелей в 08:00 - 08:45, длительность тура около 7-8 часов. Спасательные жилеты выдаются всем и обязательны на водных аттракционах. При склонности к укачиванию примите таблетку от морской болезни за полчаса до отплытия." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193197.jpg", Captions = new Dictionary<string, string> { { "en", "Orange Bay & White Island - Experience" }, { "de", "Orange Bay & White Island – Die Malediven Ägyptens - Erlebnis" }, { "it", "Orange Bay & White Island – I Caraibi del Mar Rosso - Esperienza" }, { "fr", "Orange Bay & White Island – Lagons Turquoise - Expérience" }, { "ru", "Оранж Бэй и Белый Остров — Двойной круиз - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193225.jpg", Captions = new Dictionary<string, string> { { "en", "Orange Bay & White Island - Experience" }, { "de", "Orange Bay & White Island – Die Malediven Ägyptens - Erlebnis" }, { "it", "Orange Bay & White Island – I Caraibi del Mar Rosso - Esperienza" }, { "fr", "Orange Bay & White Island – Lagons Turquoise - Expérience" }, { "ru", "Оранж Бэй и Белый Остров — Двойной круиз - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193251.jpg", Captions = new Dictionary<string, string> { { "en", "Orange Bay & White Island - Experience" }, { "de", "Orange Bay & White Island – Die Malediven Ägyptens - Erlebnis" }, { "it", "Orange Bay & White Island – I Caraibi del Mar Rosso - Esperienza" }, { "fr", "Orange Bay & White Island – Lagons Turquoise - Expérience" }, { "ru", "Оранж Бэй и Белый Остров — Двойной круиз - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193266.jpg", Captions = new Dictionary<string, string> { { "en", "Orange Bay & White Island - Experience" }, { "de", "Orange Bay & White Island – Die Malediven Ägyptens - Erlebnis" }, { "it", "Orange Bay & White Island – I Caraibi del Mar Rosso - Esperienza" }, { "fr", "Orange Bay & White Island – Lagons Turquoise - Expérience" }, { "ru", "Оранж Бэй и Белый Остров — Двойной круиз - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193270.jpg", Captions = new Dictionary<string, string> { { "en", "Orange Bay & White Island - Experience" }, { "de", "Orange Bay & White Island – Die Malediven Ägyptens - Erlebnis" }, { "it", "Orange Bay & White Island – I Caraibi del Mar Rosso - Esperienza" }, { "fr", "Orange Bay & White Island – Lagons Turquoise - Expérience" }, { "ru", "Оранж Бэй и Белый Остров — Двойной круиз - Впечатления" } } } }
