            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Seascope Panorama Boat" }, { "de", "Seascope Panorama-U-Boot & Unterwasserblick" }, { "it", "Battello Panoramico Sottomarino Seascope" }, { "fr", "Bateau Panoramique Sous-Marin Seascope" }, { "ru", "Батискаф Seascope — Панорамная подводная лодка" } },
                Descriptions = new Dictionary<string, string> { { "en", "See the underwater world of the Red Sea without needing to snorkel. The Seascape-style semi-submarine/panoramic boat experience offers underwater viewing through large windows, making it suitable for families, children and guests who prefer to stay dry." }, { "de", "Tauchen Sie trockenen Fußes in die magische Unterwasserwelt des Roten Meeres ein. Das Seascope-Halb-U-Boot bietet durch große Panoramafenster faszinierende Ausblicke auf schillernde Fischschwärme und bunte Korallengärten – ideal für Familien mit Kindern und alle Gäste, die das Meer ohne Schnorcheln erleben möchten." }, { "it", "Ammirate i fondali incantati del Mar Rosso senza bagnarvi. A bordo del semi-sottomarino panoramico Seascope, ampie vetrate sommerse offrono una vista spettacolare sulla vita marina e sulle barriere coralline. Una magnifica avventura adatta a famiglie, bambini e amanti del mare." }, { "fr", "Explorez les merveilles sous-marines de la mer Rouge tout en restant parfaitement au sec. Grâce aux grandes baies vitrées immergées du semi-sous-marin Seascope, contemplez coraux chatoyants et poissons exotiques. Une expérience accessible et captivante pour toute la famille." }, { "ru", "Погрузитесь в чарующий подводный мир Красного моря, оставаясь сухими. Панорамный полубатискаф Seascope оснащен огромными иллюминаторами на глубине, позволяя наблюдать за кораллами и тропическими рыбами. Идеальный познавательный тур для семей с детьми." } },
