                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the Seascope Panorama Semi-Submarine boat experience?" }, { "de", "Was genau ist das Seascope Panorama U-Boot / Halb-U-Boot Erlebnis?" }, { "it", "Che cos'è l'esperienza Seascope Panorama Boat / Semi-sottomarino?" }, { "fr", "Qu'est-ce que l'expérience du bateau semi-sous-marin Seascope Panorama ?" }, { "ru", "Что представляет собой батискаф Seascope Panorama (полуподводная лодка)?" } }, Answers = new Dictionary<string, string> { { "en", "The Seascope is an air-conditioned semi-submarine with large panoramic underwater windows positioned 3 to 4 meters below the sea surface. It provides clear, up-close views of coral reefs, clownfish, rays, and marine life while keeping you completely dry." }, { "de", "Das Seascope ist ein vollklimatisiertes Halb-U-Boot mit riesigen Panoramafenstern ca. 3 bis 4 Meter unter der Wasseroberfläche. Es bietet faszinierende Ausblicke auf Korallenriffe, bunte Fische und Rochen – ganz ohne nass zu werden." }, { "it", "Il Seascope è un'imbarcazione semi-sommergibile climatizzata dotata di ampie vetrate panoramiche a 3-4 metri di profondità. Permette di ammirare da vicino la barriera corallina, pesci pagliaccio e mante rimanendo completamente all'asciutto." }, { "fr", "Le Seascope est un semi-sous-marin climatisé avec de grandes baies vitrées immergées à 3-4 mètres de profondeur. Il permet d'observer les récifs coralliens et la vie marine de très près tout en restant parfaitement au sec." }, { "ru", "Seascope — это кондиционированный батискаф с огромными панорамными иллюминаторами на глубине 3-4 метра. Вы наблюдаете за кораллами, рыбками-клоунами, скатами и морской жизнью через стекло, оставаясь сухими." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is the Seascope Panorama Boat suitable for young children, seniors, and non-swimmers?" }, { "de", "Ist das Seascope Panorama Boot für Kleinkinder, Senioren und Nichtschwimmer geeignet?" }, { "it", "Il Seascope Panorama Boat è adatto a bambini piccoli, anziani e non nuotatori?" }, { "fr", "Le Seascope Panorama Boat est-il adapté aux tout-petits, aux personnes âgées et aux non-nageurs ?" }, { "ru", "Подходит ли батискаф Seascope для малышей, пожилых людей и тех, кто не умеет плавать?" } }, Answers = new Dictionary<string, string> { { "en", "Yes, it is the number one choice for families with toddlers, elderly travelers, and non-swimmers. There is no swimming required; you sit in comfortable swivel seats in the climate-controlled underwater observation deck." }, { "de", "Ja, es ist die perfekte Wahl für Familien mit Kleinkindern, Senioren und Nichtschwimmer. Kein Schwimmen nötig: Sie sitzen bequem in Drehsesseln im klimatisierten Unterwasserdeck und genießen das Riff." }, { "it", "Sì, è la scelta numero uno per famiglie con bambini, persone anziane e non nuotatori. Non serve saper nuotare: ci si siede comodamente in poltroncine nel salone subacqueo con aria condizionata." }, { "fr", "Oui, c'est l'excursion idéale pour les familles avec bébés, les personnes âgées et ceux qui ne nagent pas. Aucune baignade requise : vous êtes confortablement assis dans le salon sous-marin climatisé." }, { "ru", "Да, это лучший вариант для семей с маленькими детьми, пожилых путешественников и тех, кто боится плавать. Никакого погружения в воду: вы сидите в удобных креслах в прохладном подводном салоне." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the duration of the Seascope tour and how often does it run?" }, { "de", "Wie lange dauert die Seascope-Tour und wie oft findet sie statt?" }, { "it", "Quanto dura il tour del Seascope e con quale frequenza si svolge?" }, { "fr", "Quelle est la durée du tour en Seascope et à quelle fréquence a-t-il lieu ?" }, { "ru", "Сколько длится прогулка на Seascope и как часто отправляется батискаф?" } }, Answers = new Dictionary<string, string> { { "en", "The cruise itself lasts about 1.5 to 2 hours, with around 60 to 75 minutes spent observing the coral gardens underwater. Multiple departures are available daily (morning and afternoon), with hotel pickups scheduled roughly 45 minutes before departure." }, { "de", "Die Seefahrt dauert etwa 1,5 bis 2 Stunden, davon ca. 60 bis 75 Minuten Beobachtung der Unterwasserwelt durch die Fenster. Es gibt täglich mehrere Abfahrten morgens und nachmittags." }, { "it", "La navigazione dura circa 1,5-2 ore, di cui 60-75 minuti dedicati all'osservazione subacquea dei banchi corallini. Sono previste più partenze al giorno, al mattino e al pomeriggio." }, { "fr", "La sortie en mer dure environ 1h30 à 2h, dont 60 à 75 minutes passées sous la ligne de flottaison à admirer les coraux. Plusieurs départs sont proposés chaque jour le matin et l'après-midi." }, { "ru", "Морская прогулка длится около 1,5-2 часов, из которых 60-75 минут вы проводите на подводной палубе. Рейсы отправляются ежедневно утром и после полудня, трансфер забирает за 45 минут до старта." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I bring on the Seascope Panorama tour?" }, { "de", "Was sollte ich für die Seascope Panorama Tour mitbringen?" }, { "it", "Cosa portare a bordo del Seascope Panorama?" }, { "fr", "Que faut-il apporter pour l'excursion Seascope Panorama ?" }, { "ru", "Что взять с собой на батискаф Seascope Panorama?" } }, Answers = new Dictionary<string, string> { { "en", "Casual comfortable clothes, sunglasses for the sun deck, a camera or smartphone for underwater photography without glare, and cash for drinks on the upper deck or crew tipping." }, { "de", "Bequeme Freizeitkleidung, Sonnenbrille für das Sonnendeck, Smartphone oder Kamera für spiegelungsfreie Unterwasseraufnahmen sowie etwas Kleingeld für Getränke und Trinkgeld." }, { "it", "Abbigliamento comodo informale, occhiali da sole per il ponte superiore all'aperto, fotocamera per scatti subacquei limpidi e contanti per bevande o mance all'equipaggio." }, { "fr", "Des vêtements confortables, des lunettes pour le pont supérieur en plein air, un appareil photo pour filmer les poissons à travers les vitres et un peu de monnaie pour un rafraîchissement ou un pourboire." }, { "ru", "Удобную легкую одежду, солнцезащитные очки для верхней палубы, телефон для съемки морских обитателей через стекло и наличные на напитки и чаевые." } } } },
