                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What will I see on the Seascope Semi-Submarine in Marsa Alam?" }, { "de", "Was sieht man mit dem Seascope Halb-U-Boot in Marsa Alam?" }, { "it", "Cosa si può avvistare a bordo del Seascope a Marsa Alam?" }, { "fr", "Que peut-on observer à bord du Seascope à Marsa Alam ?" }, { "ru", "Что можно увидеть на полуподводной лодке Seascope в Марса-Аламе?" } }, Answers = new Dictionary<string, string> { { "en", "Marsa Alam is world-famous for its exceptionally preserved virgin coral reefs. Through the underwater panorama windows, guests often observe giant sea turtles, rays, moray eels, and occasionally dugongs (sea cows) swimming freely in their natural habitat." }, { "de", "Marsa Alam ist weltweit bekannt für unberührte Korallenriffe. Durch die Unterwasserfenster sehen Gäste oft riesige Meeresschildkröten, Rochen, Muränen und mit etwas Glück sogar Seekühe (Dugongs) in freier Natur." }, { "it", "Marsa Alam è rinomata nel mondo per la barriera corallina vergine. Attraverso i finestroni sottomarini si possono ammirare grandi tartarughe marine, razze, murene e con un po' di fortuna anche il dugongo." }, { "fr", "Marsa Alam est réputée pour ses récifs coralliens sauvages. À travers les vitres panoramiques, vous observerez souvent des tortues géantes, des raies, des murènes et parfois le dugong dans son habitat naturel." }, { "ru", "Марса-Алам знаменит девственными рифами. Через иллюминаторы гости часто видят гигантских зеленых черепах, скатов, мурен, а иногда и редкую морскую корову (дюгоня) в ее естественной среде обитания." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Marsa Alam Seascope excursion?" }, { "de", "Was ist im Ausflug des Marsa Alam Seascope enthalten?" }, { "it", "Cosa include l'escursione con il Seascope a Marsa Alam?" }, { "fr", "Qu'est-ce qui est inclus dans le Seascope à Marsa Alam ?" }, { "ru", "Что включено в экскурсию на батискафе в Марса-Аламе?" } }, Answers = new Dictionary<string, string> { { "en", "The tour includes air-conditioned hotel transfers from Marsa Alam resorts (or optional Hurghada transfer), the panoramic submarine cruise with marine biology commentary, complimentary soft drinks, and a brief optional guided snorkeling session from the boat stern." }, { "de", "Die Tour beinhaltet klimatisierte Transfers von Marsa-Alam-Hotels, die Panorama-U-Boot-Fahrt mit Erklärungen zur Meeresbiologie, Softdrinks und einen kurzen optionalen Schnorchelstopp vom Heck des Bootes." }, { "it", "Il tour include trasferimenti climatizzati dagli hotel di Marsa Alam, la crociera sul semi-sottomarino panoramico con commento sulla fauna marina, bevande analcoliche e una breve sosta snorkeling facoltativa." }, { "fr", "Le tour comprend les transferts climatisés depuis Marsa Alam, la navigation en semi-sous-marin avec explications sur la faune marine, des rafraîchissements et un arrêt snorkeling facultatif." }, { "ru", "В тур входят трансфер из отелей Марса-Алама на кондиционированном транспорте, прогулка на батискафе с рассказом о морских обитателях, прохладительные напитки и короткая возможность поплавать с маской с кормы." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "How long is the Seascope Marsa Alam tour?" }, { "de", "Wie lange dauert die Seascope-Tour in Marsa Alam?" }, { "it", "Quanto dura l'escursione con il Seascope a Marsa Alam?" }, { "fr", "Combien de temps dure la sortie en Seascope à Marsa Alam ?" }, { "ru", "Какова общая продолжительность экскурсии на батискафе в Марса-Аламе?" } }, Answers = new Dictionary<string, string> { { "en", "The boat trip lasts about 2 hours, and total duration including transfers ranges from 3 to 5 hours depending on your hotel's location along the Marsa Alam coastline." }, { "de", "Die eigentliche Bootsfahrt dauert ca. 2 Stunden. Die Gesamtdauer inklusive Hin- und Rückfahrt liegt je nach Hotellage bei 3 bis 5 Stunden." }, { "it", "La crociera sottomarina dura circa 2 ore. La durata totale, comprensiva dei trasferimenti, varia tra le 3 e le 5 ore a seconda della posizione del vostro resort." }, { "fr", "La traversée sous-marine dure environ 2 heures. La durée totale avec les transferts oscille entre 3 et 5 heures selon l'éloignement de votre hôtel." }, { "ru", "Сама морская прогулка длится около 2 часов. Общее время с учетом трансфера составляет от 3 до 5 часов в зависимости от расположения вашего отеля вдоль побережья." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear and bring for this excursion?" }, { "de", "Was soll ich für diese Exkursion anziehen und mitnehmen?" }, { "it", "Cosa indossare e portare per questa escursione?" }, { "fr", "Que faut-il porter et apporter pour cette excursion ?" }, { "ru", "Что надеть и взять с собой на экскурсию в Марса-Аламе?" } }, Answers = new Dictionary<string, string> { { "en", "Wear comfortable casual attire. If you plan to join the optional snorkeling session at the end, wear a swimsuit underneath and bring a towel. Sunglasses, sun hat, and cash for tipping are recommended." }, { "de", "Bequeme Freizeitkleidung tragen. Falls Sie am optionalen Schnorcheln teilnehmen möchten, Badesachen unterziehen und Handtuch mitnehmen. Sonnenbrille, Kappe und Trinkgeld einstecken." }, { "it", "Indossate abiti comodi. Se desiderate partecipare alla sosta snorkeling facoltativa, indossate il costume e portate un telo mare. Consigliati cappellino, occhiali da sole e contanti per le mance." }, { "fr", "Portez une tenue décontractée. Si vous souhaitez faire la baignade optionnelle, prévoyez un maillot et une serviette. Chapeau de soleil, lunettes et pourboire recommandés." }, { "ru", "Наденьте удобную легкую одежду. Если захотите поплавать во время остановки, наденьте купальник и захватите полотенце. Пригодятся солнцезащитные очки, головной убор и чаевые команде." } } } },
