                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What makes the Safari Boat Hamata trip unique?" }, { "de", "Was macht den Ausflug mit dem Safariboot nach Hamata so besonders?" }, { "it", "Cosa rende unica la crociera Safari Boat Hamata?" }, { "fr", "Qu'est-ce qui rend l'expédition en bateau à Hamata si exceptionnelle ?" }, { "ru", "Чем уникальна морская экспедиция на яхте в Хамату (Hamata Islands)?" } }, Answers = new Dictionary<string, string> { { "en", "Hamata, located in the deep south of Egypt, is known as the 'Egyptian Virgin Maldives'. The tour visits the protected Qulaan archipelago, featuring untouched white-sand islands surrounded by the Red Sea's most vibrant, flourishing coral gardens teeming with tropical fish and dolphins." }, { "de", "Hamata im tiefen Süden Ägyptens gilt als die unberührten Malediven des Roten Meeres. Der Ausflug führt zum Qulaan-Archipel mit einsamen weißen Sandinseln, spektakulären Riffen, bunten Fischschwärmen und Delfinen." }, { "it", "Hamata, nell'estremo sud dell'Egitto, è celebre come l'arcipelago incontaminato delle Qulaan Islands. Un vero paradiso naturale con atolli di sabbia bianca deserta e i banchi corallini più intatti e spettacolari del Mar Rosso." }, { "fr", "Hamata, dans l'extrême sud égyptien, est surnommée les 'Maldives sauvages'. Vous voguerez vers l'archipel préservé de Qulaan, avec ses îles de sable blanc désertes et ses récifs coralliens parmi les plus intacts au monde." }, { "ru", "Хамата на самом юге Египта известна как первозданные египетские Мальдивы. Маршрут проходит по заповедным островам архипелага Кулаан с белоснежными дикими пляжами и нетронутыми рифами, богатыми кораллами, дельфинами и скатами." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the full-day Safari Boat Hamata tour?" }, { "de", "Was ist in der ganztägigen Safariboot-Tour nach Hamata enthalten?" }, { "it", "Cosa è compreso nella giornata intera di Safari Boat Hamata?" }, { "fr", "Qu'est-ce qui est inclus dans cette journée complète en mer à Hamata ?" }, { "ru", "Что входит в стоимость однодневной экспедиции на яхте в Хамату?" } }, Answers = new Dictionary<string, string> { { "en", "The tour includes hotel transfers in comfortable air-conditioned vans, luxury yacht cruising across the marine park, 3 unique guided snorkeling stops around remote islands, national park fees, top-quality snorkeling gear, an open-buffet lunch, and all-day soft drinks, coffee, and tea." }, { "de", "Enthalten sind klimatisierte Transfers, Kreuzfahrt auf einer komfortablen Yacht im Meeres-Nationalpark, 3 geführte Schnorchelstopps an einsamen Inseln, Parkgebühren, hochwertige Schnorchelausrüstung, Mittagsbuffet sowie Heiß- und Kaltgetränke." }, { "it", "Il tour include transfer a/r in minibus climatizzato, crociera su yacht nel parco marino, 3 soste di snorkeling guidato presso isole remote, tasse del parco, kit snorkeling professionale, ricco pranzo a buffet e bevande calde e fredde illimitate." }, { "fr", "L'excursion comprend les transferts en van climatisé, la croisière sur un yacht tout confort, 3 arrêts snorkeling guidés près d'îles désertes, les taxes marines, le matériel de plongée libre, le déjeuner buffet et les boissons à volonté." }, { "ru", "В стоимость входят трансфер на комфортабельном кондиционированном автобусе/минивэне, круиз на яхте по морскому парку, 3 остановки с гидом на диких островах, сборы заповедника, качественное снаряжение для снорклинга, обед 'шведский стол' и напитки весь день." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the departure schedule and duration for Hamata?" }, { "de", "Wie sind die Abfahrtszeiten und die Dauer des Hamata-Ausflugs?" }, { "it", "Quali sono gli orari e la durata della gita a Hamata?" }, { "fr", "Quels sont les horaires et la durée du voyage vers Hamata ?" }, { "ru", "Каковы время отправления и общая продолжительность поездки в Хамату?" } }, Answers = new Dictionary<string, string> { { "en", "Because Hamata lies in the pristine deep south, pickups start early around 05:30 to 06:30 AM from Marsa Alam (or earlier from Hurghada). The full-day expedition lasts approximately 10 to 12 hours, returning in the early evening around 17:30 to 18:30 PM." }, { "de", "Da Hamata im unberührten Süden liegt, beginnt die Abholung früh zwischen 05:30 und 06:30 Uhr ab Marsa Alam (bzw. früher ab Hurghada). Der Tagesausflug dauert ca. 10 bis 12 Stunden mit Rückkehr gegen 18:00 Uhr." }, { "it", "Poiché Hamata si trova nell'estremo sud, il prelievo comincia presto (05:30 - 06:30 da Marsa Alam, prima se da Hurghada). È un'avventura full-day di circa 10-12 ore, con rientro in hotel verso le 17:30-18:30." }, { "fr", "Hamata se trouvant au grand sud sauvage, le ramassage commence tôt, vers 05h30 - 06h30 depuis Marsa Alam. Cette expédition complète dure environ 10 à 12 heures pour un retour à l'hôtel vers 18h00." }, { "ru", "Поскольку Хамата расположена на дальнем юге, выезд ранний — около 05:30-06:30 из Марса-Алама (из Хургады раньше). Экспедиция на весь день занимает 10-12 часов, возвращение в отель к 17:30-18:30." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I pack for the Hamata boat safari?" }, { "de", "Was sollte ich für die Hamata-Bootsafari einpacken?" }, { "it", "Cosa portare per la crociera alle isole di Hamata?" }, { "fr", "Que faut-il emporter pour ce safari marin à Hamata ?" }, { "ru", "Что взять с собой в морскую экспедицию в Хамату?" } }, Answers = new Dictionary<string, string> { { "en", "Bring your passport copies (required by Coast Guard), hotel breakfast box (order at reception the evening before), beach towels, sunscreen, sunglasses, a hat, a windbreaker jacket for the morning drive, and an underwater camera or GoPro." }, { "de", "Bringen Sie Passkopien mit (Küstenwachen-Vorschrift), eine Frühstücksbox aus dem Hotel (am Vorabend an der Rezeption bestellen), Strandtücher, Sonnencreme, Sonnenbrille, eine Windjacke für den Morgen und eine Unterwasserkamera." }, { "it", "Portate copie dei passaporti (richieste dalla Guardia Costiera), cestino colazione dell'hotel (da richiedere la sera prima), teli mare, crema solare, occhiali, giacca a vento leggera per il mattino e una GoPro." }, { "fr", "Prenez des copies de passeports (contrôle des garde-côtes), une box petit-déjeuner de l'hôtel, serviettes, crème solaire, lunettes de soleil, coupe-vent pour le matin et une caméra sous-marine." }, { "ru", "Возьмите копии паспортов (требование береговой охраны), ланч-бокс с завтраком из отеля (закажите на ресепшн накануне), полотенца, крем от загара, ветровку для утренней дороги и экшн-камеру GoPro." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193249.jpg", Captions = new Dictionary<string, string> { { "en", "Safari Boat Hamata - Experience" }, { "de", "Safari-Boot Hamata – Exklusive Riff-Expedition - Erlebnis" }, { "it", "Spedizione in Barca Safari a Hamata - Esperienza" }, { "fr", "Expédition Safari en Bateau à Hamata - Expérience" }, { "ru", "Морское сафари на острова Хамата - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193250.jpg", Captions = new Dictionary<string, string> { { "en", "Safari Boat Hamata - Experience" }, { "de", "Safari-Boot Hamata – Exklusive Riff-Expedition - Erlebnis" }, { "it", "Spedizione in Barca Safari a Hamata - Esperienza" }, { "fr", "Expédition Safari en Bateau à Hamata - Expérience" }, { "ru", "Морское сафари на острова Хамата - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193251.jpg", Captions = new Dictionary<string, string> { { "en", "Safari Boat Hamata - Experience" }, { "de", "Safari-Boot Hamata – Exklusive Riff-Expedition - Erlebnis" }, { "it", "Spedizione in Barca Safari a Hamata - Esperienza" }, { "fr", "Expédition Safari en Bateau à Hamata - Expérience" }, { "ru", "Морское сафари на острова Хамата - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Speed Boat" }, { "de", "Privates Schnellboot-Abenteuer" }, { "it", "Motoscafo Privato – Avventura nel Mar Rosso" }, { "fr", "Aventure Privée en Hors-Bord" }, { "ru", "Индивидуальный скоростной катер" } },
                Descriptions = new Dictionary<string, string> { { "en", "Enjoy a faster, more private-feeling Red Sea adventure aboard a speedboat. The route can be tailored around snorkeling, dolphin-search areas or selected islands depending on the booked package, weather and sea conditions." }, { "de", "Erleben Sie die Freiheit des Roten Meeres mit Stil und Geschwindigkeit an Bord eines privaten Schnellboots. Gestalten Sie Ihre Route flexibel – ob Delfinbeobachtung in freier Wildbahn, abgelegene Schnorchelreviere oder malerische Inselbuchten, ganz nach Ihren Wünschen." }, { "it", "Vivete l'emozione del Mar Rosso in totale privacy ed esclusività a bordo di un moderno motoscafo veloce. L'itinerario può essere personalizzato tra ricerca dei delfini, soste snorkeling nelle baie più nascoste e soste sulle isole circostanti." }, { "fr", "Vivez une expérience maritime rapide, privée et privilégiée à bord d'un hors-bord moderne. Personnalisez votre itinéraire selon vos envies : rencontre avec les dauphins sauvages, spots de snorkeling secrets ou haltes sur des îles paradisiaques." }, { "ru", "Почувствуйте динамику и приватность в морском круизе на скоростном катере. Индивидуальный маршрут с возможностью поиска диких дельфинов, уединенного снорклинга на лучших рифах и высадки на живописных островах Красного моря." } },
