                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What does the Speed Boat adventure include and where do we go?" }, { "de", "Was beinhaltet das Speedboot-Abenteuer und welche Route wird gefahren?" }, { "it", "Cosa comprende l'avventura in motoscafo veloce e dove si va?" }, { "fr", "Que comprend la sortie en vedette rapide (Speed Boat) et quel est l'itinéraire ?" }, { "ru", "Что входит в прогулку на скоростном катере (Speed Boat) и куда мы плывем?" } }, Answers = new Dictionary<string, string> { { "en", "The Speed Boat trip includes private or small-group transfer, life jackets, an experienced skipper, snorkeling equipment, fresh fruit, and chilled beverages. Depending on your choice and sea conditions, routes can visit Giftun Island beaches, search for wild dolphin pods, or explore secluded coral reefs." }, { "de", "Der Speedboot-Ausflug umfasst Hoteltransfer, Schwimmwesten, erfahrenen Skipper, Schnorchelausrüstung, frische Früchte und gekühlte Getränke. Die Route kann flexibel gestaltet werden: Delfinbeobachtung im offenen Meer, Traumstrände der Giftun-Inseln oder einsame Riffe." }, { "it", "L'uscita in motoscafo veloce include transfer, salvagenti, skipper esperto, kit snorkeling, frutta fresca e bibite fresche. La rotta è personalizzabile: avvistamento delfini in mare aperto, soste alle spiagge delle isole Giftun o snorkeling su barriere isolate." }, { "fr", "L'excursion en bateau rapide comprend les transferts, gilets, skipper professionnel, matériel de snorkeling, fruits frais et boissons fraîches. Selon vos envies et la météo : observation des dauphins sauvages, bancs de sable ou îles Giftun." }, { "ru", "Прогулка на скоростном катере включает трансфер, спасжилеты, опытного капитана, снаряжение для снорклинга, свежие фрукты и напитки. Маршрут можно настроить: поиск диких дельфинов в открытом море, пляжи островов Гифтун или уединенные коралловые рифы." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "How long is the Speed Boat trip and is it flexible?" }, { "de", "Wie lange dauert die Speedboot-Fahrt und ist sie flexibel?" }, { "it", "Quanto dura il tour in motoscafo ed è personalizzabile?" }, { "fr", "Quelle est la durée de la virée en Speed Boat et est-ce modulable ?" }, { "ru", "Сколько длится катание на катере и можно ли скорректировать маршрут?" } }, Answers = new Dictionary<string, string> { { "en", "Standard tours run for 2 to 4 hours. Because speed boats move much faster than regular day boats, you reach pristine spots in 15 to 20 minutes with zero waiting and flexible timing tailored to your schedule." }, { "de", "Die Standardtouren dauern zwischen 2 und 4 Stunden. Da das Speedboot viel schneller ist als Ausflugsschiffe, erreichen Sie die schönsten Schnorchelplätze in nur 15 bis 20 Minuten ganz ohne Wartezeiten." }, { "it", "I tour standard durano da 2 a 4 ore. Muovendosi a velocità sostenuta, si raggiungono gli atolli e i punti migliori in soli 15-20 minuti, risparmiando ore di navigazione e con massima flessibilità." }, { "fr", "Les sorties classiques durent de 2 à 4 heures. La vitesse permet d'atteindre les plus beaux spots en seulement 15 à 20 minutes, sans perte de temps et avec une flexibilité totale selon vos envies." }, { "ru", "Стандартная поездка длится от 2 до 4 часов. За счет высокой скорости катер долетает до лучших рифов и островов всего за 15-20 минут, без очередей и с максимальной гибкостью графика." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Who should avoid the speed boat trip for health reasons?" }, { "de", "Wer sollte aus gesundheitlichen Gründen auf die Speedboot-Fahrt verzichten?" }, { "it", "Chi dovrebbe evitare il motoscafo veloce per motivi di salute?" }, { "fr", "Qui devrait éviter la vedette rapide pour des raisons de santé ?" }, { "ru", "Кому не рекомендуется поездка на скоростном катере по состоянию здоровья?" } }, Answers = new Dictionary<string, string> { { "en", "Due to bumpy waves and high acceleration, speed boats are not recommended for pregnant women, individuals with acute back, neck, or spine problems, or children under 3 years old." }, { "de", "Aufgrund des Wellengangs und der hohen Beschleunigung ist die Fahrt für Schwangere, Personen mit akuten Rücken- oder Nackenbeschwerden sowie Kleinkinder unter 3 Jahren nicht geeignet." }, { "it", "A causa dei sobbalzi sulle onde e della velocità, il motoscafo è sconsigliato a donne in gravidanza, persone con gravi problemi alla schiena o al collo e bambini sotto i 3 anni." }, { "fr", "En raison des vagues et de la vitesse, cette activité est déconseillée aux femmes enceintes, aux personnes souffrant de problèmes de dos ou de cervicales, et aux enfants de moins de 3 ans." }, { "ru", "Из-за резких ударов о волны и скорости прогулка на быстроходном катере не рекомендуется беременным женщинам, людям с травмами позвоночника и спины, а также детям младше 3 лет." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I bring on the Speed Boat?" }, { "de", "Was sollte man auf das Speedboot mitnehmen?" }, { "it", "Cosa portare a bordo del motoscafo?" }, { "fr", "Que faut-il emporter sur le Speed Boat ?" }, { "ru", "Что взять с собой на скоростной катер?" } }, Answers = new Dictionary<string, string> { { "en", "Wear your swimwear and bring secure sunglasses (with strap), reef-safe sunscreen, a beach towel, and a waterproof phone pouch or strapped GoPro to avoid losing devices when cruising at high speed." }, { "de", "Tragen Sie Badekleidung und nehmen Sie eine gut sitzende Sonnenbrille (evtl. mit Band), Sonnencreme, Strandtuch und eine gesicherte wasserdichte Handyhülle oder GoPro mit." }, { "it", "Indossate il costume e portate occhiali da sole ben saldi (meglio con laccetto), crema solare, telo mare e custodia impermeabile legata al polso per non rischiare di far cadere il telefono." }, { "fr", "Portez votre maillot et prévoyez des lunettes bien ajustées, crème solaire, serviette de plage et une pochette étanche avec dragonne pour sécuriser votre smartphone face au vent et aux embruns." }, { "ru", "Наденьте купальник, возьмите солнцезащитные очки с фиксирующим шнурком, полотенце, крем от солнца и надежный водонепроницаемый чехол с ремешком на руку для телефона." } } } },
                Addons = new List<TourAddon>(),
