            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Speed Boat Sunset Private" }, { "de", "Privater Sonnenuntergangs-Bootsausflug" }, { "it", "Crociera Privata al Tramonto in Motoscafo" }, { "fr", "Croisière Privée au Coucher du Soleil en Hors-Bord" }, { "ru", "Индивидуальный круиз на закате на скоростном катере" } },
                Descriptions = new Dictionary<string, string> { { "en", "A private sunset cruise along the Red Sea coast, designed for couples, families or small groups. Enjoy the sea breeze, golden-hour views and a relaxed private-boat atmosphere while watching the sun set over the coast." }, { "de", "Eine romantische private Abendfahrt entlang der Küste des Roten Meeres, ideal für Paare und Familien. Genießen Sie die sanfte Meeresbrise, edle Atmosphäre und spektakuläre Ausblicke, während die Sonne die Wüstenberge und das Meer in warmes Gold taucht." }, { "it", "Un'esclusiva crociera privata al tramonto lungo la costa del Mar Rosso, pensata per coppie, famiglie o piccoli gruppi. Lasciatevi cullare dalla brezza serale ammirando i colori dorati del cielo e del mare in un'atmosfera intima e raffinata." }, { "fr", "Une croisière privée empreinte de romantisme au coucher du soleil le long des côtes de la mer Rouge. Idéal pour les couples ou les petits groupes, profitez de la brise marine et de la lumière dorée dans une atmosphère feutrée et intimiste." }, { "ru", "Романтический индивидуальный круиз на закате вдоль побережья Красного моря. Насладитесь легким морским бризом, золотыми красками заходящего солнца над горами и уединенной атмосферой на борту скоростного катера." } },
