                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Private Sunset Speed Boat tour?" }, { "de", "Was ist in der privaten Sonnenuntergangs-Speedboot-Tour enthalten?" }, { "it", "Cosa include il tour privato in motoscafo al tramonto?" }, { "fr", "Qu'est-ce qui est inclus dans le tour privé en Speed Boat au coucher du soleil ?" }, { "ru", "Что входит в индивидуальную прогулку на скоростном катере на закате?" } }, Answers = new Dictionary<string, string> { { "en", "This romantic VIP cruise includes private round-trip hotel transfers, exclusive use of the modern speedboat with captain, a fresh tropical fruit platter, soft drinks and sparkling water, sound system for your own music, and stops for golden-hour photos and a sunset swim." }, { "de", "Diese romantische VIP-Fahrt beinhaltet privaten Hoteltransfer, die exklusive Nutzung des modernen Speedboots mit Skipper, einen frischen tropischen Obstteller, gekühlte Erfrischungsgetränke, Bluetooth-Soundsystem für Ihre Musik sowie Fotostopps im Abendlicht und Sonnenuntergangsschwimmen." }, { "it", "Questa romantica crociera VIP include transfer privati dall'hotel, uso esclusivo del motoscafo con skipper dedicato, piatto di frutta fresca tropicale, bevande fresche, impianto stereo per la vostra musica e soste per scatti al tramonto e un bagno nella luce dorata." }, { "fr", "Cette sortie VIP romantique inclut les transferts privés, la privatisation complète du bateau rapide avec capitaine, une corbeille de fruits frais, rafraîchissements, sonorisation pour votre musique et arrêts baignade/photos au coucher du soleil." }, { "ru", "Этот романтический VIP-круиз включает индивидуальный трансфер из отеля, приватную аренду катера с капитаном, тарелку свежих тропических фруктов, прохладительные напитки, Bluetooth-колонку для вашей музыки и остановку для купания в лучах заката." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What are the timings for the sunset cruise?" }, { "de", "Wie sind die Zeiten für die Sonnenuntergangs-Fahrt?" }, { "it", "Quali sono gli orari della crociera al tramonto?" }, { "fr", "Quels sont les horaires de la croisière au coucher du soleil ?" }, { "ru", "В какое время проводится закатный круиз на катере?" } }, Answers = new Dictionary<string, string> { { "en", "Pickup is typically around 16:00 to 16:30 PM (adjusted seasonally according to sunset time). You cruise for 2 to 3 hours, catching the golden hour and twilight, and return to your hotel around 19:00 to 19:30 PM." }, { "de", "Die Abholung erfolgt meist zwischen 16:00 und 16:30 Uhr (saisonal an den Sonnenuntergang angepasst). Die Fahrt dauert ca. 2 bis 3 Stunden und Sie kehren gegen 19:00 bis 19:30 Uhr zurück." }, { "it", "Il prelievo avviene solitamente tra le 16:00 e le 16:30 (adattato stagionalmente all'ora del tramonto). Si naviga per 2-3 ore rientrando in hotel verso le 19:00 - 19:30." }, { "fr", "Le départ se fait généralement entre 16h00 et 16h30 (ajusté selon la saison). La balade dure de 2 à 3 heures avec un retour à l'hôtel vers 19h00 - 19h30." }, { "ru", "Выезд из отеля обычно в 16:00 - 16:30 (время корректируется по сезону заката солнца). Прогулка длится 2-3 часа, возвращение в отель к 19:00 - 19:30." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is this tour recommended for couples, anniversaries, or proposals?" }, { "de", "Ist diese Tour für Paare, Jubiläen oder Heiratsanträge geeignet?" }, { "it", "Questo tour è consigliato per coppie, anniversari o proposte di matrimonio?" }, { "fr", "Ce tour est-il conseillé pour les couples, anniversaires ou demandes en mariage ?" }, { "ru", "Подходит ли эта поездка для пар, романтических дат и предложения руки и сердца?" } }, Answers = new Dictionary<string, string> { { "en", "Absolutely! It is our top-rated romantic experience in Hurghada. The secluded atmosphere, mountain silhouette at sunset, and golden waters provide the perfect intimate backdrop for birthdays, proposals, and honeymooners." }, { "de", "Absolut! Es ist unser beliebtestes romantisches Erlebnis in Hurghada. Die private Atmosphäre, die Bergsilhouette im Abendlicht und das glitzernde Meer bieten den perfekten Rahmen für Heiratsanträge und Hochzeitsreisen." }, { "it", "Assolutamente sì! È la nostra esperienza romantica più richiesta a Hurghada. La privacy totale, il profilo delle montagne che si specchiano nel mare dorato creano la scenografia perfetta per proposte di nozze e anniversari." }, { "fr", "Absolument ! C'est notre expérience romantique par excellence à Hurghada. L'intimité du bateau, le soleil plongeant derrière les montagnes et l'eau scintillante offrent un cadre féerique pour une demande en mariage ou une lune de miel." }, { "ru", "Безусловно! Это одна из самых романтичных экскурсий в Хургаде. Полная уединенность, силуэты гор на фоне заката и золото морских волн создают идеальную атмосферу для предложения руки и сердца, медового месяца или годовщины." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear and bring on the private sunset boat?" }, { "de", "Was sollte man für das private Sonnenuntergangsboot anziehen und mitbringen?" }, { "it", "Cosa indossare e portare per la crociera privata al tramonto?" }, { "fr", "Que faut-il porter et apporter pour cette sortie privée au coucher du soleil ?" }, { "ru", "Что надеть и взять с собой на индивидуальный закатный катер?" } }, Answers = new Dictionary<string, string> { { "en", "Dress in chic resort wear or casual evening beach clothes. Bring swimwear and a towel if you wish to take a dip, sunglasses for the first hour, a light jacket or pashmina for the sea breeze after sunset, and your camera." }, { "de", "Elegante Resort- oder leichte Freizeitkleidung. Badekleidung und Handtuch einpacken, falls Sie schwimmen möchten, eine Sonnenbrille für den Anfang und eine leichte Strickjacke für die Brise nach Sonnenuntergang." }, { "it", "Abbigliamento da resort fresco ed elegante. Portate costume e telo se desiderate fare il bagno, occhiali da sole e un coprispalle o giacca leggera per la brezza marina serale dopo il calare del sole." }, { "fr", "Une jolie tenue de vacances décontractée ou chic. Prenez un maillot et une serviette si vous souhaitez plonger dans l'eau tiède, des lunettes de soleil et un châle léger pour la fraîcheur en mer au crépuscule." }, { "ru", "Красивую летнюю курортную одежду для памятных фотографий. Возьмите купальник и полотенце для купания, солнцезащитные очки и легкую накидку или кофту, так как после захода солнца на воде свежеет." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193258.jpg", Captions = new Dictionary<string, string> { { "en", "Speed Boat Sunset Private - Experience" }, { "de", "Privater Sonnenuntergangs-Bootsausflug - Erlebnis" }, { "it", "Crociera Privata al Tramonto in Motoscafo - Esperienza" }, { "fr", "Croisière Privée au Coucher du Soleil en Hors-Bord - Expérience" }, { "ru", "Индивидуальный круиз на закате на скоростном катере - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193266.jpg", Captions = new Dictionary<string, string> { { "en", "Speed Boat Sunset Private - Experience" }, { "de", "Privater Sonnenuntergangs-Bootsausflug - Erlebnis" }, { "it", "Crociera Privata al Tramonto in Motoscafo - Esperienza" }, { "fr", "Croisière Privée au Coucher du Soleil en Hors-Bord - Expérience" }, { "ru", "Индивидуальный круиз на закате на скоростном катере - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193268.jpg", Captions = new Dictionary<string, string> { { "en", "Speed Boat Sunset Private - Experience" }, { "de", "Privater Sonnenuntergangs-Bootsausflug - Erlebnis" }, { "it", "Crociera Privata al Tramonto in Motoscafo - Esperienza" }, { "fr", "Croisière Privée au Coucher du Soleil en Hors-Bord - Expérience" }, { "ru", "Индивидуальный круиз на закате на скоростном катере - Впечатления" } } } }
