            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Dolphin Show" }, { "de", "Delfin-Show Hurghada" }, { "it", "Spettacolo dei Delfini ad Hurghada" }, { "fr", "Spectacle Féerique des Dauphins" }, { "ru", "Шоу дельфинов в Хургаде" } },
                Descriptions = new Dictionary<string, string> { { "en", "Enjoy a family-friendly dolphin presentation featuring trained dolphins and professional handlers. The show offers close-up viewing and educational-style interaction from designated spectator areas." }, { "de", "Erleben Sie eine faszinierende und herzerwärmende Delfin-Show für die ganze Familie. Bewundern Sie die Intelligenz, Akrobatik und Anmut der dressierten Delfine und Seelöwen aus nächster Nähe in einer modernen Showarena." }, { "it", "Un entusiasmante spettacolo per tutta la famiglia con protagonisti magnifici delfini ed esperti addestratori. Ammirate l'agilità, l'intelligenza e le acrobazie di questi straordinari mammiferi marini da comode postazioni panoramiche." }, { "fr", "Assistez à un spectacle captivant et familial mettant en scène d'admirables dauphins sous la conduite de dresseurs professionnels. Un moment d'émerveillement et d'acrobaties marines à savourer depuis des gradins confortables." }, { "ru", "Захватывающее семейное представление с участием грациозных дельфинов и морских котиков. Удивительные трюки, артистизм животных и профессиональное мастерство тренеров подарят яркие эмоции взрослым и детям." } },
                Price = 15,
                Currency = "EUR",
                Duration = "Approx. 1-1.5 hours",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000011"),
                CategoryId = Guid.Parse("00000000-0000-0000-0000-000000000006"),
