                ImageUrl = "/images/tours/5861626853276193191.jpg",
                MediaUrls = new List<string> { "/images/tours/5861626853276193191.jpg", "/images/tours/5861626853276193195.jpg", "/images/tours/5861626853276193210.jpg" },
                ReserveAndPayLater = true,
