                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Dolphin Show excursion?" }, { "de", "Was ist im Ausflug zur Delfinshow enthalten?" }, { "it", "Cosa include l'escursione per lo spettacolo dei delfini?" }, { "fr", "Qu'est-ce qui est inclus dans l'excursion au spectacle de dauphins ?" }, { "ru", "Что входит в экскурсию на дельфин-шоу?" } }, Answers = new Dictionary<string, string> { { "en", "The excursion includes round-trip air-conditioned hotel transfers and standard entry tickets to the 60-minute spectacular dolphin and marine mammal performance featuring trained dolphins, sea lions, and seals performing acrobatics, dances, and tricks." }, { "de", "Der Ausflug beinhaltet den klimatisierten Hin- und Rücktransfer vom Hotel sowie reguläre Eintrittskarten zur ca. 60-minütigen Show mit trainierten Delfinen, Seelöwen und Robben voller Akrobatik, Sprünge und Kunststücke." }, { "it", "Il tour comprende trasferimenti a/r in minibus climatizzato dall'hotel e biglietti d'ingresso per lo spettacolo di circa 60 minuti con delfini addestrati, leoni marini e foche che si esibiscono in acrobazie, salti e giochi interattivi." }, { "fr", "L'excursion comprend les transferts aller-retour climatisés depuis l'hôtel et les billets d'entrée au spectacle d'une heure mettant en vedette des dauphins, otaries et phoques exécutant sauts spectaculaires et chorégraphies." }, { "ru", "В стоимость входят трансфер из отеля и обратно на комфортабельном кондиционированном транспорте и входной билет на часовое шоу дельфинов, морских котиков и морских львов с акробатическими трюками и номерами." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Can I take photos and are photo sessions with dolphins available?" }, { "de", "Darf man fotografieren und gibt es Fotoshootings mit den Delfinen?" }, { "it", "È possibile scattare foto e fare foto ricordo con i delfini?" }, { "fr", "Peut-on prendre des photos et faire une séance photo avec les dauphins ?" }, { "ru", "Можно ли фотографировать и сфотографироваться с дельфинами?" } }, Answers = new Dictionary<string, string> { { "en", "You can take photos and videos from your seat with your phone at no extra charge. After the show, the dolphinarium offers professional photo sessions right by the pool edge where you can pose with the dolphins (available for an extra fee paid directly on-site)." }, { "de", "Sie können während der Show vom Sitzplatz aus kostenlos Fotos und Videos mit Ihrem Smartphone aufnehmen. Nach der Vorstellung bietet das Delphinarium professionelle Fototermine am Beckenrand gegen Aufpreis an." }, { "it", "Potete scattare foto e girare video dal vostro posto con il telefono gratuitamente. Al termine dello show, la struttura organizza foto professionali a bordo vasca accanto ai delfini (servizio extra acquistabile sul posto)." }, { "fr", "Vous pouvez prendre photos et vidéos depuis votre siège sans frais. Après le spectacle, des photographes professionnels proposent des séances souvenirs au bord du bassin avec les dauphins (en supplément sur place)." }, { "ru", "Вы можете свободно снимать фото и видео со своего зрительского места на телефон. После шоу можно сделать памятное фото с дельфином у бассейна с профессиональным фотографом (оплачивается дополнительно на месте)." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the schedule and total duration of the Dolphin Show tour?" }, { "de", "Wie ist der Zeitplan und die Gesamtdauer des Ausflugs?" }, { "it", "Quali sono gli orari e la durata complessiva del tour?" }, { "fr", "Quels sont les horaires et la durée globale de la sortie ?" }, { "ru", "Каковы расписание и общая продолжительность поездки на дельфин-шоу?" } }, Answers = new Dictionary<string, string> { { "en", "Hotel pickups typically occur in the early afternoon (around 13:30 to 14:15 PM) depending on your hotel. The show itself lasts 1 hour, and total duration with transportation is approximately 2.5 to 3 hours." }, { "de", "Die Abholung im Hotel erfolgt meist am frühen Nachmittag (ca. 13:30 bis 14:15 Uhr). Die Show dauert etwa 60 Minuten, die gesamte Tourdauer inklusive Transfer beträgt ca. 2,5 bis 3 Stunden." }, { "it", "Il prelievo in hotel avviene solitamente nel primo pomeriggio (tra le 13:30 e le 14:15). Lo spettacolo dura 1 ora, mentre l'intera escursione comprensiva dei transfer dura circa 2,5 - 3 ore." }, { "fr", "La navette passe en début d'après-midi (vers 13h30 - 14h15). Le spectacle dure 1 heure et l'excursion complète avec trajets dure environ 2h30 à 3 heures." }, { "ru", "Трансфер забирает туристов в первой половине дня или после обеда (обычно 13:30 - 14:15). Шоу длится 1 час, общее время с дорогой — около 2,5 - 3 часов." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is the venue wheelchair accessible and stroller friendly?" }, { "de", "Ist die Anlage barrierefrei für Rollstühle und Kinderwagen geeignet?" }, { "it", "La struttura è accessibile con sedie a rotelle e passeggini?" }, { "fr", "Le lieu est-il accessible aux poussettes et aux personnes à mobilité réduite ?" }, { "ru", "Удобна ли арена дельфинария для детских и инвалидных колясок?" } }, Answers = new Dictionary<string, string> { { "en", "Yes, the dolphinarium features step-free ramp access, wide corridors, and designated spaces for strollers and wheelchairs, making it very comfortable for families and seniors." }, { "de", "Ja, das Delphinarium verfügt über Rampen, breite Gänge und ausgewiesene Stellplätze für Kinderwagen und Rollstühle – ideal für Familien mit Kleinkindern und mobilitätseingeschränkte Gäste." }, { "it", "Sì, il delfinario è provvisto di rampe d'accesso senza gradini, ampi corridoi e aree dedicate a passeggini e carrozzine, garantendo la massima comodità per tutti." }, { "fr", "Oui, le delphinarium dispose de rampes d'accès, d'allées larges et d'emplacements prévus pour les poussettes et fauteuils roulants, assurant une visite aisée pour tous." }, { "ru", "Да, на территории дельфинария оборудованы удобные пандусы, широкие проходы и места для детских и инвалидных колясок." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193191.jpg", Captions = new Dictionary<string, string> { { "en", "Dolphin Show - Experience" }, { "de", "Delfin-Show Hurghada - Erlebnis" }, { "it", "Spettacolo dei Delfini ad Hurghada - Esperienza" }, { "fr", "Spectacle Féerique des Dauphins - Expérience" }, { "ru", "Шоу дельфинов в Хургаде - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193195.jpg", Captions = new Dictionary<string, string> { { "en", "Dolphin Show - Experience" }, { "de", "Delfin-Show Hurghada - Erlebnis" }, { "it", "Spettacolo dei Delfini ad Hurghada - Esperienza" }, { "fr", "Spectacle Féerique des Dauphins - Expérience" }, { "ru", "Шоу дельфинов в Хургаде - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193210.jpg", Captions = new Dictionary<string, string> { { "en", "Dolphin Show - Experience" }, { "de", "Delfin-Show Hurghada - Erlebnis" }, { "it", "Spettacolo dei Delfini ad Hurghada - Esperienza" }, { "fr", "Spectacle Féerique des Dauphins - Expérience" }, { "ru", "Шоу дельфинов в Хургаде - Впечатления" } } } }
