            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Swim with Dolphin" }, { "de", "Schwimmen mit Delfinen" }, { "it", "Nuoto con i Delfini – Incontro Esclusivo" }, { "fr", "Nage Privilégiée avec les Dauphins" }, { "ru", "Плавание с дельфинами" } },
                Descriptions = new Dictionary<string, string> { { "en", "A supervised dolphin encounter offering guests the opportunity to enter the water with dolphins under professional staff guidance. The programme is designed around controlled interaction and safety procedures." }, { "de", "Erfüllen Sie sich einen Lebenstraum und begegnen Sie sanftmütigen Delfinen direkt im Wasser. Begleitet von erfahrenen Trainern bietet diese betreute Interaktion ein sicheres, unvergessliches und emotionales Erlebnis in harmonischer Umgebung." }, { "it", "Realizzate il sogno di nuotare a stretto contatto con i delfini in un ambiente protetto e professionale. Guidati da istruttori qualificati, vivrete un'interazione emozionante e sicura, creando ricordi indimenticabili." }, { "fr", "Réalisez un rêve d'enfant en nageant au plus près des dauphins sous la supervision bienveillante d'entraîneurs qualifiés. Un moment d'émotion pure et de complicité avec ces animaux marins d'exception, dans le respect total des règles de sécurité." }, { "ru", "Осуществите заветную мечту — прикоснитесь к миру дельфинов и поплавайте рядом с ними в бассейне под руководством опытных инструкторов. Безопасный, глубоко эмоциональный и незабываемый контакт с самыми дружелюбными обитателями океана." } },
                Price = 55,
