                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Swim with Dolphin program?" }, { "de", "Was ist im Programm 'Schwimmen mit Delfinen' enthalten?" }, { "it", "Cosa comprende il programma 'Nuoto con i delfini'?" }, { "fr", "Qu'est-ce qui est inclus dans le programme de nage avec les dauphins ?" }, { "ru", "Что входит в программу 'Плавание с дельфинами'?" } }, Answers = new Dictionary<string, string> { { "en", "The experience includes private or small-group hotel transfers, entry to the specialized dolphin pool facility, a safety briefing with an expert marine trainer, flotation vest, and an interactive in-water swim session (5, 10, or 15 minutes as selected upon booking) where you touch, dance, and swim alongside gentle dolphins." }, { "de", "Das Erlebnis umfasst Hoteltransfers, Zugang zum speziellen Schwimmbecken, eine Sicherheitseinweisung durch erfahrene Trainer, Schwimmweste und das gebuchte Wasser-Interaktionsprogramm (5, 10 oder 15 Min.), bei dem Sie mit den zutraulichen Tieren schwimmen, tanzen und sie streicheln." }, { "it", "L'esperienza include transfer a/r dall'hotel, accesso alla vasca dedicata, briefing di sicurezza con istruttori qualificati, giubbotto di galleggiamento e la sessione in acqua scelta (5, 10 o 15 minuti) per nuotare, accarezzare e interagire a tu per tu con i delfini." }, { "fr", "L'activité comprend les transferts hôtel, l'accès au bassin dédié, un briefing avec un soigneur professionnel, un gilet de flottabilité et la session dans l'eau (5, 10 ou 15 min selon l'option choisie) pour caresser, nager et jouer avec les dauphins." }, { "ru", "В тур входят трансфер из отеля, инструктаж по технике безопасности с профессиональным тренером, спасательный жилет и непосредственное плавание в бассейне с дельфинами (выбранная длительность 5, 10 или 15 минут), во время которого вы можете гладить дельфинов, держаться за плавники и плавать рядом." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear and bring for swimming with dolphins?" }, { "de", "Was sollte ich für das Schwimmen mit Delfinen anziehen und mitbringen?" }, { "it", "Cosa portare e come vestirsi per nuotare con i delfini?" }, { "fr", "Que faut-il porter et apporter pour nager avec les dauphins ?" }, { "ru", "Что нужно взять с собой и какая форма одежды для купания с дельфинами?" } }, Answers = new Dictionary<string, string> { { "en", "Bring your swimwear, a dry towel from your hotel, dry change of clothes, and flip-flops. Important: Remove all jewellery, watches, rings, and sharp accessories before entering the water to protect the delicate skin of the dolphins." }, { "de", "Bringen Sie Badekleidung, ein Handtuch aus dem Hotel, Wechselkleidung und Badeschlappen mit. Wichtig: Bitte legen Sie vor dem Betreten des Beckens jeglichen Schmuck, Uhren und Ringe ab, um die empfindliche Haut der Delfine nicht zu verletzen." }, { "it", "Portate costume da bagno, telo dell'hotel, cambio asciutto e ciabatte. Importante: prima di entrare in acqua occorre togliere anelli, collane, orologi e bracciali per non rischiare di graffiare la pelle delicata dei delfini." }, { "fr", "Apportez maillot de bain, serviette d'hôtel, vêtements de rechange et tongs. Important : enlevez impérativement tous vos bijoux, montres et bagues avant d'aller dans l'eau afin de préserver la peau sensible des dauphins." }, { "ru", "Возьмите купальник, отельное полотенце, сменную сухую одежду и сланцы. Важное правило: перед заходом в бассейн необходимо обязательно снять все кольца, браслеты, часы и цепочки, чтобы не поцарапать нежную кожу дельфинов." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Are non-swimmers or children allowed to participate?" }, { "de", "Können Nichtschwimmer oder Kinder teilnehmen?" }, { "it", "I non nuotatori o i bambini possono partecipare?" }, { "fr", "Les non-nageurs et les enfants peuvent-ils participer ?" }, { "ru", "Могут ли участвовать дети и те, кто не умеет плавать?" } }, Answers = new Dictionary<string, string> { { "en", "Yes! All participants wear certified buoyancy vests, and professional trainers are in the water by your side at all times. Children from age 3 and up can participate (children under 6 must be accompanied in the water by an adult)." }, { "de", "Ja! Alle Teilnehmer tragen zertifizierte Schwimmwesten und professionelle Trainer begleiten Sie ständig im Wasser. Kinder ab 3 Jahren sind willkommen (unter 6 Jahren in Begleitung eines zahlenden Erwachsenen im Wasser)." }, { "it", "Sì! Tutti i partecipanti indossano giubbotti salvagente certificati e gli addestratori sono sempre in acqua al vostro fianco. Bambini benvenuti a partire da 3 anni (sotto i 6 anni affiancati da un genitore in vasca)." }, { "fr", "Oui ! Le port du gilet de flottaison est obligatoire et des soigneurs restent à vos côtés en permanence dans l'eau. Enfants acceptés dès 3 ans (les moins de 6 ans doivent être accompagnés d'un adulte dans l'eau)." }, { "ru", "Да! Всем участникам выдаются надежные спасательные жилеты, а инструкторы находятся рядом в воде каждую секунду. Дети допускаются с 3 лет (до 6 лет — обязательно в сопровождении взрослого в воде)." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Can family members watch and take photos from the pool deck?" }, { "de", "Dürfen Begleitpersonen vom Beckenrand zuschauen und Fotos machen?" }, { "it", "Gli accompagnatori possono assistere e fare foto dal bordo vasca?" }, { "fr", "Les accompagnateurs peuvent-ils regarder et prendre des photos depuis le bord ?" }, { "ru", "Могут ли сопровождающие смотреть и фотографировать с бортика?" } }, Answers = new Dictionary<string, string> { { "en", "Yes, accompanying family members can purchase spectator entry tickets to watch from comfortable poolside seating. The dolphinarium also provides high-definition photo and video packages available for purchase." }, { "de", "Ja, Begleitpersonen können Begleitertickets erwerben und das Erlebnis von bequemen Sitzplätzen am Beckenrand aus verfolgen. Das Delphinarium bietet zudem professionelle Foto- und Videopakete zum Kauf an." }, { "it", "Sì, i familiari possono acquistare un biglietto accompagnatore per assistere comodamente a bordo piscina. Inoltre lo staff interno offre foto e video professionali in alta risoluzione acquistabili al termine." }, { "fr", "Oui, les proches peuvent prendre un billet spectateur pour vous encourager depuis les gradins autour du bassin. Un service photo et vidéo professionnel est également proposé sur place." }, { "ru", "Да, родственники и друзья могут приобрести билет зрителя и наблюдать за вами с удобных мест у бассейна. Также на месте работает штатный фотограф с готовыми пакетами качественных снимков и видео." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193191.jpg", Captions = new Dictionary<string, string> { { "en", "Swim with Dolphin - Experience" }, { "de", "Schwimmen mit Delfinen - Erlebnis" }, { "it", "Nuoto con i Delfini – Incontro Esclusivo - Esperienza" }, { "fr", "Nage Privilégiée avec les Dauphins - Expérience" }, { "ru", "Плавание с дельфинами - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193210.jpg", Captions = new Dictionary<string, string> { { "en", "Swim with Dolphin - Experience" }, { "de", "Schwimmen mit Delfinen - Erlebnis" }, { "it", "Nuoto con i Delfini – Incontro Esclusivo - Esperienza" }, { "fr", "Nage Privilégiée avec les Dauphins - Expérience" }, { "ru", "Плавание с дельфинами - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193224.jpg", Captions = new Dictionary<string, string> { { "en", "Swim with Dolphin - Experience" }, { "de", "Schwimmen mit Delfinen - Erlebnis" }, { "it", "Nuoto con i Delfini – Incontro Esclusivo - Esperienza" }, { "fr", "Nage Privilégiée avec les Dauphins - Expérience" }, { "ru", "Плавание с дельфинами - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193242.jpg", Captions = new Dictionary<string, string> { { "en", "Swim with Dolphin - Experience" }, { "de", "Schwimmen mit Delfinen - Erlebnis" }, { "it", "Nuoto con i Delfini – Incontro Esclusivo - Esperienza" }, { "fr", "Nage Privilégiée avec les Dauphins - Expérience" }, { "ru", "Плавание с дельфинами - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193255.jpg", Captions = new Dictionary<string, string> { { "en", "Swim with Dolphin - Experience" }, { "de", "Schwimmen mit Delfinen - Erlebnis" }, { "it", "Nuoto con i Delfini – Incontro Esclusivo - Esperienza" }, { "fr", "Nage Privilégiée avec les Dauphins - Expérience" }, { "ru", "Плавание с дельфинами - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193257.jpg", Captions = new Dictionary<string, string> { { "en", "Swim with Dolphin - Experience" }, { "de", "Schwimmen mit Delfinen - Erlebnis" }, { "it", "Nuoto con i Delfini – Incontro Esclusivo - Esperienza" }, { "fr", "Nage Privilégiée avec les Dauphins - Expérience" }, { "ru", "Плавание с дельфинами - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Neverland Show" }, { "de", "Neverland Abendshow Hurghada" }, { "it", "Spettacolo Neverland Hurghada" }, { "fr", "Spectacle Neverland Hurghada" }, { "ru", "Вечернее шоу Neverland в Хургаде" } },
                Descriptions = new Dictionary<string, string> { { "en", "Enjoy an evening entertainment experience at Neverland Hurghada, combining large-scale stage production, music, lights and themed performances. It is designed as a relaxed night out for couples, families and groups." }, { "de", "Erleben Sie ein faszinierendes Abendprogramm im Neverland Hurghada, das opulente Bühnenproduktionen, mitreißende Musik, Lichteffekte und spektakuläre Themen-Performances vereint. Ein eleganter, unterhaltsamer Abend für Paare, Familien und Gruppen." }, { "it", "Vivete una serata di puro intrattenimento al Neverland di Hurghada, tra grandiose produzioni sceniche, musica, giochi di luce e affascinanti coreografie a tema. Una notte indimenticabile e rilassante, perfetta per coppie, famiglie e gruppi." }, { "fr", "Vivez une soirée d'exception avec le spectacle Neverland à Hurghada, mêlant scénographies grandioses, musique envoûtante, jeux de lumières et performances thématiques captivantes. Une parenthèse festive et raffinée pour les couples, familles et groupes." }, { "ru", "Погрузитесь в атмосферу праздника на грандиозном вечернем шоу Neverland в Хургаде, объединяющем масштабную сценическую постановку, живую музыку, световые спецэффекты и тематические перформансы. Идеальный выбор для приятного отдыха пар, семей и дружеских компаний." } },
                Price = 65,
                Currency = "EUR",
                Duration = "Approx. 3-5 hours including transfer, depending on hotel",
                StartTime = "08:00",
