                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the Neverland Night Show and what does it include?" }, { "de", "Was ist die Neverland Night Show und was ist darin enthalten?" }, { "it", "Cos'è il Neverland Night Show e cosa include la serata?" }, { "fr", "Qu'est-ce que la soirée Neverland Show et qu'est-ce qui est inclus ?" }, { "ru", "Что представляет собой вечернее шоу Neverland (Alf Leila Wa Leila) и что в него входит?" } }, Answers = new Dictionary<string, string> { { "en", "Neverland is Hurghada's premier Arabian Nights theatrical dinner extravaganza. The tour includes hotel transfers, entry to the majestic oriental palace theatre, a lavish multi-course oriental dinner with soft drinks, and a 2.5-hour spectacular production featuring folkloric dancing, Tanoura whirling dervishes, acrobats, equestrian horse shows, and Nile pharaonic history." }, { "de", "Die Neverland Show ist Hurghadas spektakulärste 1001-Nacht-Dinnershow im orientalischen Palastambiente. Im Preis enthalten sind Transfers, Eintritt, ein orientalisches mehrgängiges Abendessen inklusive Softdrinks sowie eine 2,5-stündige Show mit Folklore, Tanoura-Tänzern, Akrobatik und Reitkunst." }, { "it", "Neverland è il più grandioso dinner-show delle Mille e una Notte a Hurghada. Include trasferimenti dall'hotel, ingresso nel maestoso palazzo in stile moresco, ricca cena orientale con bevande analcoliche e 2,5 ore di spettacolo con danze folcloristiche, dervisci Tanoura, acrobati e cavalli." }, { "fr", "Neverland est le plus grand dîner-spectacle des Mille et Une Nuits à Hurghada. La soirée comprend les transferts, l'accès au palais oriental, un dîner gourmand avec boissons sans alcool et 2h30 de représentations : folklore égyptien, derviches tourneurs, voltige équestre et acrobaties." }, { "ru", "Neverland — это масштабное восточное театрализованное шоу в стиле 'Тысяча и одна ночь' во дворце Alf Leila Wa Leila. В тур входят трансфер из отеля, вход в дворец, восточный ужин с напитками и 2,5 часа шоу: танец живота, дервиши танура, конное акробатическое шоу и фараонская история." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the schedule and duration of the Neverland evening?" }, { "de", "Wie ist der Zeitplan und die Dauer des Neverland-Abends?" }, { "it", "Quali sono gli orari e la durata della serata a Neverland?" }, { "fr", "Quels sont les horaires et la durée de la soirée Neverland ?" }, { "ru", "Каковы время начала и продолжительность вечера в Neverland?" } }, Answers = new Dictionary<string, string> { { "en", "Pick-up from Hurghada resorts is between 18:30 and 19:15 PM. Dinner is served around 20:00 PM followed immediately by the main performances. You will return to your hotel around 22:45 to 23:15 PM." }, { "de", "Die Abholung erfolgt zwischen 18:30 und 19:15 Uhr. Das Abendessen beginnt gegen 20:00 Uhr, gefolgt vom Hauptshowprogramm. Die Rückkehr zum Hotel erfolgt zwischen 22:45 und 23:15 Uhr." }, { "it", "Il prelievo in hotel si tiene tra le 18:30 e le 19:15. La cena viene servita intorno alle 20:00, seguita dallo show principale. Il rientro in struttura è previsto tra le 22:45 e le 23:15." }, { "fr", "La prise en charge a lieu entre 18h30 et 19h15. Le dîner est servi vers 20h00 suivi des représentations scéniques. Le retour à votre hôtel s'effectue entre 22h45 et 23h15." }, { "ru", "Трансфер забирает туристов из отелей в 18:30 - 19:15. Ужин начинается около 20:00, затем стартует основная шоу-программа. Возвращение в отель к 22:45 - 23:15." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear to the Neverland Show?" }, { "de", "Welche Kleiderordnung gilt für die Neverland Show?" }, { "it", "Qual è il dress code consigliato per il Neverland Show?" }, { "fr", "Quel est le code vestimentaire pour la soirée Neverland ?" }, { "ru", "Какой дресс-код рекомендуется для посещения шоу Neverland?" } }, Answers = new Dictionary<string, string> { { "en", "Smart-casual attire is recommended (avoid beach swimwear and flip-flops). During winter months (November to March), bring a light jacket or pashmina as the open-air theatrical arena can become breezy at night." }, { "de", "Gepflegte Freizeitkleidung (Smart Casual, keine Badekleidung oder Badeschlappen). In den Wintermonaten (November bis März) empfiehlt sich eine Jacke oder ein Tuch für den Abend in der Freiluft-Arena." }, { "it", "Si consiglia un abbigliamento smart-casual (evitare costumi da bagno e infradito da spiaggia). Nei mesi invernali (da novembre a marzo) portate una giacca leggera poiché l'arena all'aperto può essere ventilata." }, { "fr", "Une tenue décontractée soignée est recommandée (évitez maillots et tongs). En hiver (novembre à mars), prévoyez une veste légère ou un foulard car l'amphithéâtre en plein air peut être frais le soir." }, { "ru", "Рекомендуется стиль smart-casual (не пляжная одежда и не сланцы). В зимний период (с ноября по март) советуем взять легкую куртку или палантин, так как на открытой вечерней арене бывает прохладный ветерок." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is the dinner menu suitable for vegetarians and children?" }, { "de", "Gibt es beim Abendessen Optionen für Vegetarier und Kinder?" }, { "it", "La cena include alternative per vegetariani e bambini?" }, { "fr", "Le dîner propose-t-il des options pour végétariens et enfants ?" }, { "ru", "Подходит ли меню ужина для вегетарианцев и детей?" } }, Answers = new Dictionary<string, string> { { "en", "Yes, the dining buffet includes a generous selection of Mediterranean mezze salads, rice, pasta, vegetables, and breads alongside grilled meats and poultry, ensuring plenty of delicious choices for vegetarians and kids." }, { "de", "Ja, das Buffet bietet eine reichhaltige Auswahl an mediterranen Vorspeisen, Salaten, Reis, Pasta, frischem Gemüse und Brot sowie Grillgerichten, sodass Vegetarier und Kinder voll auf ihre Kosten kommen." }, { "it", "Sì, il buffet offre un'ampia scelta di antipasti mezze, insalate, riso, pasta, verdure cotte e pane fresco oltre a carni alla griglia, garantendo ottime opzioni per vegetariani e bambini." }, { "fr", "Oui, le buffet comprend une variété d'entrées orientales, salades fraîches, riz, pâtes et légumes cuisinés en plus des viandes grillées, convenant parfaitement aux végétariens et aux enfants." }, { "ru", "Да, на шведском столе представлен большой выбор восточных закусок, свежих салатов, риса, пасты, печеных овощей и выпечки наряду с мясом на гриле, поэтому вегетарианцы и дети найдут множество блюд по вкусу." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193224.jpg", Captions = new Dictionary<string, string> { { "en", "Neverland Show - Experience" }, { "de", "Neverland Abendshow Hurghada - Erlebnis" }, { "it", "Spettacolo Neverland Hurghada - Esperienza" }, { "fr", "Spectacle Neverland Hurghada - Expérience" }, { "ru", "Вечернее шоу Neverland в Хургаде - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193242.jpg", Captions = new Dictionary<string, string> { { "en", "Neverland Show - Experience" }, { "de", "Neverland Abendshow Hurghada - Erlebnis" }, { "it", "Spettacolo Neverland Hurghada - Esperienza" }, { "fr", "Spectacle Neverland Hurghada - Expérience" }, { "ru", "Вечернее шоу Neverland в Хургаде - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193249.jpg", Captions = new Dictionary<string, string> { { "en", "Neverland Show - Experience" }, { "de", "Neverland Abendshow Hurghada - Erlebnis" }, { "it", "Spettacolo Neverland Hurghada - Esperienza" }, { "fr", "Spectacle Neverland Hurghada - Expérience" }, { "ru", "Вечернее шоу Neverland в Хургаде - Впечатления" } } } }
