            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Aquarium Hurghada" }, { "de", "Grand Aquarium Hurghada" }, { "it", "Grand Aquarium di Hurghada" }, { "fr", "Grand Aquarium d'Hurghada" }, { "ru", "Большой аквариум Хургады" } },
                Descriptions = new Dictionary<string, string> { { "en", "Explore marine life from the Red Sea and beyond in a family-friendly aquarium setting. It is an easy half-day activity for guests who want to learn about aquatic species without a full-day excursion." }, { "de", "Entdecken Sie die faszinierende Unterwasserwelt des Roten Meeres und exotischer Gewässer im Grand Aquarium von Hurghada. Ein familienfreundlicher Halbtagesausflug, um seltene Meeresbewohner hautnah zu erleben – ganz ohne Tauchmaske." }, { "it", "Esplorate le meraviglie marine del Mar Rosso e oltre nell'elegante cornice del Grand Aquarium di Hurghada. Un'esperienza piacevole e accessibile di mezza giornata per ammirare da vicino straordinarie specie acquatiche, ideale per tutta la famiglia." }, { "fr", "Découvrez la fascinante faune marine de la mer Rouge et des océans au Grand Aquarium d'Hurghada. Une immersion idéale d'une demi-journée pour contempler des espèces aquatiques rares dans un cadre accessible et familial." }, { "ru", "Откройте для себя богатое подводное царство Красного моря в комфортабельном Большом аквариуме Хургады. Прекрасная познавательная программа на полдня для всей семьи, позволяющая познакомиться с удивительными морскими обитателями без длительных заплывов." } },
