                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What will I see at Hurghada Grand Aquarium?" }, { "de", "Was gibt es im Hurghada Grand Aquarium zu sehen?" }, { "it", "Cosa si visita all'Hurghada Grand Aquarium?" }, { "fr", "Que découvre-t-on au Grand Aquarium d'Hurghada ?" }, { "ru", "Что можно увидеть в Большом Аквариуме Хургады (Hurghada Grand Aquarium)?" } }, Answers = new Dictionary<string, string> { { "en", "Known as 'The Red Sea in Glass', the facility houses over 1,200 marine animals across 24 exhibits. Highlights include a 20-meter underwater acrylic tunnel surrounded by sharks and giant stingrays, a mini-zoo with rescued desert wildlife, a lush rainforest biome, and a fossil museum showcasing prehistoric whale skeletons (Wadi Al-Hitan relics)." }, { "de", "Das Aquarium ('Das Rote Meer im Glas') beherbergt über 1.200 Meerestiere in 24 Schauzonen. Höhepunkte sind der 20 Meter lange Unterwassertunnel mit Haien und Rochen, ein Mini-Zoo, ein tropischer Regenwald und das Fossilienmuseum mit Urzeit-Walskeletten." }, { "it", "Definito 'Il Mar Rosso nel Vetro', ospita oltre 1.200 esemplari marini in 24 ambienti. I punti forti sono il tunnel sottomarino di 20 metri tra squali e mante, il mini-zoo con fauna locale, la foresta pluviale e il museo dei fossili con scheletri di balene preistoriche." }, { "fr", "Surnommé 'La Mer Rouge dans du verre', le site présente plus de 1 200 créatures marines réparties en 24 espaces. Ne manquez pas le tunnel sous-marin de 20 mètres peuplé de requins et raies, le mini-zoo, la forêt tropicale et l'exposition de fossiles de baleines." }, { "ru", "Этот комплекс называют 'Красное море в стекле'. Здесь более 1200 обитателей в 24 зонах. Главные хиты: 20-метровый подводный стеклянный туннель с акулами и гигантскими скатами, мини-зоопарк, тропический лес и музей древних окаменелостей со скелетами доисторических китов." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the tour and how long does it take?" }, { "de", "Was ist im Ausflug enthalten und wie lange dauert er?" }, { "it", "Cosa include il biglietto e quanto tempo occorre?" }, { "fr", "Qu'est-ce qui est inclus et combien de temps dure la visite ?" }, { "ru", "Что включено в экскурсию и сколько длится посещение аквариума?" } }, Answers = new Dictionary<string, string> { { "en", "The tour includes hotel pickup and return in an air-conditioned vehicle and full-access admission tickets to all aquarium zones, rainforest, mini-zoo, and fossil exhibitions. The visit itself takes about 1.5 to 2 hours, making total excursion duration around 2.5 to 3 hours." }, { "de", "Der Ausflug umfasst klimatisierten Hin- und Rücktransfer sowie Eintrittskarten für alle Ausstellungsbereiche, Regenwald, Mini-Zoo und Fossilienmuseum. Der Rundgang dauert ca. 1,5 bis 2 Stunden (Gesamtdauer ca. 2,5 bis 3 Std.)." }, { "it", "Il pacchetto comprende trasferimento dall'hotel a/r con aria condizionata e biglietti d'ingresso per tutte le sezioni dell'acquario, zoo, giungla e fossili. La visita autonoma richiede 1,5 - 2 ore (durata totale circa 2,5 - 3 ore)." }, { "fr", "Le tour inclut le transfert aller-retour climatisé et l'accès complet à toutes les zones (aquariums, forêt, mini-zoo et fossiles). La visite dure environ 1h30 à 2h, pour une durée totale d'environ 2h30 à 3 heures." }, { "ru", "В стоимость входят трансфер из отеля на кондиционированном транспорте и полный входной билет во все зоны аквариума, тропический зал, зоопарк и музей окаменелостей. Осмотр занимает 1,5-2 часа, вся поездка с дорогой — 2,5-3 часа." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "When does shark feeding take place and can we see it?" }, { "de", "Wann findet die Haifütterung statt und kann man zusehen?" }, { "it", "A che ora c'è il pasto degli squali ed è visibile al pubblico?" }, { "fr", "À quelle heure a lieu le nourrissage des requins et peut-on y assister ?" }, { "ru", "В какое время проходит кормление акул и можно ли его посмотреть?" } }, Answers = new Dictionary<string, string> { { "en", "Daily shark feeding typically takes place between 11:00 to 11:30 AM in the main tank tunnel. Our morning tour departures are scheduled precisely so you can witness the divers interacting with and feeding the sharks up close." }, { "de", "Die tägliche Haifütterung findet meist zwischen 11:00 und 11:30 Uhr im Hauptbecken statt. Unsere Vormittagstouren sind zeitlich so abgestimmt, dass Sie den Tauchern beim Füttern direkt zusehen können." }, { "it", "Il momento del pasto degli squali avviene ogni giorno tra le 11:00 e le 11:30 nella vasca principale. I nostri tour mattutini sono organizzati appositamente per permettervi di assistere a questa attrazione emozionante." }, { "fr", "Le nourrissage quotidien des requins se déroule en général entre 11h00 et 11h30 dans le bassin principal. Nos départs du matin sont spécialement planifiés pour vous permettre d'y assister." }, { "ru", "Ежедневное шоу кормления акул водолазом проходит с 11:00 до 11:30 в главном аквариуме. Наши утренние выезды спланированы так, чтобы вы успели увидеть этот захватывающий процесс своими глазами." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is the aquarium suitable for hot summer days and baby strollers?" }, { "de", "Ist das Aquarium für heiße Sommertage und Kinderwagen geeignet?" }, { "it", "L'acquario è adatto nelle giornate calde ed è accessibile con passeggini?" }, { "fr", "L'aquarium est-il climatisé et pratique avec une poussette bébé ?" }, { "ru", "Комфортно ли в аквариуме в летнюю жару и удобно ли с детской коляской?" } }, Answers = new Dictionary<string, string> { { "en", "Yes! The indoor exhibition halls and underwater tunnels are fully air-conditioned, making it a refreshing escape from mid-day heat. Paths are smooth and equipped with ramps, making strollers easy to push throughout." }, { "de", "Ja! Die Innenhallen und der Unterwassertunnel sind vollklimatisiert – eine angenehme Abkühlung an heißen Sommertagen. Die Wege sind barrierefrei und verfügen über Rampen für Kinderwagen." }, { "it", "Sì! I padiglioni interni e il tunnel subacqueo sono completamente climatizzati, offrendo una piacevole sosta dal caldo estivo. I percorsi sono privi di barriere e dotati di rampe per passeggini." }, { "fr", "Oui ! Les galeries intérieures sont entièrement climatisées, ce qui en fait une sortie fraîche très appréciable en été. Le parcours est fluide et aménagé avec des rampes pour poussettes." }, { "ru", "Да! Все выставочные залы и подводный туннель отлично кондиционируются, что приятно спасает от полуденного солнца. Везде есть удобные пандусы для проезда с детскими колясками." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193255.jpg", Captions = new Dictionary<string, string> { { "en", "Aquarium Hurghada - Experience" }, { "de", "Grand Aquarium Hurghada - Erlebnis" }, { "it", "Grand Aquarium di Hurghada - Esperienza" }, { "fr", "Grand Aquarium d'Hurghada - Expérience" }, { "ru", "Большой аквариум Хургады - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193257.jpg", Captions = new Dictionary<string, string> { { "en", "Aquarium Hurghada - Experience" }, { "de", "Grand Aquarium Hurghada - Erlebnis" }, { "it", "Grand Aquarium di Hurghada - Esperienza" }, { "fr", "Grand Aquarium d'Hurghada - Expérience" }, { "ru", "Большой аквариум Хургады - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193268.jpg", Captions = new Dictionary<string, string> { { "en", "Aquarium Hurghada - Experience" }, { "de", "Grand Aquarium Hurghada - Erlebnis" }, { "it", "Grand Aquarium di Hurghada - Esperienza" }, { "fr", "Grand Aquarium d'Hurghada - Expérience" }, { "ru", "Большой аквариум Хургады - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Abu Dabbab" }, { "de", "Schildkrötenbucht Abu Dabbab" }, { "it", "Baia di Abu Dabbab" }, { "fr", "Baie d'Abu Dabbab" }, { "ru", "Бухта Абу-Дабаб" } },
                Descriptions = new Dictionary<string, string> { { "en", "Travel south to Abu Dabbab for a full-day Red Sea nature experience. The bay is known for clear water, sandy beach and the possibility of seeing green sea turtles and other marine life while snorkeling." }, { "de", "Reisen Sie gen Süden in die geschützte Bucht von Abu Dabbab zu einem ganztägigen Naturerlebnis am Roten Meer. Kristallklares Wasser, goldener Sandstrand und die unvergleichliche Gelegenheit, riesige Grüne Meeresschildkröten und farbenprächtige Meeresbewohner beim Schnorcheln zu beobachten." }, { "it", "Viaggiate verso sud fino alla baia protetta di Abu Dabbab per un'indimenticabile giornata nella natura del Mar Rosso. Celebre per le sue acque cristalline, la spiaggia dorata e la straordinaria opportunità di nuotare accanto a tartarughe marine giganti e dugonghi." }, { "fr", "Partez vers le sud à la découverte de la prestigieuse baie d'Abu Dabbab pour une journée complète au cœur de la nature préservée de la mer Rouge. Eaux turquoise, plage de sable fin et privilège unique d'observer des tortues marines géantes en snorkeling." }, { "ru", "Отправьтесь на юг в заповедную бухту Абу-Дабаб на целый день незабываемого отдыха на Красном море. Залив славится кристально чистой водой, песчаным пляжем и уникальной возможностью поплавать со снорклингом рядом с гигантскими зелеными черепахами." } },
                Price = 70,
                Currency = "EUR",
