                MediaUrls = new List<string> { "/images/tours/5861626853276193281.jpg", "/images/tours/5861626853276193191.jpg", "/images/tours/5861626853276193195.jpg" },
                ReserveAndPayLater = true,
                HotelPickup = true,
                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "Why is Abu Dabbab Bay so famous and what will we see?" }, { "de", "Warum ist die Bucht von Abu Dabbab so berühmt und was werden wir sehen?" }, { "it", "Perché la baia di Abu Dabbab è così famosa e cosa vedremo?" }, { "fr", "Pourquoi la baie d'Abu Dabbab est-elle si réputée et qu'y observe-t-on ?" }, { "ru", "Чем знаменита бухта Абу-Даббаб (Abu Dabbab) и кого там можно встретить?" } }, Answers = new Dictionary<string, string> { { "en", "Abu Dabbab is a protected national marine sanctuary in Marsa Alam celebrated worldwide for its lush sea-grass meadows. It is one of the very few natural habitats where you can snorkel right off the sandy beach alongside giant green sea turtles and the rare, endangered Dugong (sea cow)." }, { "de", "Abu Dabbab ist ein Meeresschutzgebiet bei Marsa Alam, berühmt für seine Seegraswiesen. Es ist einer der seltenen Orte weltweit, an dem man direkt vom Sandstrand aus mit riesigen grünen Meeresschildkröten und der seltenen Seekuh (Dugong) schnorcheln kann." }, { "it", "Abu Dabbab è un'area marina protetta celebre per i suoi fondali di praterie sottomarine. È uno dei pochissimi luoghi al mondo dove è possibile nuotare direttamente dalla riva con enormi tartarughe verdi giganti e il rarissimo dugongo (mucca di mare)." }, { "fr", "Abu Dabbab est une réserve marine protégée réputée pour ses herbiers sous-marins. C'est l'un des rares endroits au monde où l'on peut nager depuis la plage avec d'immenses tortues marines vertes et le mythique dugong." }, { "ru", "Абу-Даббаб — всемирно известный заповедный залив с полями морской травы в Марса-Аламе. Это уникальное место, где прямо с песчаного берега можно поплавать с гигантскими зелеными черепахами и редчайшей морской коровой — дюгонем." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Abu Dabbab day excursion?" }, { "de", "Was ist im Tagesausflug nach Abu Dabbab enthalten?" }, { "it", "Cosa comprende l'escursione di una giornata ad Abu Dabbab?" }, { "fr", "Que comprend l'excursion d'une journée à Abu Dabbab ?" }, { "ru", "Что включено в однодневную экскурсию в Абу-Даббаб?" } }, Answers = new Dictionary<string, string> { { "en", "The tour includes round-trip transport in air-conditioned vehicles, full beach club day-pass with shaded loungers, a freshly cooked lunch at the beach restaurant, soft drinks, national park entry fees, snorkeling gear, and guided snorkeling tours to spot turtles." }, { "de", "Die Tour beinhaltet Hin- und Rückfahrt im klimatisierten Bus/Van, Tageseintritt zum Strandclub mit schattigen Liegen, ein frisch zubereitetes Mittagessen im Strandrestaurant, Softdrinks, Parkgebühren, Schnorchelausrüstung und geführte Schnorchelgänge zu den Schildkröten." }, { "it", "L'escursione comprende trasporto a/r in comodo veicolo climatizzato, accesso al beach club con lettini ombreggiati, pranzo al ristorante sulla spiaggia, soft drink, tasse del parco protetto, kit snorkeling e tour guidato alla ricerca delle tartarughe." }, { "fr", "La sortie inclut le transport aller-retour climatisé, l'accès à la plage avec transats et parasols, le déjeuner au restaurant de plage, les boissons sans alcool, les droits d'entrée, le matériel de snorkeling et les guidages pour voir les tortues." }, { "ru", "В тур входят трансфер на комфортном кондиционированном транспорте, вход на оборудованный пляж с лежаками и зонтиками, вкусный горячий обед в пляжном ресторане, напитки, сборы нацпарка, аренда масок и ласт и снорклинг с гидом к черепахам." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the pickup time and duration for Abu Dabbab from Hurghada?" }, { "de", "Wie sind Abholzeit und Gesamtdauer für Abu Dabbab ab Hurghada?" }, { "it", "Quali sono gli orari di partenza e la durata per Abu Dabbab da Hurghada?" }, { "fr", "Quels sont les horaires et la durée depuis Hurghada vers Abu Dabbab ?" }, { "ru", "Какое время выезда и продолжительность поездки в Абу-Даббаб из Хургады?" } }, Answers = new Dictionary<string, string> { { "en", "Because Abu Dabbab is situated south in Marsa Alam, departures from Hurghada start early (approx. 05:30 to 06:15 AM). The scenic drive along the coast takes around 3 to 3.5 hours each way with a comfort stop. You spend about 5 hours on the beach, returning around 18:00 to 18:30 PM." }, { "de", "Da Abu Dabbab im Süden bei Marsa Alam liegt, erfolgt die Abholung ab Hurghada früh (ca. 05:30 bis 06:15 Uhr). Die Fahrt dauert ca. 3 bis 3,5 Stunden pro Strecke mit Kaffeepause. Sie genießen ca. 5 Stunden am Strand und kehren gegen 18:00 - 18:30 Uhr zurück." }, { "it", "Trovandosi a sud, la partenza da Hurghada è mattutina (ore 05:30 - 06:15). Il viaggio panoramico costiero dura circa 3 - 3,5 ore con sosta caffè. Trascorrerete circa 5 ore in spiaggia, con rientro in hotel verso le 18:00 - 18:30." }, { "fr", "Située à Marsa Alam au sud, le départ d'Hurghada a lieu tôt (vers 05h30 - 06h15). Le trajet dure environ 3h à 3h30 avec pause rafraîchissement. Vous profitez de 5 heures sur place, pour un retour vers 18h00 - 18h30." }, { "ru", "Так как бухта находится южнее, в Марса-Аламе, выезд из отелей Хургады ранний — около 05:30-06:15. Дорога вдоль живописного побережья занимает около 3-3,5 часов с санитарной остановкой. На пляже вы проведете около 5 часов, возвращение в отель к 18:00-18:30." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I pack for Abu Dabbab?" }, { "de", "Was sollte man für die Abu Dabbab Tour einpacken?" }, { "it", "Cosa mettere nello zaino per Abu Dabbab?" }, { "fr", "Que faut-il emporter dans son sac pour Abu Dabbab ?" }, { "ru", "Что необходимо взять с собой в поездку в Абу-Даббаб?" } }, Answers = new Dictionary<string, string> { { "en", "Passport copies (checkpoint rule), hotel breakfast box (order at reception the night before), beach towel, swimwear, water shoes, high-SPF sunscreen, sunglasses, hat, underwater camera (GoPro), and cash for souvenirs or cold beer." }, { "de", "Passkopien (Kontrollposten-Vorgabe), Frühstückspaket aus dem Hotel (am Vorabend bestellen), Strandtuch, Badesachen, Badeschuhe, Sonnencreme, Sonnenbrille, Sonnenhut, Unterwasserkamera und Bargeld für Extras." }, { "it", "Copie dei passaporti (controllo posti di blocco), cestino colazione dell'hotel (da richiedere la sera prima), telo mare, costume, scarpette da scoglio, crema solare, occhiali, fotocamera subacquea e contanti." }, { "fr", "Copies de passeport, boîte petit-déjeuner de l'hôtel, serviette, maillot, chaussures aquatiques, crème solaire, lunettes, chapeau, caméra étanche pour filmer les tortues et argent de poche." }, { "ru", "Копии паспортов (для дорожной полиции), сухой паек на завтрак из отеля (заказать с вечера), пляжное полотенце, купальник, коралловые тапочки, крем от солнца, головной убор, подводную камеру и наличные." } } } },
