                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193281.jpg", Captions = new Dictionary<string, string> { { "en", "Abu Dabbab - Experience" }, { "de", "Schildkrötenbucht Abu Dabbab - Erlebnis" }, { "it", "Baia di Abu Dabbab - Esperienza" }, { "fr", "Baie d'Abu Dabbab - Expérience" }, { "ru", "Бухта Абу-Дабаб - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193191.jpg", Captions = new Dictionary<string, string> { { "en", "Abu Dabbab - Experience" }, { "de", "Schildkrötenbucht Abu Dabbab - Erlebnis" }, { "it", "Baia di Abu Dabbab - Esperienza" }, { "fr", "Baie d'Abu Dabbab - Expérience" }, { "ru", "Бухта Абу-Дабаб - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193195.jpg", Captions = new Dictionary<string, string> { { "en", "Abu Dabbab - Experience" }, { "de", "Schildkrötenbucht Abu Dabbab - Erlebnis" }, { "it", "Baia di Abu Dabbab - Esperienza" }, { "fr", "Baie d'Abu Dabbab - Expérience" }, { "ru", "Бухта Абу-Дабаб - Впечатления" } } } }
