            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Water World Aquapark" }, { "de", "Water World Wasserpark" }, { "it", "Parco Acquatico Water World" }, { "fr", "Parc Aquatique Water World" }, { "ru", "Аквапарк Water World" } },
                Descriptions = new Dictionary<string, string> { { "en", "Spend a fun-filled day at an aquapark with slides, pools and water activities suitable for different ages. It is an easy family option for guests looking for a break from the beach and sea excursions." }, { "de", "Verbringen Sie einen unbeschwerten, erlebnisreichen Tag im Wasserpark mit abwechslungsreichen Rutschen, weitläufigen Pools und Attraktionen für jedes Alter. Die ideale Familienauszeit für erstklassigen Wasserspaß abseits des Meeres." }, { "it", "Trascorrete una giornata spensierata in un dinamico parco acquatico tra scivoli emozionanti, piscine rilassanti e attrazioni per tutte le età. La scelta ideale per famiglie desiderose di una rinfrescante alternativa alle escursioni in mare." }, { "fr", "Passez une journée grisante dans un parc aquatique complet, doté de toboggans spectaculaires, de piscines et d'attractions adaptées à tous les âges. Une option familiale par excellence pour varier les plaisirs balnéaires." }, { "ru", "Проведите яркий и веселый день в аквапарке с захватывающими водными горками, просторными бассейнами и развлечениями для гостей всех возрастов. Идеальный семейный отдых, дарящий массу эмоций и свежести вдали от морских прогулок." } },
