                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Water World Aquapark day pass?" }, { "de", "Was ist im Tagesticket für den Water World Aquapark enthalten?" }, { "it", "Cosa include il biglietto giornaliero per Water World Aquapark?" }, { "fr", "Qu'est-ce qui est inclus dans le pass journée Water World Aquapark ?" }, { "ru", "Что входит в билет на целый день в аквапарк Water World?" } }, Answers = new Dictionary<string, string> { { "en", "The day pass includes air-conditioned hotel transfers, unlimited access to over 50 thrilling water slides, wave pools, rafting rivers, and kids' splash zones, plus an all-inclusive food court lunch buffet with snacks, ice creams, and unlimited soft drinks all day." }, { "de", "Das Tagesticket beinhaltet den klimatisierten Hoteltransfer, unbegrenzten Zugang zu über 50 Wasserrutschen, Wellenbecken, Wildwasser-Rafting und Kinderbereichen sowie All-Inclusive-Verpflegung am Mittagsbuffet mit Snacks, Eis und unbegrenzten Softdrinks." }, { "it", "Il pass giornaliero comprende transfer da/per l'hotel, accesso illimitato a oltre 50 scivoli acquatici, piscina a onde, fiume rafting e aree baby splash, oltre a pranzo a buffet all-inclusive con snack, gelati e bibite illimitate per l'intera giornata." }, { "fr", "Le pass comprend les transferts hôtel, l'accès illimité à plus de 50 toboggans aquatiques sensationnels, piscine à vagues, rivière à bouées, pataugeoires ludiques, ainsi qu'un déjeuner buffet tout compris avec snacks, glaces et boissons sans alcool toute la journée." }, { "ru", "В стоимость входят трансфер из отеля, безлимитный доступ ко всем 50+ горкам, волновому бассейну, ленивой и рафтинг-реке, детским игровым городкам, а также питание по системе 'все включено' (обед, закуски, мороженое и безалкогольные напитки весь день)." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What are the height and age restrictions for slides?" }, { "de", "Gibt es Größen- und Altersbeschränkungen für die Rutschen?" }, { "it", "Ci sono limitazioni di altezza ed età per gli scivoli?" }, { "fr", "Y a-t-il des limites de taille et d'âge pour les toboggans ?" }, { "ru", "Есть ли ограничения по росту и возрасту для катания на горках?" } }, Answers = new Dictionary<string, string> { { "en", "Most major thrill slides require a minimum height of 120 cm (approx. 6 years old). For smaller children and toddlers, the park features huge dedicated pirate aqua-towers, shallow splash pools, and mini-slides fully staffed with certified lifeguards." }, { "de", "Für die großen Adrenalinrutschen gilt meist eine Mindestkörpergröße von 120 cm (ca. 6 Jahre). Für kleinere Kinder gibt es riesige Piraten-Wassertürme, flache Planschbecken und Mini-Rutschen unter Aufsicht geschulter Rettungsschwimmer." }, { "it", "La maggior parte degli scivoli per adulti richiede un'altezza minima di 120 cm (circa 6 anni). Per i più piccoli sono presenti ampie lagune tematiche con mini-scivoli, giochi d'acqua e costante sorveglianza dei bagnini." }, { "fr", "Les grands toboggans à sensations requièrent une taille minimale de 120 cm (environ 6 ans). Les jeunes enfants disposent d'un vaste parc aquatique dédié avec tours de jeux pirates, bassins peu profonds et maîtres-nageurs." }, { "ru", "На экстремальные взрослые горки допускаются гости ростом от 120 см (примерно от 6 лет). Для малышей есть огромные тематические водные городки, мелкие бассейны и безопасные детские горки под присмотром спасателей." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I bring and are lockers and towels provided?" }, { "de", "Was sollte ich mitbringen und gibt es Schließfächer und Handtücher?" }, { "it", "Cosa portare e sono disponibili armadietti e teli?" }, { "fr", "Que faut-il apporter et y a-t-il des casiers et des serviettes ?" }, { "ru", "Что взять с собой и есть ли шкафчики для вещей и полотенца?" } }, Answers = new Dictionary<string, string> { { "en", "Bring your swimwear, sunscreen, flip-flops, sunglasses, and your hotel beach towel (or rent one at the gate). Secure lockers are available for rent to keep your valuables, phones, and wallets completely safe while you splash." }, { "de", "Bringen Sie Badekleidung, Sonnencreme, Badeschlappen, Sonnenbrille und Ihr Hotel-Strandtuch mit. Sichere Schließfächer können gegen geringe Gebühr gemietet werden, um Wertsachen und Smartphones sicher zu verwahren." }, { "it", "Portate costume, crema solare, ciabattine, occhiali da sole e il vostro telo mare dell'hotel. Sono disponibili armadietti di sicurezza a noleggio per custodire documenti, telefoni e valori." }, { "fr", "Apportez maillots, crème solaire, tongs, lunettes de soleil et serviettes d'hôtel. Des casiers fermant à clé sont disponibles à la location pour stocker vos effets personnels en toute sérénité." }, { "ru", "Возьмите купальник, крем от солнца, шлепанцы, очки и пляжные полотенца из отеля. На входе можно арендовать персональный запирающийся шкафчик (локер) для безопасного хранения телефонов и ценных вещей." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What are the park opening hours and pickup timings?" }, { "de", "Wie sind die Öffnungszeiten und die Abholzeiten?" }, { "it", "Quali sono gli orari del parco e del servizio navetta?" }, { "fr", "Quels sont les horaires d'ouverture et de navette ?" }, { "ru", "Какое расписание работы аквапарка и трансфера?" } }, Answers = new Dictionary<string, string> { { "en", "Hotel pickups start at 09:15 to 09:45 AM. The aquapark operates from 10:00 AM to 17:00 PM. Return buses depart the park around 16:30 to 17:00 PM, getting you back to your resort in time for dinner." }, { "de", "Die Abholung erfolgt zwischen 09:15 und 09:45 Uhr. Der Park ist von 10:00 bis 17:00 Uhr geöffnet. Der Rücktransfer startet um 16:30 bis 17:00 Uhr." }, { "it", "La navetta passa in hotel tra le 09:15 e le 09:45. Il parco è aperto dalle 10:00 alle 17:00. Il rientro parte alle 16:30 - 17:00, tornando comodamente in hotel per cena." }, { "fr", "Prise en charge à l'hôtel entre 09h15 et 09h45. Le parc aquatique ouvre de 10h00 à 17h00. Les navettes de retour partent vers 16h30 - 17h00." }, { "ru", "Трансфер забирает туристов в 09:15 - 09:45. Аквапарк открыт с 10:00 до 17:00. Обратный автобус отходит в 16:30 - 17:00, возвращая вас в отель к ужину." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193198.jpg", Captions = new Dictionary<string, string> { { "en", "Water World Aquapark - Experience" }, { "de", "Water World Wasserpark - Erlebnis" }, { "it", "Parco Acquatico Water World - Esperienza" }, { "fr", "Parc Aquatique Water World - Expérience" }, { "ru", "Аквапарк Water World - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193191.jpg", Captions = new Dictionary<string, string> { { "en", "Water World Aquapark - Experience" }, { "de", "Water World Wasserpark - Erlebnis" }, { "it", "Parco Acquatico Water World - Esperienza" }, { "fr", "Parc Aquatique Water World - Expérience" }, { "ru", "Аквапарк Water World - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193195.jpg", Captions = new Dictionary<string, string> { { "en", "Water World Aquapark - Experience" }, { "de", "Water World Wasserpark - Erlebnis" }, { "it", "Parco Acquatico Water World - Esperienza" }, { "fr", "Parc Aquatique Water World - Expérience" }, { "ru", "Аквапарк Water World - Впечатления" } } } }
