            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Neverland Aquapark" }, { "de", "Neverland Aquapark Hurghada" }, { "it", "Parco Acquatico Neverland" }, { "fr", "Parc Aquatique Neverland" }, { "ru", "Аквапарк Neverland" } },
                Descriptions = new Dictionary<string, string> { { "en", "Enjoy a full day of water attractions and entertainment at Neverland Hurghada. With pools, slides and leisure areas, it is ideal for families and guests who want an active day away from the sea." }, { "de", "Genießen Sie einen luxuriösen Ganztagesausflug voller Wasserspaß und erstklassiger Unterhaltung im Neverland Hurghada. Mit zahllosen Rutschen, Erlebnisbecken und komfortablen Loungebereichen perfekt für aktive Familien und Erholungssuchende." }, { "it", "Vivete un'intera giornata di divertimento acquatico ed esclusivo intrattenimento al Neverland di Hurghada. Con decine di scivoli, piscine a tema e aree relax ombreggiate, è la meta ideale per una giornata energica e spensierata." }, { "fr", "Savourez une journée complète d'attractions aquatiques et de divertissements haut de gamme au Neverland Hurghada. Toboggans géants, lagons scintillants et espaces de détente en font l'escapade parfaite pour toute la famille." }, { "ru", "Насладитесь насыщенным днем водных аттракционов и развлечений в крупнейшем аквапарке Neverland в Хургаде. Многочисленные горки, бассейны и комфортабельные зоны отдыха создают идеальные условия для активного и беззаботного семейного дня." } },
                Price = 65,
                Currency = "EUR",
                Duration = "Approx. 6-8 hours",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000011"),
