                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "Why is Neverland Aquapark considered the biggest water resort in Egypt?" }, { "de", "Warum gilt der Neverland Aquapark als das größte Wasser-Resort Ägyptens?" }, { "it", "Perché Neverland Aquapark è considerato il più grande parco acquatico d'Egitto?" }, { "fr", "Pourquoi Neverland Aquapark est-il considéré comme le plus grand resort aquatique d'Égypte ?" }, { "ru", "Почему аквапарк Neverland считается самым грандиозным водным парком в Египте?" } }, Answers = new Dictionary<string, string> { { "en", "Neverland Hurghada is a massive mega-waterpark sprawling over 100,000 m² featuring over 80 spectacular slides and water attractions, heated pools in winter, interactive pirate ships, multi-lane racers, and world-class aquatic fun for all ages." }, { "de", "Neverland Hurghada ist ein gigantischer Mega-Wasserpark auf über 100.000 m² mit über 80 spektakulären Rutschen, im Winter beheizten Becken, Piratenschiffen, Geschwindigkeitsbahnen und Spaß für jedes Alter." }, { "it", "Neverland Hurghada è un mega parco acquatico di oltre 100.000 m² con oltre 80 scivoli spettacolari, piscine riscaldate d'inverno, galeoni dei pirati e attrazioni da record per tutta la famiglia." }, { "fr", "Neverland Hurghada s'étend sur plus de 100 000 m² avec plus de 80 toboggans et jeux aquatiques, des bassins chauffés en hiver, des bateaux pirates et des attractions aquatiques de premier ordre." }, { "ru", "Neverland Hurghada — это колоссальный водный курорт площадью более 100 000 м² с более чем 80 водными горками и аттракционами, подогреваемыми бассейнами зимой, пиратскими кораблями и развлечениями для любого возраста." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Neverland Aquapark day pass?" }, { "de", "Was ist im Neverland Aquapark Tagesticket enthalten?" }, { "it", "Cosa include il pass giornaliero per Neverland Aquapark?" }, { "fr", "Que comprend le pass journée à Neverland Aquapark ?" }, { "ru", "Что включено в билет на день в аквапарк Neverland?" } }, Answers = new Dictionary<string, string> { { "en", "The excursion includes round-trip air-conditioned hotel transport, full-day entry pass to all 80+ slides, sun loungers and umbrella shades, plus an open food court lunch buffet with hot meals, bakery, desserts, soft drinks, and mineral water all day." }, { "de", "Enthalten sind klimatisierte Hin- und Rücktransfers, Ganztageseintritt zu allen 80+ Rutschen, Sonnenliegen, Sonnenschirme sowie ganztägiges All-Inclusive-Mittagessen im Food Court mit warmen Mahlzeiten, Desserts und unbegrenzten Softdrinks." }, { "it", "Il tour include transfer a/r con aria condizionata, ingresso full-day a tutti gli oltre 80 scivoli, lettini e ombrelloni, oltre a un ricco pranzo all-inclusive nell'area ristoro con piatti caldi, dolci e bevande analcoliche illimitate." }, { "fr", "L'excursion inclut les transferts climatisés, l'accès illimité toute la journée aux 80+ toboggans, transats ombragés et un déjeuner complet au food-court avec plats chauds, desserts et boissons fraîches à volonté." }, { "ru", "В стоимость входят трансфер из отеля и обратно, безлимитный доступ ко всем 80+ горкам на весь день, шезлонги и зонтики, а также обед по системе 'все включено' на фуд-корте (горячие блюда, пицца, десерты и безалкогольные напитки весь день)." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Are pools heated at Neverland Aquapark during winter?" }, { "de", "Sind die Pools im Neverland Aquapark im Winter beheizt?" }, { "it", "Le piscine di Neverland Aquapark sono riscaldate in inverno?" }, { "fr", "Les bassins de Neverland Aquapark sont-ils chauffés en hiver ?" }, { "ru", "Подогреваются ли бассейны в аквапарке Neverland зимой?" } }, Answers = new Dictionary<string, string> { { "en", "Yes! Unlike many older parks, Neverland features state-of-the-art heated pool systems throughout key children's zones and main slide landing pools from November through March, guaranteeing comfortable water temperatures year-round." }, { "de", "Ja! Im Gegensatz zu vielen älteren Parks verfügt Neverland über moderne Beckenbeheizung in den Kinderbereichen und Hauptlandebecken von November bis März – für perfekten Badespaß auch im Winter." }, { "it", "Sì! A differenza di altri parchi, Neverland dispone di un moderno impianto di riscaldamento per le aree bambini e le vasche di arrivo degli scivoli da novembre a marzo, assicurando un comfort termico ottimale." }, { "fr", "Oui ! Neverland bénéficie d'un système moderne de chauffage de l'eau dans les zones enfants et les bassins d'arrivée des principaux toboggans de novembre à mars pour un plaisir garanti en toute saison." }, { "ru", "Да! В отличие от многих других аквапарков, в Neverland с ноября по март работают современные системы подогрева детских зон и бассейнов приземления горок, поэтому купаться тепло и комфортно даже зимой." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I bring and wear to Neverland Aquapark?" }, { "de", "Was sollte man für den Neverland Aquapark mitbringen und anziehen?" }, { "it", "Cosa portare e indossare a Neverland Aquapark?" }, { "fr", "Que faut-il apporter et porter pour Neverland Aquapark ?" }, { "ru", "Что взять с собой и как одеться в аквапарк Neverland?" } }, Answers = new Dictionary<string, string> { { "en", "Wear appropriate swimwear (no metal zippers or buckles on slides). Bring your hotel beach towel, water shoes or flip-flops, high-protection sunscreen, sunglasses, and cash for optional locker rentals or souvenir photos." }, { "de", "Badekleidung ohne störende Metallreißverschlüsse oder Schnallen tragen. Hotel-Badetuch, Badeschlappen, Sonnencreme, Sonnenbrille und Bargeld für ein Schließfach oder Souvenirfotos mitbringen." }, { "it", "Indossate costumi da bagno idonei (senza cerniere o fibbie metalliche che possano danneggiare gli scivoli). Portate teli mare dell'hotel, ciabattine, protezione solare e contanti per il noleggio armadietto." }, { "fr", "Portez des maillots de bain adaptés sans pièces métalliques. Apportez votre serviette d'hôtel, tongs, crème solaire, lunettes et de la monnaie pour la consigne et d'éventuels extras." }, { "ru", "Наденьте удобный купальный костюм (без металлических замков и пряжек, которые могут повредить горки). Возьмите полотенце из отеля, сланцы, солнцезащитный крем и немного наличных для аренды шкафчика." } } } },
