            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Water Sport" }, { "de", "Wassersport-Erlebnis Rotes Meer" }, { "it", "Pacchetto Sport Acquatici sul Mar Rosso" }, { "fr", "Sports Nautiques en Mer Rouge" }, { "ru", "Водные виды спорта на Красном море" } },
                Descriptions = new Dictionary<string, string> { { "en", "Enjoy an adrenaline-filled Red Sea water-sports session with activities selected from the available programme. The exact activity can include options such as parasailing or other motorised water sports, depending on the booked package." }, { "de", "Spüren Sie das Adrenalin bei einem exklusiven Wassersport-Erlebnis auf dem Roten Meer. Wählen Sie aus aufregenden motorisierten Aktivitäten wie Parasailing, Banana Boat oder rasanten Fahrten für unvergessliche Momente auf dem türkisfarbenen Wasser." }, { "it", "Provate l'emozione pura con una sessione su misura di sport acquatici sul Mar Rosso. A seconda del pacchetto scelto, potrete cimentarvi nel parasailing panoramico o sfrecciare sulle onde con energici sport nautici motorizzati." }, { "fr", "Faites le plein de sensations fortes avec une session de sports nautiques d'exception sur les eaux turquoise de la mer Rouge. Parachute ascensionnel, engins tractés ou motonautisme selon votre formule pour des souvenirs inoubliables." }, { "ru", "Испытайте прилив адреналина на индивидуальной сессии водных видов спорта в лазурных водах Красного моря. В зависимости от выбранной программы вас ждут захватывающий парасейлинг, скоростные катера или катание на надувных аттракционах." } },
