                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What activities are included in the Water Sport package?" }, { "de", "Welche Aktivitäten sind im Wassersport-Paket enthalten?" }, { "it", "Quali attività comprende il pacchetto di sport acquatici?" }, { "fr", "Quelles activités comprend le forfait sports nautiques (Water Sport) ?" }, { "ru", "Какие развлечения входят в пакет водных видов спорта (Water Sport)?" } }, Answers = new Dictionary<string, string> { { "en", "This multi-activity adrenaline package includes round-trip hotel transfers, safety briefing, professional life vests, and thrilling rides including the high-speed Banana Boat, the bouncing Crazy Sofa tube behind a fast speedboat, and optional parasailing or wakeboarding depending on the booked tier." }, { "de", "Dieses Adrenalin-Kombipaket beinhaltet den Hoteltransfer, Sicherheitseinweisung, zertifizierte Schwimmwesten und rasante Fahrten: das beliebte Bananenboot, das federnde Crazy Sofa hinter einem Schnellboot sowie je nach gebuchter Variante Parasailing oder Wakeboarding." }, { "it", "Questo pacchetto combinato include transfer da/per hotel, spiegazione sulla sicurezza, giubbotti salvagente e attrazioni ad alta velocità: banana boat, il ciambellone gonfiabile Crazy Sofa trainato da motoscafo potente e, a seconda del pacchetto, parasailing o sci nautico." }, { "fr", "Ce forfait à sensations comprend les transferts, le briefing, les gilets de sauvetage certifiés et des tours exaltants : banane tractée, bouée Crazy Sofa remorquée à toute vitesse, et selon l'option choisie, parachute ascensionnel ou wakeboard." }, { "ru", "Этот комбинированный пакет включает трансфер из отеля, спасательные жилеты, инструктаж и драйвовые катания: скоростной банан, надувной диван Crazy Sofa за мощным катером, а также парасейлинг или вейкбординг в зависимости от выбранного тарифа." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is the water sport activity safe for children and non-swimmers?" }, { "de", "Sind die Wassersportaktivitäten für Kinder und Nichtschwimmer sicher?" }, { "it", "Gli sport acquatici sono sicuri per bambini e non nuotatori?" }, { "fr", "Ces activités nautiques sont-elles sûres pour les enfants et les non-nageurs ?" }, { "ru", "Безопасны ли эти водные аттракционы для детей и тех, кто не умеет плавать?" } }, Answers = new Dictionary<string, string> { { "en", "Yes. Every participant is fitted with a securely fastened USCG-approved life vest. Our speedboat captains adjust the speed and bumps to suit family preferences, offering gentle glides for kids and families or high-octane twists for thrill-seekers." }, { "de", "Ja. Jeder Gast erhält eine ohnmachtssichere Schwimmweste. Die Bootsführer passen die Geschwindigkeit flexibel an Ihre Wünsche an – sanft und sicher für Familien mit Kindern oder rasant und actionreich für Adrenalin-Fans." }, { "it", "Sì. Ogni ospite indossa un giubbotto salvagente omologato ad alta galleggiabilità. I piloti regolano la velocità su misura: andatura dolce e divertente per famiglie con bambini o curve mozzafiato per chi cerca adrenalina." }, { "fr", "Oui. Tout le monde porte un gilet de sauvetage aux normes. Nos pilotes adaptent l'allure à vos souhaits : glisse douce et tranquille pour les enfants ou virages serrés riches en sensations fortes pour les amateurs d'adrénaline." }, { "ru", "Да. Всем участникам надевают сертифицированные спасательные жилеты. Капитан катера регулирует скорость под ваши пожелания: мягкое спокойное катание для детей и семей или крутые виражи и брызги для любителей экстрима." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "How long is the experience and what is the schedule?" }, { "de", "Wie lange dauert das Erlebnis und wie ist der Ablauf?" }, { "it", "Quanto dura l'esperienza e qual è la tempistica?" }, { "fr", "Combien de temps dure l'activité et comment se déroule-t-elle ?" }, { "ru", "Сколько длится катание и как устроен график поездки?" } }, Answers = new Dictionary<string, string> { { "en", "Active water time is approximately 15 to 30 minutes of exhilarating riding across multiple inflatables. Total excursion duration with hotel pickups and beach station preparation is about 1.5 to 2 hours, with flexible morning and afternoon departures." }, { "de", "Die reine Fahrzeit auf dem Wasser beträgt etwa 15 bis 30 Minuten auf verschiedenen Geräten. Die Gesamtdauer inklusive Abholung und Vorbereitung an der Wassersportstation liegt bei ca. 1,5 bis 2 Stunden mit flexiblen Zeiten." }, { "it", "Il tempo effettivo di azione in mare è di circa 15-30 minuti suddivisi tra le attrazioni gonfiabili. Con i trasferimenti e la preparazione la durata complessiva è di circa 1,5 - 2 ore, con partenze al mattino o pomeriggio." }, { "fr", "Le temps actif sur l'eau est d'environ 15 à 30 minutes de sensations. Avec les transferts et l'installation, comptez 1h30 à 2 heures au total. Départs disponibles le matin ou l'après-midi." }, { "ru", "Чистое время активного катания на воде составляет от 15 до 30 минут на разных аттракционах. С учетом трансфера из отеля и инструктажа на станции вся поездка занимает 1,5-2 часа. Доступны утренние и дневные выезды." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear and bring for water sports?" }, { "de", "Was sollte ich für den Wassersport anziehen und mitbringen?" }, { "it", "Cosa indossare e portare per fare sport acquatici?" }, { "fr", "Que faut-il porter et apporter pour les activités nautiques ?" }, { "ru", "Что надеть и взять с собой на водные развлечения?" } }, Answers = new Dictionary<string, string> { { "en", "Wear well-fitting swimwear, bring a beach towel, sunscreen, and leave all loose items, sunglasses, hats, and jewellery in the station storage before boarding to prevent losing them in the sea." }, { "de", "Fest sitzende Badekleidung tragen, Badetuch und Sonnencreme mitbringen. Lose Gegenstände wie Sonnenbrillen, Mützen oder Schmuck bitte vorab in den Schließfächern an Land deponieren." }, { "it", "Indossate costumi ben aderenti, portate telo mare e crema solare. Si raccomanda di lasciare occhiali, cappelli e gioielli negli armadietti della base per evitare di perderli tra le onde." }, { "fr", "Prévoyez un maillot bien ajusté, une serviette et de la crème solaire. Déposez lunettes, casquettes et bijoux dans les casiers sécurisés au club avant d'embarquer pour ne rien égarer en mer." }, { "ru", "Наденьте плотно сидящий купальник, возьмите отельное полотенце и крем от солнца. Очки, панамы, цепочки и украшения лучше оставить в шкафчике на берегу, чтобы не потерять их в море." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193210.jpg", Captions = new Dictionary<string, string> { { "en", "Water Sport - Experience" }, { "de", "Wassersport-Erlebnis Rotes Meer - Erlebnis" }, { "it", "Pacchetto Sport Acquatici sul Mar Rosso - Esperienza" }, { "fr", "Sports Nautiques en Mer Rouge - Expérience" }, { "ru", "Водные виды спорта на Красном море - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193219.jpg", Captions = new Dictionary<string, string> { { "en", "Water Sport - Experience" }, { "de", "Wassersport-Erlebnis Rotes Meer - Erlebnis" }, { "it", "Pacchetto Sport Acquatici sul Mar Rosso - Esperienza" }, { "fr", "Sports Nautiques en Mer Rouge - Expérience" }, { "ru", "Водные виды спорта на Красном море - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193224.jpg", Captions = new Dictionary<string, string> { { "en", "Water Sport - Experience" }, { "de", "Wassersport-Erlebnis Rotes Meer - Erlebnis" }, { "it", "Pacchetto Sport Acquatici sul Mar Rosso - Esperienza" }, { "fr", "Sports Nautiques en Mer Rouge - Expérience" }, { "ru", "Водные виды спорта на Красном море - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Parachute" }, { "de", "Parasailing über dem Roten Meer" }, { "it", "Parasailing Panoramico" }, { "fr", "Vol en Parachute Ascensionnel" }, { "ru", "Парасейлинг над Красным морем" } },
                Descriptions = new Dictionary<string, string> { { "en", "Rise above the Red Sea on a parasailing flight and enjoy panoramic views of Hurghada's coastline from the air. A short, exciting activity that works well as an add-on to a beach or boat day." }, { "de", "Schweben Sie hoch über dem Roten Meer und genießen Sie atemberaubende Panoramaausblicke auf die Küste Hurghadas. Ein aufregendes, schwereloses Flugerlebnis, das sich ideal als Highlight zu einem Strand- oder Bootstag empfiehlt." }, { "it", "Spiccate il volo sopra il Mar Rosso e ammirate spettacolari panorami della costa di Hurghada dall'alto con un indimenticabile volo in parasailing. Un'attività emozionante e suggestiva, ideale per arricchire la vostra giornata balneare." }, { "fr", "Élevez-vous au-dessus des eaux cristallines de la mer Rouge lors d'un vol en parachute ascensionnel et admirez le littoral d'Hurghada vu du ciel. Un instant grisant de sérénité et de panoramas grandioses." }, { "ru", "Взмойте ввысь над лазурным Красным морем на парасейлинге и насладитесь захватывающими панорамными видами на побережье Хургады с высоты птичьего полета. Яркое, безопасное и эмоциональное дополнение к вашему отдыху." } },
                Price = 15,
                Currency = "EUR",
                Duration = "Approx. 10-20 minutes flight; total activity usually 1-2 hours",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000011"),
                CategoryId = Guid.Parse("00000000-0000-0000-0000-000000000007"),
                Emoji = "🌊",
                ImageUrl = "/images/tours/5861626853276193198.jpg",
                MediaUrls = new List<string> { "/images/tours/5861626853276193198.jpg", "/images/tours/5861626853276193225.jpg", "/images/tours/5861626853276193229.jpg" },
                ReserveAndPayLater = true,
                HotelPickup = true,
                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Parachute (Parasailing) tour?" }, { "de", "Was ist bei der Parasailing-Tour (Fallschirm) inbegriffen?" }, { "it", "Cosa comprende l'esperienza di volo con paracadute ascensionale (Parasailing)?" }, { "fr", "Qu'est-ce qui est inclus dans le vol en parachute ascensionnel (Parasailing) ?" }, { "ru", "Что входит в полет на парашюте за катером (Parasailing)?" } }, Answers = new Dictionary<string, string> { { "en", "The tour includes hotel pickup and return, speedboat transfer to the flight zone, professional harness and life vest, safety briefing, and a glorious 10 to 12 minute panoramic parasailing flight 100 to 150 meters above the Red Sea (available as solo or tandem for pairs)." }, { "de", "Der Ausflug umfasst Hoteltransfer, Schnellbootfahrt zur Flugzone, Sicherheitsgeschirr, Schwimmweste, Einweisung und einen fantastischen 10- bis 12-minütigen Panoramaflug 100 bis 150 Meter über dem Roten Meer (als Einzelflug oder Tandemflug für zwei Personen)." }, { "it", "Il tour comprende transfer dall'hotel a/r, corsa in motoscafo verso l'area di decollo, imbragatura omologata, salvagente, briefing e uno spettacolare volo di 10-12 minuti a 100-150 metri sul livello del mare (singolo o in tandem per due persone)." }, { "fr", "La sortie inclut le transfert hôtel, la navette en bateau jusqu'à la zone de vol, le harnais de sécurité, le gilet, le briefing et un vol panoramique exceptionnel de 10 à 12 minutes à 100-150 mètres d'altitude (en solo ou en tandem à deux)." }, { "ru", "В тур входят трансфер из отеля, выезд на катере в зону полетов, страховочная система, спасательный жилет, инструктаж и панорамный полет на парашюте 10-12 минут на высоте 100-150 метров над морем (одиночный или тандем для двоих)." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Can two people fly together (tandem) and is there a weight limit?" }, { "de", "Können zwei Personen zusammen fliegen (Tandem) und gibt es ein Gewichtslimit?" }, { "it", "È possibile volare in coppia (tandem) e quali sono i limiti di peso?" }, { "fr", "Peut-on voler en duo (tandem) et quelle est la limite de poids ?" }, { "ru", "Можно ли лететь вдвоем (тандемом) и какой весовой лимит?" } }, Answers = new Dictionary<string, string> { { "en", "Yes, tandem flights are extremely popular for couples, friends, or parents with children. For safety, the combined weight for a tandem flight should typically not exceed 150 to 170 kg (subject to prevailing wind conditions evaluated by the captain)." }, { "de", "Ja, Tandemflüge sind bei Paaren, Freunden und Eltern mit Kind sehr beliebt. Aus Sicherheitsgründen liegt das Maximalgewicht für zwei Personen meist bei ca. 150 bis 170 kg (je nach Windstärke vom Kapitän geprüft)." }, { "it", "Sì, i voli in tandem sono richiestissimi per coppie, amici o genitori con figli. Per garantire la massima sicurezza, il peso combinato non deve generalmente superare i 150-170 kg (valutato dal comandante in base al vento)." }, { "fr", "Oui, les vols en tandem sont idéaux en couple ou parent-enfant. Pour des raisons aérodynamiques, le poids combiné des deux passagers ne doit pas dépasser 150 à 170 kg (ajusté par le capitaine selon le vent)." }, { "ru", "Да, парные полеты очень популярны среди пар и родителей с детьми. В целях безопасности суммарный вес двух человек обычно не должен превышать 150-170 кг (окончательное решение принимает капитан по силе ветра)." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Do I take off and land in the water, or on the boat deck?" }, { "de", "Startet und landet man im Wasser oder trocken auf dem Bootsdeck?" }, { "it", "Si decolla e atterra in acqua oppure all'asciutto sulla piattaforma della barca?" }, { "fr", "Décolle-t-on et atterrit-on dans l'eau ou au sec sur le bateau ?" }, { "ru", "Взлет и посадка происходят в воду или сухими на палубу катера?" } }, Answers = new Dictionary<string, string> { { "en", "You take off and land smoothly directly on the hydraulic rear flight platform of the specialized parasail boat. You stay completely dry unless you explicitly ask the captain for a playful gentle 'toe-dip' in the sea before reeling you back in!" }, { "de", "Start und Landung erfolgen sanft und vollkommen trocken direkt auf der hydraulischen Startplattform am Heck des Bootes. Sie werden nicht nass – es sei denn, Sie wünschen beim Kapitän einen kurzen, lustigen Wasserkontakt der Zehen!" }, { "it", "Decollo e atterraggio avvengono in totale dolcezza e all'asciutto direttamente sulla plancetta posteriore idraulica del motoscafo. Si resta asciutti, a meno che non chiediate al capitano un divertente 'tuffetto dei piedi' in acqua prima del rientro!" }, { "fr", "Le décollage et l'amerrissage s'effectuent tout en douceur et au sec sur la plateforme arrière hydraulique du bateau. Vous restez sec, sauf si vous demandez au capitaine un petit trempage rafraîchissant des pieds juste avant l'atterrissage !" }, { "ru", "Взлет и посадка происходят плавно и абсолютно всухую прямо со специальной гидравлической площадки на корме катера. Вы остаетесь сухими, если только сами не попросите капитана слегка 'окунуть ноги' в воду перед посадкой!" } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear and can I bring a phone or action camera in the air?" }, { "de", "Was soll ich anziehen und darf man Smartphone oder Actioncam in die Luft mitnehmen?" }, { "it", "Cosa indossare e si può portare il telefono o la GoPro in volo?" }, { "fr", "Que porter et peut-on emmener son téléphone ou sa caméra en vol ?" }, { "ru", "Что надеть и разрешено ли брать с собой телефон или экшн-камеру в полет?" } }, Answers = new Dictionary<string, string> { { "en", "Wear comfortable beachwear or shorts and t-shirt. You may bring your smartphone or GoPro in the air, provided it has a secure wrist lanyard or chest harness. The boat crew also offers professional photo and video packages." }, { "de", "Bequeme Strandkleidung oder Shorts und T-Shirt tragen. Sie dürfen Ihr Smartphone oder eine GoPro mit in die Luft nehmen, wenn diese mit einer Handgelenkschlaufe gesichert ist. Die Crew bietet auch professionelle Foto-/Videoaufnahmen an." }, { "it", "Indossate abiti da spiaggia comodi o pantaloncini e t-shirt. È consentito portare lo smartphone o una GoPro se fissati con laccetto di sicurezza al polso o pettorina. L'equipaggio offre anche pacchetti fotografici professionali." }, { "fr", "Portez une tenue de plage ou un short et t-shirt. Vous pouvez emporter votre téléphone ou caméra d'action si elle est solidement attachée à une dragonne. L'équipage propose également un reportage photo/vidéo pro." }, { "ru", "Наденьте купальник или легкие шорты с футболкой. Телефон или GoPro можно взять с собой в воздух только при наличии надежного шнурка на запястье или крепления на грудь. Также команда катера предлагает услуги фото- и видеосъемки." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193198.jpg", Captions = new Dictionary<string, string> { { "en", "Parachute - Experience" }, { "de", "Parasailing über dem Roten Meer - Erlebnis" }, { "it", "Parasailing Panoramico - Esperienza" }, { "fr", "Vol en Parachute Ascensionnel - Expérience" }, { "ru", "Парасейлинг над Красным морем - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193225.jpg", Captions = new Dictionary<string, string> { { "en", "Parachute - Experience" }, { "de", "Parasailing über dem Roten Meer - Erlebnis" }, { "it", "Parasailing Panoramico - Esperienza" }, { "fr", "Vol en Parachute Ascensionnel - Expérience" }, { "ru", "Парасейлинг над Красным морем - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193229.jpg", Captions = new Dictionary<string, string> { { "en", "Parachute - Experience" }, { "de", "Parasailing über dem Roten Meer - Erlebnis" }, { "it", "Parasailing Panoramico - Esperienza" }, { "fr", "Vol en Parachute Ascensionnel - Expérience" }, { "ru", "Парасейлинг над Красным морем - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Sunrise Horse Riding" }, { "de", "Reitausflug zum Sonnenaufgang" }, { "it", "Passeggiata a Cavallo all'Alba" }, { "fr", "Balade Équestre au Lever du Soleil" }, { "ru", "Конная прогулка на рассвете" } },
                Descriptions = new Dictionary<string, string> { { "en", "Start the day with a peaceful sunrise horse ride through the desert and/or along the Red Sea coast. The experience combines nature, fresh morning air and an authentic way to explore the landscape." }, { "de", "Beginnen Sie den Tag in vollkommener Ruhe bei einem Reitausflug zum Sonnenaufgang durch die unberührte Wüste und entlang der Küste des Roten Meeres. Erleben Sie das sanfte Morgenlicht, reine Wüstenluft und edle Pferde in herrlicher Naturkulisse." }, { "it", "Iniziate la giornata nell'incanto silenzioso dell'alba con un'esclusiva passeggiata a cavallo nel deserto e lungo la riva del Mar Rosso. Un'esperienza autentica a contatto con la natura, accarezzati dalla brezza mattutina e dai riflessi dorati del sole." }, { "fr", "Commencez votre journée en toute sérénité par une promenade à cheval au lever du soleil à travers les dunes et le long du rivage de la mer Rouge. Une échappée poétique alliant nature sauvage, air pur matinal et noblesse équestre." }, { "ru", "Встретьте новый день в гармонии и тишине во время конной прогулки на рассвете по пустынным просторам и вдоль кромки Красного моря. Свежий утренний бриз, первые лучи солнца и единение с благородными скакунами подарят незабываемые впечатления." } },
                Price = 45,
                Currency = "EUR",
                Duration = "Approx. 1.5-3 hours",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000011"),
                CategoryId = Guid.Parse("00000000-0000-0000-0000-000000000005"),
                Emoji = "🏜️",
                ImageUrl = "/images/tours/5861626853276193197.jpg",
                MediaUrls = new List<string> { "/images/tours/5861626853276193197.jpg", "/images/tours/5861626853276193199.jpg", "/images/tours/5861626853276193202.jpg" },
                ReserveAndPayLater = true,
                HotelPickup = true,
                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Sunrise Horse Riding tour?" }, { "de", "Was ist in der Sonnenaufgangs-Reittour enthalten?" }, { "it", "Cosa comprende la passeggiata a cavallo all'alba?" }, { "fr", "Qu'est-ce qui est inclus dans la balade à cheval au lever du soleil ?" }, { "ru", "Что включено в конную прогулку на рассвете (Sunrise Horse Riding)?" } }, Answers = new Dictionary<string, string> { { "en", "The excursion includes round-trip hotel transfers, safety helmets, an experienced equestrian guide, and a serene 1.5 to 2-hour ride through morning desert trails and along the calm shores of the Red Sea as the sun emerges over the horizon. Horses can wade gently into shallow sea waters for magical photos." }, { "de", "Der Ausflug beinhaltet den Hoteltransfer, Schutzhelme, einen erfahrenen Reitführer und einen friedlichen 1,5- bis 2-stündigen Ritt durch Wüstenpfade und entlang des Ufers des Roten Meeres im Licht der Morgensonne. Die Pferde waten für traumhafte Fotos auch sanft ins seichte Wasser." }, { "it", "Il tour comprende trasferimenti a/r dall'hotel, cap protettivo omologato, guida equestre esperta e una suggestiva cavalcata di 1,5-2 ore tra dune desertiche e bagnasciuga del Mar Rosso mentre sorge il sole. I cavalli possono passeggiare anche nel bagnasciuga per foto indimenticabili." }, { "fr", "La balade comprend les transferts hôtel, les bombes de protection, un guide équestre professionnel et 1h30 à 2h d'équitation paisible à travers les sentiers du désert et le long de la plage au lever du soleil, avec passage des chevaux dans l'eau turquoise pour de superbes clichés." }, { "ru", "В стоимость входят трансфер из отеля, защитные шлемы, опытный инструктор-берейтор и 1,5-2 часа утренней верховой прогулки по пустыне и вдоль морского побережья на фоне восходящего солнца. Лошади могут заходить в морскую воду для эффектных фотографий." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is this horse riding experience suitable for total beginners and children?" }, { "de", "Ist der Ausritt für absolute Anfänger und Kinder geeignet?" }, { "it", "L'esperienza a cavallo è adatta a principianti assoluti e bambini?" }, { "fr", "Cette sortie à cheval convient-elle aux débutants complets et aux enfants ?" }, { "ru", "Подходит ли верховая езда для новичков без опыта и детей?" } }, Answers = new Dictionary<string, string> { { "en", "Yes! Our well-trained, docile Arabian and crossbred horses are matched carefully to your riding skill level. For beginners and young children (from 5 years old), guides walk alongside holding a lead rope throughout the journey to ensure total safety." }, { "de", "Ja! Unsere ausgeglichenen, gut trainierten Araber- und Reitpferde werden sorgfältig auf Ihren Erfahrungsstand abgestimmt. Für Einsteiger und Kinder ab 5 Jahren führen die Guides die Pferde während des gesamten Ritts sicher am Führstrick." }, { "it", "Sì! I nostri cavalli arabi e incroci sono dolci, calmi e scelti in base al vostro livello. Per principianti e bambini (dai 5 anni), gli istruttori affiancano i cavalli a piedi conducendoli con la corda per una sicurezza totale." }, { "fr", "Oui ! Nos chevaux arabes et croisés sont doux, calmes et attribués selon votre niveau. Pour les débutants et les enfants dès 5 ans, les guides mènent la monture à la longe tout au long du parcours pour une sécurité absolue." }, { "ru", "Да! Спокойные и выезженные лошади подбираются строго под уровень наездника. Для начинающих и детей (от 5 лет) инструктор идет рядом и ведет лошадь под уздцы на протяжении всей прогулки." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the pickup time and what should I wear?" }, { "de", "Wann ist die Abholung und welche Kleidung wird empfohlen?" }, { "it", "A che ora è la partenza e quale abbigliamento è consigliato?" }, { "fr", "Quelle est l'heure de départ et comment s'habiller ?" }, { "ru", "Во сколько выезд и какая одежда рекомендуется для конной прогулки?" } }, Answers = new Dictionary<string, string> { { "en", "Pickup is early at dawn around 04:45 to 05:30 AM (varying seasonally with sunrise). Wear long comfortable pants (jeans, leggings, or riding trousers) and closed-toe sneakers/shoes. Avoid flip-flops, shorts, or loose scarves." }, { "de", "Die Abholung erfolgt in der Morgendämmerung zwischen 04:45 und 05:30 Uhr (je nach Sonnenaufgangszeit). Bitte lange bequeme Hosen (Jeans oder Leggings) und feste geschlossene Sportschuhe tragen. Keine Shorts, Sandalen oder wehende Schals." }, { "it", "La partenza è all'alba, indicativamente tra le 04:45 e le 05:30 (in base all'ora esatta in cui sorge il sole). Indossate pantaloni lunghi comodi (jeans o leggings) e scarpe da ginnastica chiuse. Evitare ciabatte, pantaloncini o sciarpe svolazzanti." }, { "fr", "Départ aux aurores entre 04h45 et 05h30 selon la saison. Portez un pantalon long confortable (jean, legging) et des chaussures de sport fermées. Évitez les tongs, les shorts et les écharpes flottantes." }, { "ru", "Выезд на рассвете около 04:45 - 05:30 (зависит от времени восхода солнца по сезону). Обязательно наденьте длинные удобные брюки (джинсы или легинсы) и закрытую спортивную обувь (кроссовки). Шорты и шлепанцы запрещены." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is there a maximum rider weight limit?" }, { "de", "Gibt es ein Höchstgewicht für Reiter?" }, { "it", "C'è un limite di peso massimo per i cavalieri?" }, { "fr", "Existe-t-il une limite de poids pour monter à cheval ?" }, { "ru", "Есть ли ограничение по весу для всадника?" } }, Answers = new Dictionary<string, string> { { "en", "For animal welfare and rider safety, the standard maximum rider weight is 100 kg (approx. 220 lbs). Please inform us upon booking so our stables can reserve an appropriately sized horse." }, { "de", "Aus Gründen des Tierwohls und der Reitersicherheit liegt das zulässige Höchstgewicht bei ca. 100 kg. Bitte teilen Sie uns Ihr ungefähres Gewicht bei der Buchung mit, damit ein passendes Pferd reserviert wird." }, { "it", "Per la tutela e il benessere dei cavalli, il peso massimo consentito è di 100 kg. Vi preghiamo di segnalarlo al momento della prenotazione per assegnarvi il cavallo più idoneo." }, { "fr", "Pour le respect du cheval et votre sécurité, la limite de poids maximale est fixée à 100 kg. Merci de préciser votre gabarit à la réservation afin de vous préparer la monture adéquate." }, { "ru", "Для заботы о здоровье лошадей максимальный вес всадника составляет 100 кг. Пожалуйста, укажите ваши данные при бронировании, чтобы конюшня подобрала подходящую сильную лошадь." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193197.jpg", Captions = new Dictionary<string, string> { { "en", "Sunrise Horse Riding - Experience" }, { "de", "Reitausflug zum Sonnenaufgang - Erlebnis" }, { "it", "Passeggiata a Cavallo all'Alba - Esperienza" }, { "fr", "Balade Équestre au Lever du Soleil - Expérience" }, { "ru", "Конная прогулка на рассвете - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193199.jpg", Captions = new Dictionary<string, string> { { "en", "Sunrise Horse Riding - Experience" }, { "de", "Reitausflug zum Sonnenaufgang - Erlebnis" }, { "it", "Passeggiata a Cavallo all'Alba - Esperienza" }, { "fr", "Balade Équestre au Lever du Soleil - Expérience" }, { "ru", "Конная прогулка на рассвете - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193202.jpg", Captions = new Dictionary<string, string> { { "en", "Sunrise Horse Riding - Experience" }, { "de", "Reitausflug zum Sonnenaufgang - Erlebnis" }, { "it", "Passeggiata a Cavallo all'Alba - Esperienza" }, { "fr", "Balade Équestre au Lever du Soleil - Expérience" }, { "ru", "Конная прогулка на рассвете - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Safari Quad Sunset" }, { "de", "Quad-Safari zum Sonnenuntergang" }, { "it", "Quad Safari al Tramonto" }, { "fr", "Safari en Quad au Coucher du Soleil" }, { "ru", "Сафари на квадроциклах на закате" } },
                Descriptions = new Dictionary<string, string> { { "en", "Ride a quad bike through the desert at sunset, enjoying wide-open landscapes and the changing colours of the Red Sea desert. A popular short adventure for guests who want action without committing to a full safari." }, { "de", "Steuern Sie Ihr eigenes Quad durch die Weiten der Wüste im magischen Licht der Dämmerung und erleben Sie das Farbenspiel des Sonnenuntergangs über den Bergen des Roten Meeres. Ein dynamisches, kompaktes Wüstenabenteuer für Abenteuerlustige." }, { "it", "Guidate un potente quad attraverso gli scenari sconfinati del deserto al tramonto, ammirando le sfumature calde del crepuscolo sulle montagne del Mar Rosso. Un'avventura dinamica ed emozionante per vivere la magia del deserto." }, { "fr", "Pilotez votre quad à travers les grands espaces désertiques au crépuscule et laissez-vous émerveiller par les teintes flamboyantes du soleil se couchant derrière les montagnes. Une aventure palpitante et accessible pour savourer la magie du désert." }, { "ru", "Прокатитесь на мощном квадроцикле по бескрайней пустыне в лучах заходящего солнца, любуясь чарующей игрой красок на фоне гор Красного моря. Динамичное и яркое приключение для тех, кто ценит скорость и живописные пейзажи." } },
                Price = 35,
                Currency = "EUR",
                Duration = "Approx. 2-4 hours",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000011"),
                CategoryId = Guid.Parse("00000000-0000-0000-0000-000000000005"),
                Emoji = "🏜️",
                ImageUrl = "/images/tours/5861626853276193279.jpg",
                MediaUrls = new List<string> { "/images/tours/5861626853276193279.jpg", "/images/tours/5861626853276193229.jpg", "/images/tours/5861626853276193234.jpg" },
                ReserveAndPayLater = true,
                HotelPickup = true,
                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Sunset Quad Safari tour?" }, { "de", "Was ist in der Quad-Safari bei Sonnenuntergang enthalten?" }, { "it", "Cosa comprende la safari in quad al tramonto?" }, { "fr", "Qu'est-ce qui est inclus dans le safari en quad au coucher du soleil ?" }, { "ru", "Что входит в вечернее сафари на квадроциклах на закате (Safari Quad Sunset)?" } }, Answers = new Dictionary<string, string> { { "en", "The tour includes hotel pickup and return in an air-conditioned van, rental of an automatic 250cc-400cc quad ATV, a test drive tutorial, protective helmet, a guided 25-30 km desert trail ride, a photo stop at panoramic dunes during sunset, and traditional Bedouin herbal tea in an authentic desert tent." }, { "de", "Die Tour beinhaltet Hoteltransfer, automatisches Quad (250–400 ccm), Einweisung mit Probefahrt, Schutzhelm, ca. 25–30 km geführte Wüstenfahrt, Fotostopp auf Sanddünen im Abendrot sowie echten Beduinentee im Wüstenzelt." }, { "it", "Il tour comprende navetta climatizzata da/per hotel, noleggio quad automatico da 250-400cc, prova pratica di guida, casco protettivo, circa 25-30 km di percorso guidato nel deserto, sosta fotografica sulle dune al tramonto e tè beduino nella tenda nomade." }, { "fr", "Le safari comprend les transferts en van climatisé, un quad automatique 250-400cc, briefing et essai de conduite, casque, environ 25-30 km de pilotage dans les pistes du désert, arrêt photo sur les dunes au coucher du soleil et thé bédouin traditionnel." }, { "ru", "В тур включены трансфер из отеля, аренда автоматического квадроцикла 250-400 куб.см, тест-драйв, защитный шлем, заезд по пустыне 25-30 км с гидом, остановка для фото на барханах на закате и традиционный бедуинский чай в шатре." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the minimum age to drive a quad bike?" }, { "de", "Wie alt muss man sein, um ein Quad selbst zu fahren?" }, { "it", "Qual è l'età minima per guidare un quad?" }, { "fr", "Quel est l'âge minimum pour conduire un quad ?" }, { "ru", "С какого возраста разрешено самостоятельно управлять квадроциклом?" } }, Answers = new Dictionary<string, string> { { "en", "The minimum driving age is 16 years. Children aged 10 to 15 are welcome to join as passengers on a double quad seated behind a paying parent or adult guardian." }, { "de", "Das Mindestalter für Einzelfahrer beträgt 16 Jahre. Kinder von 10 bis 15 Jahren dürfen als Beifahrer auf einem Doppelquad hinter einem Erwachsenen mitfahren." }, { "it", "L'età minima per guidare il quad è di 16 anni. I ragazzi da 10 a 15 anni possono partecipare come passeggeri su un quad doppio seduti dietro a un genitore o adulto." }, { "fr", "L'âge minimum pour piloter est de 16 ans. Les enfants âgés de 10 à 15 ans peuvent participer en tant que passagers sur un quad biplace derrière un adulte." }, { "ru", "Самостоятельно управлять квадроциклом разрешено с 16 лет. Дети от 10 до 15 лет могут ехать пассажирами на двухместном квадроцикле сзади родителя или взрослого." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear and bring for quad biking?" }, { "de", "Was soll ich für die Quad-Tour anziehen und mitnehmen?" }, { "it", "Come vestirsi e cosa portare per l'escursione in quad?" }, { "fr", "Que faut-il porter et apporter pour le quad dans le désert ?" }, { "ru", "Что надеть и взять с собой на квадроциклы?" } }, Answers = new Dictionary<string, string> { { "en", "Wear comfortable casual clothes you do not mind getting dusty, closed sneakers or trainers (strictly no flip-flops), and bring sunglasses and a traditional cotton scarf (arafat) to protect your face from dust. Arafat scarves and dust goggles are also available to purchase at the safari station." }, { "de", "Bequeme Kleidung anziehen, die staubig werden darf, feste geschlossene Turnschuhe (keine Sandalen/Flip-Flops), Sonnenbrille und ein Wüstentuch (Arafat) zum Schutz vor Sand. Tücher und Staubbrillen können auch vor Ort erworben werden." }, { "it", "Indossate abiti comodi che non temano la polvere, scarpe chiuse da tennis (assolutamente no infradito), occhiali da sole e la classica kefiah (sciarpa beduina) contro la polvere, acquistabile anche direttamente alla base safari." }, { "fr", "Mettez des vêtements confortables pouvant prendre la poussière, des baskets fermées (tongs interdites), lunettes de soleil et un chèche (écharpe bédouine) pour le visage, vendu aussi sur place à petit prix." }, { "ru", "Наденьте практичную одежду, которую не жалко запылить, закрытую обувь (кроссовки, шлепанцы строго запрещены), солнцезащитные очки и платок-арафатку для защиты от песка (арафатки и защитные очки можно купить на базе)." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is the quad tour safe for pregnant women or people with back problems?" }, { "de", "Ist die Quad-Tour für Schwangere oder Personen mit Rückenbeschwerden geeignet?" }, { "it", "Il tour in quad è sicuro per donne in gravidanza o persone con problemi alla schiena?" }, { "fr", "Le quad est-il adapté aux femmes enceintes ou aux personnes ayant des maux de dos ?" }, { "ru", "Безопасно ли катание на квадроциклах для беременных женщин и людей с болью в спине?" } }, Answers = new Dictionary<string, string> { { "en", "For safety and medical reasons, quad biking is strictly not permitted for pregnant women or individuals with spinal injuries, recent surgeries, or acute back disorders due to desert bumps and vibrations." }, { "de", "Aus Sicherheits- und Gesundheitsgründen ist die Quad-Fahrt für Schwangere sowie Personen mit Wirbelsäulen- oder akuten Rückenproblemen wegen Bodenunebenheiten und Erschütterungen nicht gestattet." }, { "it", "Per ragioni di sicurezza medica, l'escursione in quad è severamente vietata a donne in dolce attesa e a persone con patologie vertebrali o recenti interventi alla schiena a causa delle vibrazioni." }, { "fr", "Pour des raisons médicales, le quad est strictement interdit aux femmes enceintes ainsi qu'aux personnes souffrant de problèmes de colonne vertébrale ou de dos en raison des secousses du terrain." }, { "ru", "В целях безопасности и по медицинским нормам катание на квадроциклах категорически запрещено беременным женщинам и лицам с заболеваниями позвоночника или травмами спины из-за вибраций и кочек." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193279.jpg", Captions = new Dictionary<string, string> { { "en", "Safari Quad Sunset - Experience" }, { "de", "Quad-Safari zum Sonnenuntergang - Erlebnis" }, { "it", "Quad Safari al Tramonto - Esperienza" }, { "fr", "Safari en Quad au Coucher du Soleil - Expérience" }, { "ru", "Сафари на квадроциклах на закате - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193229.jpg", Captions = new Dictionary<string, string> { { "en", "Safari Quad Sunset - Experience" }, { "de", "Quad-Safari zum Sonnenuntergang - Erlebnis" }, { "it", "Quad Safari al Tramonto - Esperienza" }, { "fr", "Safari en Quad au Coucher du Soleil - Expérience" }, { "ru", "Сафари на квадроциклах на закате - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193234.jpg", Captions = new Dictionary<string, string> { { "en", "Safari Quad Sunset - Experience" }, { "de", "Quad-Safari zum Sonnenuntergang - Erlebnis" }, { "it", "Quad Safari al Tramonto - Esperienza" }, { "fr", "Safari en Quad au Coucher du Soleil - Expérience" }, { "ru", "Сафари на квадроциклах на закате - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Motocross Desert" }, { "de", "Motocross Wüsten-Abenteuer" }, { "it", "Motocross nel Deserto" }, { "fr", "Motocross dans le Désert" }, { "ru", "Мотокросс в пустыне" } },
                Descriptions = new Dictionary<string, string> { { "en", "A high-energy off-road experience for guests who enjoy speed and desert terrain. Ride a motocross-style motorcycle on designated tracks and trails under professional guidance." }, { "de", "Ein adrenalingeladenes Offroad-Erlebnis für Motorsport-Enthusiasten und Geschwindigkeitsliebhaber. Meistern Sie anspruchsvolle Dünenpfade und ausgewiesene Naturstrecken auf wendigen Motocross-Maschinen unter professioneller Anleitung." }, { "it", "Un'esperienza off-road ad alta adrenalina dedicata agli amanti della velocità e dei percorsi sterrati. Conducete una moto da motocross su piste e sentieri desertici selezionati sotto la guida esperta di istruttori professionisti." }, { "fr", "Une aventure tout-terrain d'une rare intensité pour les passionnés de vitesse et de sensations pures. Parcourez les pistes désertiques et franchissez les dunes au guidon d'une moto cross sous l'encadrement attentif d'un guide professionnel." }, { "ru", "Заряженное адреналином внедорожное приключение для ценителей скорости и драйва. Управляйте кроссовым мотоциклом на специально подготовленных пустынных трассах и барханах под руководством профессионального инструктора." } },
                Price = 100,
                Currency = "EUR",
