                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Motocross Desert experience?" }, { "de", "Was ist im Motocross-Wüstenerlebnis enthalten?" }, { "it", "Cosa comprende l'esperienza Motocross Desert?" }, { "fr", "Qu'est-ce qui est inclus dans l'aventure Motocross Desert ?" }, { "ru", "Что входит в тур на кроссовых мотоциклах по пустыне (Motocross Desert)?" } }, Answers = new Dictionary<string, string> { { "en", "This premium off-road motorbike adventure includes hotel transfers, a maintained enduro/motocross motorcycle (250cc KTM, Honda, or Yamaha), full professional protective gear (full-face helmet, chest protector, knee & elbow pads, gloves, goggles), fuel, and riding with an expert desert motocross guide across technical sand tracks and mountain trails." }, { "de", "Dieses exklusive Offroad-Motorraderlebnis beinhaltet Hoteltransfers, eine gewartete Enduro-/Motocross-Maschine (250 ccm KTM, Honda oder Yamaha), komplette Profi-Schutzkleidung (Crosshelm, Brustpanzer, Protektoren, Handschuhe, Brille), Benzin und Führung durch einen Wüstenprofi auf technischen Wüsten- und Bergpfaden." }, { "it", "Questa avventura su due ruote comprende transfer dall'hotel, moto da enduro/motocross revisionata (KTM, Honda o Yamaha 250cc), equipaggiamento protettivo professionale completo (casco integrale, pettorina, ginocchiere, gomitiere, guanti, maschera), benzina e guida esperta lungo percorsi tecnici tra canyon e piste sabbiose." }, { "fr", "Cette aventure moto tout-terrain comprend les transferts, une moto d'enduro/cross révisée (KTM, Honda ou Yamaha 250cc), l'équipement de protection complet (casque intégral, gilet pare-pierre, coudières, genouillères, gants), le carburant et un guide pro à travers pistes rapides et zones sablonneuses." }, { "ru", "Этот премиальный мототур по пустыне включает трансфер из отеля, кроссовый мотоцикл эндуро 250 куб.см (KTM, Honda, Yamaha), полный комплект профессиональной экипировки (кроссовый шлем, панцирь-черепаха, наколенники, налокотники, перчатки, очки), бензин и сопровождение опытного инструктора по дюнам и каньонам." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Do I need previous motorcycle riding experience and a motorcycle licence?" }, { "de", "Benötige ich Motorraderfahrung und einen Motorradführerschein?" }, { "it", "Servono esperienza pregressa in moto e la patente specifica?" }, { "fr", "Faut-il une expérience préalable de la moto et un permis moto ?" }, { "ru", "Требуется ли опыт вождения мотоцикла и водительские права категории А?" } }, Answers = new Dictionary<string, string> { { "en", "Prior experience riding a manual clutch motorbike is required, as motocross bikes operate with standard foot-gear shifting. A formal motorcycle driver's licence is recommended, and our guides assess your clutch and balance skills during a mandatory track warmup before entering open desert terrain." }, { "de", "Grundlegende Vorerfahrung mit manueller Kupplung und Fußschaltung auf Motorrädern ist zwingend erforderlich. Ein Führerschein ist ratsam. Vor der Tour in das offene Gelände findet ein obligatorischer Geschicklichkeitstest auf dem Übungsparcours statt." }, { "it", "È richiesta un'esperienza pregressa nella guida di moto a marce manuali con frizione. La patente moto è consigliata. Prima di accedere al deserto aperto, la guida effettua un test obbligatorio di abilità su circuito protetto per valutare la padronanza del mezzo." }, { "fr", "Une expérience préalable de la moto à boîte manuelle et embrayage est indispensable. Un permis moto est recommandé. Un test obligatoire sur piste fermée est effectué par le moniteur avant de partir dans le grand désert." }, { "ru", "Обязателен опыт управления мотоциклом с механической коробкой передач и сцеплением. Водительские права категории А рекомендуются. Перед выездом в пустыню проводится обязательный тест-драйв на площадке базы." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the duration and pacing of the motocross tour?" }, { "de", "Wie lange dauert die Tour und wie wird das Tempo bestimmt?" }, { "it", "Quanto dura il tour e come viene stabilito il ritmo di guida?" }, { "fr", "Quelle est la durée du circuit et comment s'adapte le rythme ?" }, { "ru", "Сколько длится тур на мотоциклах и как подбирается скорость?" } }, Answers = new Dictionary<string, string> { { "en", "The excursion lasts 2 to 3 hours total with around 90 minutes of pure riding action. Groups are kept very small (2 to 5 riders), allowing the guide to calibrate the speed and terrain difficulty to the riders' capabilities." }, { "de", "Der Ausflug dauert insgesamt ca. 2 bis 3 Stunden mit ca. 90 Minuten reiner Fahrzeit. Die Gruppen sind sehr klein (2 bis 5 Fahrer), sodass der Guide das Tempo und das Streckenprofil exakt auf Ihr fahrerisches Können abstimmt." }, { "it", "Il tour dura circa 2-3 ore complessive con 90 minuti effettivi di guida off-road. I gruppi sono ristretti (da 2 a 5 piloti), consentendo alla guida di tarare velocità e difficoltà dei tracciati sulle reali abilità dei partecipanti." }, { "fr", "La sortie dure de 2 à 3 heures avec 1h30 de pilotage effectif. Les groupes sont limités à 2 à 5 motards pour permettre au guide d'adapter l'allure et le niveau technique des sentiers au niveau de chacun." }, { "ru", "Тур длится 2-3 часа, из них около 1,5 часов чистого драйва на мотоцикле. Группы небольшие (2-5 райдеров), благодаря чему инструктор выстраивает темп и сложность трассы индивидуально под уровень группы." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear for desert motocross?" }, { "de", "Was soll ich zum Wüsten-Motocross anziehen?" }, { "it", "Cosa indossare per il motocross nel deserto?" }, { "fr", "Comment s'habiller pour faire du motocross dans le désert ?" }, { "ru", "Как экипироваться для мотокросса в пустыне?" } }, Answers = new Dictionary<string, string> { { "en", "Wear durable long pants (jeans or heavy work pants), tall socks, and sturdy high-ankle boots or solid sneakers. Breathable moisture-wicking shirts are recommended under the provided body armour." }, { "de", "Robuste lange Hosen (Jeans oder feste Arbeitshosen), lange Sportsocken und feste knöchelhohe Schuhe oder feste Sneaker anziehen. Ein atmungsaktives Funktionsshirt unter dem Brustpanzer ist optimal." }, { "it", "Indossate pantaloni lunghi resistenti (jeans spessi), calzettoni alti e scarpe alte alla caviglia o scarponcini da trekking/sneakers robuste. Consigliata maglietta traspirante sotto la pettorina." }, { "fr", "Prévoyez un pantalon long et épais (jean solide), des chaussettes montantes et des chaussures montantes tenant bien la cheville ou de solides baskets. T-shirt respirant conseillé sous l'armure." }, { "ru", "Наденьте плотные длинные брюки (джинсы), высокие носки и прочные ботинки или плотные кроссовки с поддержкой голеностопа. Под защитный панцирь лучше надеть дышащую футболку." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193237.jpg", Captions = new Dictionary<string, string> { { "en", "Motocross Desert - Experience" }, { "de", "Motocross Wüsten-Abenteuer - Erlebnis" }, { "it", "Motocross nel Deserto - Esperienza" }, { "fr", "Motocross dans le Désert - Expérience" }, { "ru", "Мотокросс в пустыне - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193251.jpg", Captions = new Dictionary<string, string> { { "en", "Motocross Desert - Experience" }, { "de", "Motocross Wüsten-Abenteuer - Erlebnis" }, { "it", "Motocross nel Deserto - Esperienza" }, { "fr", "Motocross dans le Désert - Expérience" }, { "ru", "Мотокросс в пустыне - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193252.jpg", Captions = new Dictionary<string, string> { { "en", "Motocross Desert - Experience" }, { "de", "Motocross Wüsten-Abenteuer - Erlebnis" }, { "it", "Motocross nel Deserto - Esperienza" }, { "fr", "Motocross dans le Désert - Expérience" }, { "ru", "Мотокросс в пустыне - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Buggy Safari" }, { "de", "Dünenbuggy-Safari" }, { "it", "Safari in Buggy nel Deserto" }, { "fr", "Safari en Buggy dans le Désert" }, { "ru", "Сафари на багги в пустыне" } },
                Descriptions = new Dictionary<string, string> { { "en", "Take on the desert in a powerful dune buggy, travelling across sandy tracks and open desert landscapes. The experience combines off-road driving, adventure and spectacular desert scenery." }, { "de", "Bezwingen Sie die Weiten der Wüste am Steuer eines kraftvollen Dünenbuggys über sandige Pisten und atemberaubende Landschaften. Die perfekte Symbiose aus sicherem Fahrspaß, purem Abenteuer und grandiosen Panoramen." }, { "it", "Conquistate il deserto al volante di un potente dune buggy, sfrecciando tra piste sabbiose e scenari rocciosi mozzafiato. Un'esperienza che unisce il piacere della guida fuoristrada, il brivido dell'avventura e scorci paesaggistici unici." }, { "fr", "Domptez le désert au volant d'un puissant buggy des sables à travers des pistes sinueuses et de majestueux panoramas sahariens. Une aventure exclusive alliant pilotage tout-terrain sécurisé, adrénaline et décors spectaculaires." }, { "ru", "Покорите просторы пустыни за рулем мощного дюнного багги, преодолевая песчаные трассы и любуясь живописными ландшафтами. Захватывающий баланс комфортного внедорожного вождения, азарта и величественных видов." } },
                Price = 110,
                Currency = "EUR",
                Duration = "Approx. 2-5 hours",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000011"),
                CategoryId = Guid.Parse("00000000-0000-0000-0000-000000000005"),
                Emoji = "🏜️",
                ImageUrl = "/images/tours/5861626853276193199.jpg",
                MediaUrls = new List<string> { "/images/tours/5861626853276193199.jpg", "/images/tours/5861626853276193237.jpg", "/images/tours/5861626853276193284.jpg" },
                ReserveAndPayLater = true,
                HotelPickup = true,
                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Buggy Safari tour?" }, { "de", "Was beinhaltet die Wüsten-Buggy-Safari?" }, { "it", "Cosa comprende il Buggy Safari nel deserto?" }, { "fr", "Qu'est-ce qui est inclus dans le Buggy Safari ?" }, { "ru", "Что входит в сафари на багги (Buggy Safari)?" } }, Answers = new Dictionary<string, string> { { "en", "The tour includes hotel pickup and return in an air-conditioned vehicle, rental of a modern open-cockpit dune buggy (available in 2-seater or 4-seater family configurations) with roll cage and 4-point racing harness belts, protective goggles, a guided 30-35 km desert canyon expedition, and Bedouin tea." }, { "de", "Der Ausflug beinhaltet Hoteltransfers, einen modernen Dünenbuggy (wahlweise als 2-Sitzer oder 4-Sitzer für Familien) mit Überrollkäfig und 4-Punkt-Renngurten, Schutzbrille, eine 30–35 km geführte Wüsten- und Canyontour sowie frischen Beduinentee." }, { "it", "Il tour comprende transfer da/per hotel, noleggio dune buggy moderno (disponibile a 2 posti o 4 posti per famiglie) con roll-bar tubolare e cinture di sicurezza a 4 punti, maschera antipolvere, escursione guidata di 30-35 km tra canyon e dune e tè beduino." }, { "fr", "Le safari comprend les transferts hôtel, le buggy tout-terrain moderne (modèles 2 places ou 4 places famille) équipé d'arceau de sécurité et ceintures harnais 4 points, lunettes anti-poussière, expédition guidée de 30-35 km dans les canyons et thé bédouin." }, { "ru", "В тур включены трансфер из отеля, аренда современного багги (2-местные или 4-местные семейные модели) с каркасом безопасности и 4-точечными спортивными ремнями, защитные очки, заезд на 30-35 км по каньонам и дюнам и чаепитие у бедуинов." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "How is a Buggy different from a Quad bike and why is it recommended for families?" }, { "de", "Wie unterscheidet sich ein Buggy vom Quad und warum ist er ideal für Familien?" }, { "it", "In cosa differisce il Buggy dal Quad ed è indicato per famiglie?" }, { "fr", "Quelle est la différence entre un Buggy et un Quad et pourquoi convient-il aux familles ?" }, { "ru", "Чем багги отличается от квадроцикла и почему он удобнее для семей?" } }, Answers = new Dictionary<string, string> { { "en", "A buggy features a standard car steering wheel, foot accelerator/brake pedals, bucket seats, full roll cages, and multi-point seatbelts. It offers higher stability and protection than a quad bike, allowing parents and kids (from age 4) to sit side-by-side safely." }, { "de", "Ein Buggy hat ein klassisches Autolenkrad, Fußpedale (Gas/Bremse), Schalensitze, Sicherheitskäfig und Renngurte. Er bietet mehr Stabilität und Schutz als ein Quad – Eltern und Kinder (ab 4 Jahren) sitzen bequem nebeneinander." }, { "it", "Il buggy è dotato di classico volante da auto, pedali acceleratore/freno, sedili anatomici, gabbia di protezione e cinture di sicurezza. È più stabile e sicuro del quad e permette a genitori e figli (dai 4 anni) di viaggiare affiancati." }, { "fr", "Le buggy se conduit avec un volant comme une voiture, des pédales accélérateur/frein, des sièges baquets et une cage de protection renforcée. Beaucoup plus stable qu'un quad, il permet aux parents et enfants (dès 4 ans) d'être assis côte à côte en sécurité." }, { "ru", "Багги управляется привычным автомобильным рулем и педалями, оснащен спортивными креслами, каркасом безопасности и ремнями. Он значительно устойчивее квадроцикла и позволяет родителям и детям (от 4 лет) сидеть рядом в одной машине." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What are the age requirements to drive or ride in a buggy?" }, { "de", "Welche Altersvorgaben gelten für Fahrer und Beifahrer im Buggy?" }, { "it", "Quali sono i requisiti d'età per guidare o essere passeggeri sul buggy?" }, { "fr", "Quelles sont les conditions d'âge pour conduire ou monter dans un buggy ?" }, { "ru", "Каковы возрастные ограничения для водителей и пассажиров багги?" } }, Answers = new Dictionary<string, string> { { "en", "Drivers must be at least 18 years old with basic driving familiarity (valid home country driving licence is welcome). Passengers can join from age 4 and up in the passenger or rear seats." }, { "de", "Fahrer müssen mindestens 18 Jahre alt sein und Fahrpraxis besitzen (ein normaler Pkw-Führerschein genügt). Kinder dürfen ab 4 Jahren als Beifahrer mitfahren." }, { "it", "Il conducente deve avere almeno 18 anni ed esperienza di guida con la patente auto. I bambini possono salire come passeggeri a partire dai 4 anni compiuti." }, { "fr", "Les conducteurs doivent être âgés d'au moins 18 ans et savoir conduire (permis de conduire B recommandé). Les passagers sont acceptés dès l'âge de 4 ans." }, { "ru", "Водителю должно быть не менее 18 лет, требуются базовые навыки вождения автомобиля. Пассажирами могут ехать взрослые и дети в возрасте от 4 лет." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should we wear and bring for the Buggy Safari?" }, { "de", "Was sollte man für die Buggy-Safari anziehen und mitbringen?" }, { "it", "Cosa portare e indossare per la safari in buggy?" }, { "fr", "Que faut-il apporter et porter pour la sortie en buggy ?" }, { "ru", "Что надеть и взять с собой на сафари на багги?" } }, Answers = new Dictionary<string, string> { { "en", "Wear comfortable casual clothes that can get dusty, closed sports shoes, and bring sunglasses and an arafat scarf for sand protection. Don't forget your camera or phone to take action photos during trail stops." }, { "de", "Zweckmäßige Freizeitkleidung tragen, die staubig werden darf, feste Turnschuhe sowie Sonnenbrille und Wüstenschal (Arafat) mitnehmen. Smartphone oder Kamera für coole Wüstenfotos einpacken." }, { "it", "Abiti comodi e leggeri che non si rovinano con la sabbia, scarpe da ginnastica chiuse, occhiali da sole e kefiah protettiva. Portate il telefono per scattare foto mozzafiato durante le soste." }, { "fr", "Habits confortables lavables, baskets fermées, lunettes de soleil et foulard bédouin contre la poussière. N'oubliez pas votre téléphone pour immortaliser les paysages désertiques." }, { "ru", "Удобную одежду из натуральных тканей, не маркую, закрытые кроссовки, солнцезащитные очки и платок-арафатку от пыли. Возьмите телефон для ярких фотографий на фоне барханов." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193199.jpg", Captions = new Dictionary<string, string> { { "en", "Buggy Safari - Experience" }, { "de", "Dünenbuggy-Safari - Erlebnis" }, { "it", "Safari in Buggy nel Deserto - Esperienza" }, { "fr", "Safari en Buggy dans le Désert - Expérience" }, { "ru", "Сафари на багги в пустыне - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193237.jpg", Captions = new Dictionary<string, string> { { "en", "Buggy Safari - Experience" }, { "de", "Dünenbuggy-Safari - Erlebnis" }, { "it", "Safari in Buggy nel Deserto - Esperienza" }, { "fr", "Safari en Buggy dans le Désert - Expérience" }, { "ru", "Сафари на багги в пустыне - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193284.jpg", Captions = new Dictionary<string, string> { { "en", "Buggy Safari - Experience" }, { "de", "Dünenbuggy-Safari - Erlebnis" }, { "it", "Safari in Buggy nel Deserto - Esperienza" }, { "fr", "Safari en Buggy dans le Désert - Expérience" }, { "ru", "Сафари на багги в пустыне - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Super Safari" }, { "de", "Große Wüsten-Super-Safari" }, { "it", "Super Safari nel Deserto" }, { "fr", "Grand Super Safari dans le Désert" }, { "ru", "Супер Сафари в пустыне" } },
                Descriptions = new Dictionary<string, string> { { "en", "Experience a classic Red Sea desert safari combining off-road travel, quad biking and Bedouin-style activities. Depending on the package, the evening may include a camel ride, village visit, dinner, entertainment and stargazing." }, { "de", "Das ultimative Wüstenabenteuer am Roten Meer: Kombinieren Sie rasante Jeep- und Quadfahrten mit traditioneller Beduinen-Gastfreundschaft. Freuen Sie sich auf Kamelreiten, ein orientalisches Barbecue-Abendessen unter Sternen, traditionelle Folklore und faszinierende Sternenbeobachtung." }, { "it", "Vivete il fascino intramontabile del deserto con un grande safari che unisce fuoristrada in 4x4, guida in quad e autentica ospitalità beduina. Include passeggiata in cammello, cena barbecue sotto la volta celeste, spettacolo folkloristico e osservazione astronomica." }, { "fr", "L'incontournable safari dans le désert de la mer Rouge alliant raid en 4x4, pilotage de quad et traditions bédouines. Profitez d'une balade à dos de chameau, d'un dîner oriental sous la voûte étoilée, de danses folkloriques et de l'observation des étoiles." }, { "ru", "Классическое гранд-сафари в пустыне Красного моря, объединяющее поездку на джипах, катание на квадроциклах и погружение в бедуинские традиции. В программу входят прогулка на верблюдах, ужин-барбекю под звездным небом, восточное шоу и наблюдение за звездами." } },
                Price = 30,
                Currency = "EUR",
                Duration = "Approx. 5-7 hours",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000011"),
                CategoryId = Guid.Parse("00000000-0000-0000-0000-000000000005"),
                Emoji = "🏜️",
                ImageUrl = "/images/tours/5861626853276193266.jpg",
                MediaUrls = new List<string> { "/images/tours/5861626853276193266.jpg", "/images/tours/5861626853276193272.jpg", "/images/tours/5861626853276193274.jpg" },
                ReserveAndPayLater = true,
                HotelPickup = true,
                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Super Safari (Mega Desert Adventure)?" }, { "de", "Was ist in der Mega Super Safari enthalten?" }, { "it", "Cosa comprende la Super Safari (Mega avventura nel deserto)?" }, { "fr", "Qu'est-ce qui est inclus dans le Super Safari ?" }, { "ru", "Что входит в программу масштабного тура Супер Сафари (Super Safari)?" } }, Answers = new Dictionary<string, string> { { "en", "The Super Safari is our all-in-one ultimate desert day. It includes 4x4 Land Cruiser jeep dune-bashing, driving a quad bike (ATV) for 45 minutes, driving a spider/dune buggy for 20 minutes, visiting a traditional Bedouin village, a camel ride, an open barbecue dinner buffet, folklore evening shows (belly dance, Tanoura, fire show), and night stargazing through high-powered astronomical telescopes." }, { "de", "Die Super Safari ist das ultimative Wüsten-Komplettpaket: Fahrt im 4x4 Land Cruiser durch die Dünen, 45 Min. Quad-Fahren, 20 Min. Spider-Buggy-Fahren, Besuch eines traditionellen Beduinendorfs, Kamelritt, Grill-Abendbuffet, orientalische Show (Bauchtanz, Tanoura, Feuershow) und Sternenbeobachtung durch Lichtteleskope." }, { "it", "La Super Safari è il pacchetto desertico più completo: traversata in jeep 4x4 Land Cruiser tra le dune, 45 minuti di guida del quad, 20 minuti di spider buggy, visita a un autentico villaggio beduino, passeggiata a dorso di cammello, cena barbecue a buffet, show orientale (danza del ventre, dervisci, mangiafuoco) e osservazione delle stelle con telescopio astronomico." }, { "fr", "Le Super Safari réunit toutes les merveilles du désert : franchissement des dunes en 4x4 Land Cruiser, 45 min de quad, 20 min de buggy spider, visite d'un village bédouin, balade à dos de chameau, dîner buffet barbecue, spectacle folklorique (danse orientale, Tanoura, spectacle de feu) et observation du ciel étoilé au télescope." }, { "ru", "Супер Сафари — это максимум впечатлений в одной экскурсии: гонки по дюнам на джипах 4x4 Toyota Land Cruiser, катание на квадроциклах 45 минут, заезд на багги 20 минут, визит в бедуинскую деревню, катание на верблюдах, ужин-барбекю 'шведский стол', шоу-программа (танец живота, танура, фаер-шоу) и наблюдение за звездами в мощный телескоп." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the schedule and total duration of the Super Safari?" }, { "de", "Wie sind Zeitplan und Gesamtdauer der Super Safari?" }, { "it", "Quali sono gli orari e la durata della Super Safari?" }, { "fr", "Quels sont les horaires et la durée totale du Super Safari ?" }, { "ru", "Какое расписание и сколько длится экскурсия Супер Сафари?" } }, Answers = new Dictionary<string, string> { { "en", "Pick-up from Hurghada resorts is around 12:30 to 13:30 PM. The action-packed program lasts approximately 6 to 7 hours, returning to your hotel between 19:30 and 20:30 PM after dinner and shows." }, { "de", "Die Abholung erfolgt zwischen 12:30 und 13:30 Uhr. Das abwechslungsreiche Programm dauert ca. 6 bis 7 Stunden, sodass Sie nach Abendessen und Show gegen 19:30 bis 20:30 Uhr wieder im Hotel sind." }, { "it", "Il prelievo dall'hotel si tiene tra le 12:30 e le 13:30. L'escursione ricca di attività dura circa 6-7 ore con rientro in resort dopo cena e spettacoli tra le 19:30 e le 20:30." }, { "fr", "Le départ de votre hôtel a lieu entre 12h30 et 13h30. Le programme complet dure environ 6 à 7 heures avec un retour à l'hôtel vers 19h30 - 20h30 après le dîner et les spectacles." }, { "ru", "Трансфер забирает гостей из отелей в 12:30 - 13:30. Насыщенная программа длится 6-7 часов, возвращение в отель после ужина, шоу и телескопов около 19:30 - 20:30." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear and pack for the Super Safari?" }, { "de", "Was soll ich für die Super Safari anziehen und einpacken?" }, { "it", "Cosa indossare e portare per la Super Safari?" }, { "fr", "Que faut-il porter et emporter pour le Super Safari ?" }, { "ru", "Что надеть и взять с собой на экскурсию Супер Сафари?" } }, Answers = new Dictionary<string, string> { { "en", "Wear comfortable lightweight clothing suitable for heat and dust, closed sneakers, sunglasses, and an arafat headscarf. In winter (November to March), pack a warm sweater or light jacket, as desert temperatures drop notably after dark." }, { "de", "Bequeme, unempfindliche Sommerkleidung, feste Turnschuhe, Sonnenbrille und Wüstentuch anziehen. Im Winter (November bis März) unbedingt eine wärmende Jacke oder Pullover für den Abend einpacken, da es in der Wüste nach Sonnenuntergang spürbar abkühlt." }, { "it", "Abbigliamento leggero e pratico per sabbia e caldo, scarpe da tennis chiuse, occhiali da sole e kefiah per la polvere. In inverno (da novembre a marzo) portate una felpa o giacca a vento per la sera quando la temperatura scende." }, { "fr", "Vêtements confortables et lavables, baskets fermées, lunettes et chèche protecteur. En hiver (novembre à mars), prévoyez un gilet chaud ou une veste car la nuit tombe vite et rafraîchit le désert." }, { "ru", "Наденьте комфортную практичную одежду, закрытые кроссовки, солнцезащитные очки и платок-арафатку. В зимний период (с ноября по март) обязательно возьмите теплую кофту или куртку, так как после заката в пустыне становится прохладно." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is the Super Safari suitable for children and families?" }, { "de", "Ist die Super Safari für Kinder und Familien geeignet?" }, { "it", "La Super Safari è adatta a famiglie con bambini?" }, { "fr", "Le Super Safari est-il recommandé aux familles avec enfants ?" }, { "ru", "Подходит ли Супер Сафари для семей с детьми?" } }, Answers = new Dictionary<string, string> { { "en", "Yes, it is one of the top family excursions in Egypt! Children can ride quad bikes as passengers behind parents, enjoy the buggy ride, ride friendly camels in the Bedouin village, and enjoy the lively fire shows and telescope stargazing." }, { "de", "Ja, es ist eines der beliebtesten Familienerlebnisse in Ägypten! Kinder können als Beifahrer auf Quads und Buggys mitfahren, auf friedlichen Kamelen reiten und abends die Feuershow und den Sternenhimmel bestaunen." }, { "it", "Sì, è tra le escursioni per famiglie più amate in Egitto! I bambini possono fare i passeggeri su quad e buggy, salire a dorso di cammello nel villaggio beduino e rimanere incantati da mangiafuoco e telescopio." }, { "fr", "Oui, c'est l'une des excursions phares pour les familles ! Les enfants participent en tant que passagers sur les quads et buggys, découvrent les chameaux au village bédouin et adorent le spectacle de feu et les étoiles." }, { "ru", "Да, это одна из лучших экскурсий для семейного отдыха! Дети едут пассажирами на квадроциклах и багги, катаются на добрых верблюдах в деревне бедуинов, с восторгом смотрят шоу с огнем и разглядывают кратеры Луны в телескоп." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193266.jpg", Captions = new Dictionary<string, string> { { "en", "Super Safari - Experience" }, { "de", "Große Wüsten-Super-Safari - Erlebnis" }, { "it", "Super Safari nel Deserto - Esperienza" }, { "fr", "Grand Super Safari dans le Désert - Expérience" }, { "ru", "Супер Сафари в пустыне - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193272.jpg", Captions = new Dictionary<string, string> { { "en", "Super Safari - Experience" }, { "de", "Große Wüsten-Super-Safari - Erlebnis" }, { "it", "Super Safari nel Deserto - Esperienza" }, { "fr", "Grand Super Safari dans le Désert - Expérience" }, { "ru", "Супер Сафари в пустыне - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193274.jpg", Captions = new Dictionary<string, string> { { "en", "Super Safari - Experience" }, { "de", "Große Wüsten-Super-Safari - Erlebnis" }, { "it", "Super Safari nel Deserto - Esperienza" }, { "fr", "Grand Super Safari dans le Désert - Expérience" }, { "ru", "Супер Сафари в пустыне - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Karting El Gouna" }, { "de", "Karting El Gouna" }, { "it", "Karting a El Gouna" }, { "fr", "Karting à El Gouna" }, { "ru", "Картинг в Эль-Гуне" } },
                Descriptions = new Dictionary<string, string> { { "en", "Enjoy an exciting karting session in El Gouna. Race around the track, challenge your friends or family and enjoy a fun motorsport activity away from the beach." }, { "de", "Erleben Sie ein adrenalingeladenes Karting-Erlebnis in El Gouna. Meistern Sie die anspruchsvolle Rennstrecke, fordern Sie Freunde oder Familie heraus und genießen Sie eine dynamische Motorsport-Aktivität abseits der Strände." }, { "it", "Vivi l'emozione di un'avvincente sessione di karting a El Gouna. Sfida amici o familiari su un circuito moderno e dinamico, regalando alla tua vacanza una scarica di pura adrenalina motoristica." }, { "fr", "Faites le plein de sensations fortes lors d'une session exaltante de karting à El Gouna. Élancez-vous sur le circuit, défiez vos proches et profitez d'une parenthèse sportive et dynamique hors des plages." }, { "ru", "Ощутите настоящий азарт скорости на современном картодроме в Эль-Гуне. Прокатитесь по виражам трассы, устройте увлекательное соревнование с друзьями или семьей и зарядитесь яркими эмоциями." } },
                Price = 30,
                Currency = "EUR",
                Duration = "Approx. 1-2 hours",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000015"),
                CategoryId = Guid.Parse("00000000-0000-0000-0000-000000000005"),
                Emoji = "🏜️",
                ImageUrl = "/images/tours/5861626853276193279.jpg",
                MediaUrls = new List<string> { "/images/tours/5861626853276193279.jpg", "/images/tours/5861626853276193284.jpg", "/images/tours/5861626853276193197.jpg" },
                ReserveAndPayLater = true,
                HotelPickup = true,
                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the El Gouna Go-Karting experience?" }, { "de", "Was ist beim Go-Karting in El Gouna enthalten?" }, { "it", "Cosa comprende l'esperienza Go-Kart a El Gouna?" }, { "fr", "Qu'est-ce qui est inclus dans la session de Karting à El Gouna ?" }, { "ru", "Что входит в заезд на картинге в Эль-Гуне (Karting El Gouna)?" } }, Answers = new Dictionary<string, string> { { "en", "The experience includes round-trip transfers, entry to the professional outdoor asphalt karting track in El Gouna, a safety briefing, full-face racing helmet, modern 270cc Sodi racing kart rental, and timed race heat sessions (typically 10 to 15 laps per heat) with digital telemetry lap-timing printouts." }, { "de", "Das Erlebnis umfasst Hin- und Rücktransfer, Zugang zur professionellen Outdoor-Asphaltbahn in El Gouna, Sicherheitseinweisung, Integral-Rennhelm, modernen 270-ccm-Sodi-Kart sowie gezeitete Rennläufe (ca. 10 bis 15 Runden) mit digitaler Rundenzeiterfassung." }, { "it", "L'attività comprende transfer dall'hotel, accesso alla pista outdoor professionale in asfalto a El Gouna, briefing sulla sicurezza, casco integrale, noleggio kart da corsa Sodi 270cc e manche di gara cronometrate (10-15 giri) con tabellone e telemetria dei tempi sul giro." }, { "fr", "L'expérience comprend les transferts hôtel, l'accès au circuit extérieur officiel en asphalte d'El Gouna, briefing, casque de course, kart de compétition Sodi 270cc et session de tours chronométrés (10 à 15 tours) avec affichage numérique des temps au tour." }, { "ru", "В стоимость входят трансфер из отеля, доступ на профессиональный открытый асфальтовый картодром в Эль-Гуне, инструктаж, гоночный шлем, современный карт Sodi 270 куб.см и заезды на время (10-15 кругов) с электронной телеметрией и распечаткой времени круга." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What are the age and height restrictions for karting?" }, { "de", "Welche Alters- und Größenbeschränkungen gelten beim Kartfahren?" }, { "it", "Quali sono le restrizioni di altezza ed età per il karting?" }, { "fr", "Quelles sont les limites d'âge et de taille pour le karting ?" }, { "ru", "Какие ограничения по возрасту и росту действуют на картодроме?" } }, Answers = new Dictionary<string, string> { { "en", "For standard 270cc adult karts, drivers must be at least 140 cm tall (approx. 12 years old). Junior karts are available for younger racers from 7 to 11 years (min. 120 cm), and two-seater tandem karts allow parents to drive with children as young as 5." }, { "de", "Für die regulären 270-ccm-Karts beträgt die Mindestgröße 140 cm (ca. 12 Jahre). Für Kinder von 7 bis 11 Jahren (ab 120 cm) stehen gedrosselte Junior-Karts bereit, und in Doppelsitz-Karts können Eltern bereits Kinder ab 5 Jahren mitnehmen." }, { "it", "Per i kart adulti da 270cc l'altezza minima è di 140 cm (circa 12 anni). Sono disponibili junior kart per ragazzi dai 7 agli 11 anni (minimo 120 cm) e kart biposto per consentire ai genitori di girare con bimbi dai 5 anni." }, { "fr", "Pour les karts adultes 270cc, la taille minimale est de 140 cm (environ 12 ans). Des karts juniors sont prévus pour les 7-11 ans (minimum 120 cm) et des biplaces permettent aux parents de piloter avec des enfants dès 5 ans." }, { "ru", "Для управления взрослым картом 270 куб.см минимальный рост составляет 140 см (примерно от 12 лет). Для детей 7-11 лет (от 120 см) есть юниорские карты, а на двухместных тандем-картах родители могут прокатить детей от 5 лет." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear for go-kart racing?" }, { "de", "Welche Kleidung sollte man beim Kartfahren tragen?" }, { "it", "Come vestirsi per correre sui kart?" }, { "fr", "Comment s'habiller pour faire du karting ?" }, { "ru", "Что надеть на картодром?" } }, Answers = new Dictionary<string, string> { { "en", "You must wear fully closed shoes (sneakers, trainers, or tennis shoes; flip-flops and sandals are strictly forbidden on track). Wear comfortable casual t-shirt and jeans or shorts. Long hair must be tied back securely inside the helmet." }, { "de", "Festes geschlossenes Schuhwerk ist Pflicht (Turnschuhe oder Sneaker; Sandalen und Badeschlappen sind auf der Bahn streng verboten). Bequeme Kleidung tragen; lange Haare müssen zusammengebunden unter den Helm gesteckt werden." }, { "it", "È obbligatorio indossare scarpe chiuse da ginnastica (vietatissimi sandali e infradito sui kart). Abbigliamento comodo con maglietta e pantaloni/pantaloncini; i capelli lunghi devono essere legati e raccolti sotto il casco." }, { "fr", "Chaussures fermées obligatoires (baskets ; sandales et tongs formellement interdites). Tenue décontractée t-shirt et short/pantalon. Les cheveux longs doivent être attachés sous le casque." }, { "ru", "Обязательна закрытая обувь (кроссовки или кеды; шлепанцы и сандалии на трассе строго запрещены). Удобная легкая одежда. Длинные волосы необходимо собрать резинкой и убрать под подшлемник." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "How long is the excursion and can we visit El Gouna Marina afterwards?" }, { "de", "Wie lange dauert der Ausflug und kann man danach die El Gouna Marina besichtigen?" }, { "it", "Quanto dura l'attività ed è possibile visitare la Marina di El Gouna?" }, { "fr", "Combien de temps dure la sortie et peut-on visiter la marina d'El Gouna ?" }, { "ru", "Сколько длится поездка и можно ли совместить картинг с прогулкой по марине Эль-Гуны?" } }, Answers = new Dictionary<string, string> { { "en", "The total duration is approximately 2 to 3 hours including transfers. Upon request, we can arrange an extended drop-off at the Abu Tig Marina or Downtown El Gouna for dining, shopping, or drinks before returning to Hurghada." }, { "de", "Die Gesamtdauer beträgt ca. 2 bis 3 Stunden inklusive Transfer. Auf Wunsch lässt sich die Tour ideal mit einem Bummel an der luxuriösen Abu Tig Marina oder in Downtown El Gouna zum Abendessen oder Shoppen verbinden." }, { "it", "La durata complessiva è di circa 2-3 ore con i transfer. Su richiesta possiamo prolungare la sosta per una piacevole passeggiata tra i bar e i ristoranti glamour di Abu Tig Marina o nel centro di El Gouna." }, { "fr", "L'excursion dure 2 à 3 heures au total avec les transferts. Sur demande, nous pouvons prolonger votre passage pour une balade ou un verre sur les quais chic de la marina d'Abu Tig à El Gouna." }, { "ru", "Общая длительность поездки около 2-3 часов с дорогой. По запросу можно совместить картинг со свободной прогулкой по роскошной набережной Абу-Тиг Марина в Эль-Гуне с кафе, ресторанами и бутиками." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193279.jpg", Captions = new Dictionary<string, string> { { "en", "Karting El Gouna - Experience" }, { "de", "Karting El Gouna - Erlebnis" }, { "it", "Karting a El Gouna - Esperienza" }, { "fr", "Karting à El Gouna - Expérience" }, { "ru", "Картинг в Эль-Гуне - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193284.jpg", Captions = new Dictionary<string, string> { { "en", "Karting El Gouna - Experience" }, { "de", "Karting El Gouna - Erlebnis" }, { "it", "Karting a El Gouna - Esperienza" }, { "fr", "Karting à El Gouna - Expérience" }, { "ru", "Картинг в Эль-Гуне - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193197.jpg", Captions = new Dictionary<string, string> { { "en", "Karting El Gouna - Experience" }, { "de", "Karting El Gouna - Erlebnis" }, { "it", "Karting a El Gouna - Esperienza" }, { "fr", "Karting à El Gouna - Expérience" }, { "ru", "Картинг в Эль-Гуне - Впечатления" } } } }
