            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Spa & Massage" }, { "de", "Spa & Massage" }, { "it", "Spa & Massaggi" }, { "fr", "Spa & Massages" }, { "ru", "Спа и массаж" } },
                Descriptions = new Dictionary<string, string> { { "en", "Relax and recharge with a professional spa and massage session. It is a simple way to unwind after travel, sun exposure or an active day of excursions." }, { "de", "Entspannen Sie Körper und Geist bei einer exklusiven Spa- und Massagebehandlung. Die ideale Verwöhnzeit, um nach der Reise, Sonnenstunden am Meer oder erlebnisreichen Ausflügen vollkommen zu regenerieren." }, { "it", "Ritrova il perfetto equilibrio di corpo e mente con una rigenerante sessione di spa e massaggio professionale. Il rituale ideale per distendersi dopo il viaggio, il sole o un'intensa giornata di escursioni." }, { "fr", "Offrez-vous une parenthèse de pure détente avec une séance professionnelle de spa et de massage. L'art de se ressourcer en douceur après le voyage, les bains de soleil ou une journée d'excursions." }, { "ru", "Восстановите силы и гармонию во время профессионального сеанса спа и массажа. Идеальный способ расслабиться после перелета, морского солнца или насыщенного дня экскурсий." } },
