                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Turkish Bath & Massage Spa package?" }, { "de", "Was ist im Türkischen Bad & Massage Wellnesspaket enthalten?" }, { "it", "Cosa include il pacchetto Spa con Bagno Turco e Massaggio?" }, { "fr", "Qu'est-ce qui est inclus dans le forfait Spa Hammam & Massage ?" }, { "ru", "Что входит в спа-программу 'Турецкий хаммам и массаж'?" } }, Answers = new Dictionary<string, string> { { "en", "The comprehensive wellness ritual includes round-trip hotel transfers, access to the relaxation area, steam room, sauna, hot Jacuzzi plunge, traditional oriental peeling with a Kessa loofah glove, warm cloud foam massage wash, a full-body 45-minute aromatherapy essential oil relaxation massage, and complimentary hot herbal tea." }, { "de", "Das ganzheitliche Entspannungserlebnis umfasst Hin- und Rücktransfer, Zugang zum Wellnessbereich, Dampfbad, Sauna, Whirlpool, orientalisches Kessa-Peeling zur Hauterneuerung, reinigende Schaummassage, eine 45-minütige Ganzkörper-Entspannungsmassage mit Aromaölen und frischen Kräutertee." }, { "it", "Il rituale di benessere completo include transfer dall'hotel, accesso alla zona relax con sauna, bagno turco a vapore e idromassaggio jacuzzi, scrub corpo con guanto Kessa, soffice massaggio con schiuma di sapone naturale, massaggio rilassante total body da 45 minuti con oli aromatici e tè caldo alle erbe." }, { "fr", "Ce rituel de détente complet comprend les transferts, l'accès au sauna, hammam et jacuzzi chaud, un gommage au gant de Kessa pour purifier la peau, un massage enveloppant à la mousse de savon, un massage relaxant du corps entier de 45 minutes aux huiles essentielles et une dégustation de thé bédouin." }, { "ru", "В полноценную спа-программу входят трансфер из отеля и обратно, зона отдыха, сауна, парная, горячий джакузи, пилинг рукавичкой Кесса, нежный пенный массаж, 45-минутный расслабляющий массаж всего тела с натуральными ароматическими маслами и восточный травяной чай." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I bring and wear to the spa center?" }, { "de", "Was sollte man für das Spa mitbringen und anziehen?" }, { "it", "Cosa portare e indossare al centro benessere?" }, { "fr", "Que faut-il apporter et porter au centre de bien-être ?" }, { "ru", "Что взять с собой и в чем приходить в спа-центр?" } }, Answers = new Dictionary<string, string> { { "en", "Bring your swimwear and flip-flops. The spa provides clean towels, robes, disposable slippers, and private lockers for personal belongings and clothes. Disposable massage undergarments are also available." }, { "de", "Bringen Sie Badebekleidung und Badeschlappen mit. Das Spa stellt saubere Handtücher, Bademäntel, Einweg-Slipper sowie verschließbare Schließfächer für Kleidung und Wertsachen zur Verfügung." }, { "it", "Portate il costume da bagno e le ciabatte. La struttura fornisce teli puliti, accappatoi, ciabattine monouso e armadietti personali con chiave per abiti e valori. Disponibile biancheria monouso per i trattamenti." }, { "fr", "Apportez maillot de bain et tongs. Le spa fournit des serviettes propres, peignoirs, chaussons jetables et des casiers sécurisés pour vos effets personnels." }, { "ru", "Возьмите купальник и сланцы. Спа-салон предоставляет чистые полотенца, халаты, тапочки и запирающиеся шкафчики для одежды и личных вещей. Для массажа выдается одноразовое белье." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Can I choose male or female massage therapists?" }, { "de", "Kann man zwischen männlichen und weiblichen Therapeuten wählen?" }, { "it", "È possibile richiedere massaggiatrici donne o massaggiatori uomini?" }, { "fr", "Peut-on choisir un thérapeute homme ou femme ?" }, { "ru", "Можно ли выбрать мастера-массажиста (мужчину или женщину)?" } }, Answers = new Dictionary<string, string> { { "en", "Yes, absolutely. You can specify your therapist gender preference upon booking or upon arrival at the spa reception to ensure your absolute comfort and privacy." }, { "de", "Ja, absolut. Sie können Ihren Wunsch bezüglich eines weiblichen oder männlichen Therapeuten bereits bei der Buchung oder direkt am Empfang des Spas äußern." }, { "it", "Sì, certamente. È possibile esprimere la propria preferenza per un terapeuta uomo o donna al momento della prenotazione o all'arrivo alla reception della spa per il massimo comfort e riservatezza." }, { "fr", "Oui, sans problème. Vous pouvez spécifier votre préférence pour une praticienne femme ou un praticien homme dès la réservation ou à votre arrivée à la réception du spa." }, { "ru", "Да, конечно. Вы можете выбрать мастера (женщину или мужчину) при бронировании или на ресепшн спа-центра для вашего максимального комфорта и приватности." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Is the spa recommended before or after getting a sun tan?" }, { "de", "Wird der Spa-Besuch vor oder nach dem Sonnenbaden empfohlen?" }, { "it", "Il trattamento spa è consigliato prima o dopo l'abbronzatura?" }, { "fr", "Le soin spa est-il conseillé avant ou après avoir bronzé ?" }, { "ru", "Когда лучше идти в спа: в начале отпуска или после загара?" } }, Answers = new Dictionary<string, string> { { "en", "We highly recommend booking the Turkish Bath & Peeling during the first 1 to 2 days of your vacation! Removing dead skin cells creates an ultra-smooth base that ensures a deeper, longer-lasting, radiant golden suntan. Note: avoid body peeling if your skin is already sunburned." }, { "de", "Wir empfehlen das Peeling wärmstens an den ersten 1 bis 2 Urlaubstagen! Die Entfernung abgestorbener Hautschüppchen sorgt für eine besonders gleichmäßige, langanhaltende und goldene Bräune. Bei frischem Sonnenbrand sollte auf Peelings verzichtet werden." }, { "it", "Consigliamo vivamente il bagno turco e lo scrub nei primi 1-2 giorni di vacanza! Eliminare le cellule morte prepara la pelle a un'abbronzatura dorata uniforme e duratura. Attenzione: evitare lo scrub in caso di scottature solari già presenti." }, { "fr", "Nous recommandons vivement de faire le hammam et le gommage lors des 1 à 2 premiers jours de vos vacances ! Cela prépare la peau pour un bronzage éclatant, uniforme et durable. À éviter en revanche si vous avez déjà un coup de soleil." }, { "ru", "Мы настоятельно рекомендуем посетить хаммам и пилинг в первые 1-2 дня отдыха! Глубокое очищение кожи обеспечит идеальный, ровный и стойкий золотистый загар. Если кожа уже обгорела на солнце, жесткий пилинг противопоказан." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/01f7cc1b-ab8a-49a2-87fb-93494909eea2.JPG", Captions = new Dictionary<string, string> { { "en", "Spa & Massage - Experience" }, { "de", "Spa & Massage - Erlebnis" }, { "it", "Spa & Massaggi - Esperienza" }, { "fr", "Spa & Massages - Expérience" }, { "ru", "Спа и массаж - Впечатления" } } }, new TourMedia { Url = "/images/tours/0250f9da-c94a-4640-ba3a-7591aea4e2a0.JPG", Captions = new Dictionary<string, string> { { "en", "Spa & Massage - Experience" }, { "de", "Spa & Massage - Erlebnis" }, { "it", "Spa & Massaggi - Esperienza" }, { "fr", "Spa & Massages - Expérience" }, { "ru", "Спа и массаж - Впечатления" } } }, new TourMedia { Url = "/images/tours/05854f9c-1938-4917-b2e1-d522d209dd9f.JPG", Captions = new Dictionary<string, string> { { "en", "Spa & Massage - Experience" }, { "de", "Spa & Massage - Erlebnis" }, { "it", "Spa & Massaggi - Esperienza" }, { "fr", "Spa & Massages - Expérience" }, { "ru", "Спа и массаж - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Luxor Van" }, { "de", "Tagesausflug Luxor im Minivan" }, { "it", "Luxor in Minivan" }, { "fr", "Louxor en Minibus Climatisé" }, { "ru", "Экскурсия в Луксор на комфортабельном минивэне" } },
                Descriptions = new Dictionary<string, string> { { "en", "Discover the highlights of ancient Luxor on a full-day journey from Hurghada. Visit major landmarks such as the Valley of the Kings, Hatshepsut Temple, Colossi of Memnon and Karnak Temple, with an Egyptologist-style guided programme where included." }, { "de", "Entdecken Sie die Schätze des antiken Theben auf einem ganztägigen Ausflug von Hurghada nach Luxor im komfortablen Minivan. Bestaunen Sie weltberühmte Monumente wie das Tal der Könige, den Hatschepsut-Tempel, die Memnonkolosse und den monumentalen Karnak-Tempel – begleitet von fundierter ägyptologischer Führung." }, { "it", "Scopri i tesori dell'antica Tebe con un'esclusiva escursione di un'intera giornata da Hurghada a Luxor in minivan climatizzato. Ammira meraviglie senza tempo come la Valle dei Re, il Tempio di Hatshepsut, i Colossi di Memnone e il Tempio di Karnak, accompagnato da una guida esperta di egittologia." }, { "fr", "Explorez les merveilles de l'antique Thèbes lors d'une journée complète au départ d'Hurghada en minibus tout confort. Visitez la Vallée des Rois, le temple d'Hatchepsout, les Colosses de Memnon et le majestueux temple de Karnak, sublimés par les récits captivants d'un guide égyptologue." }, { "ru", "Откройте для себя сокровища древних Фив во время однодневной поездки из Хургады в Луксор на комфортабельном минивэне. Вас ждут всемирно известные памятники: Долина Царей, храм царицы Хатшепсут, Колоссы Мемнона и грандиозный Карнакский храм в сопровождении профессионального гида-египтолога." } },
                Price = 110,
                Currency = "EUR",
                Duration = "Approx. 12-14 hours",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000012"),
                CategoryId = Guid.Parse("00000000-0000-0000-0000-000000000009"),
                Emoji = "🏛️",
                ImageUrl = "/images/tours/5861626853276193194.jpg",
                MediaUrls = new List<string> { "/images/tours/5861626853276193194.jpg", "/images/tours/5861626853276193196.jpg", "/images/tours/5861626853276193204.jpg", "/images/tours/5861626853276193211.jpg", "/images/tours/5861626853276193212.jpg", "/images/tours/5861626853276193221.jpg", "/images/tours/5861626853276193222.jpg", "/images/tours/5861626853276193223.jpg", "/images/tours/5861626853276193231.jpg", "/images/tours/5861626853276193232.jpg", "/images/tours/5861626853276193233.jpg", "/images/tours/5861626853276193235.jpg", "/images/tours/5861626853276193239.jpg", "/images/tours/5861626853276193240.jpg", "/images/tours/5861626853276193243.jpg", "/images/tours/5861626853276193264.jpg", "/images/tours/5861626853276193273.jpg", "/images/tours/5861626853276193274.jpg", "/images/tours/5861626853276193277.jpg", "/images/tours/5861626853276193283.jpg" },
                ReserveAndPayLater = true,
                HotelPickup = true,
                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What sights are visited and what is included in the Luxor Van day trip?" }, { "de", "Welche Sehenswürdigkeiten werden besucht und was ist im Luxor-Van-Tagesausflug enthalten?" }, { "it", "Quali monumenti si visitano e cosa è compreso nel tour Luxor Van?" }, { "fr", "Quels sites visite-t-on et qu'est-ce qui est inclus dans l'excursion Luxor Van ?" }, { "ru", "Какие достопримечательности входят в тур в Луксор на микроавтобусе (Luxor Van)?" } }, Answers = new Dictionary<string, string> { { "en", "The tour includes round-trip transport in a small, comfortable air-conditioned van, licensed professional Egyptologist guide in your chosen language, entrance tickets to Karnak Temple Complex, Valley of the Kings (access into 3 royal pharaonic tombs), Hatshepsut Mortuary Temple at Deir el-Bahari, the towering Colossi of Memnon, a traditional Nile motorboat crossing, and lunch at a local restaurant." }, { "de", "Die Tour umfasst den Hin- und Rücktransfer im komfortablen, klimatisierten Minivan, lizenzierten deutschsprachigen Ägyptologen als Guide, Eintrittskarten zum Karnak-Tempel, ins Tal der Könige (inkl. 3 Pharaonengräber), zum Hatschepsut-Terrassentempel, zu den Kolossen von Memnon, eine Nilüberquerung per Motorboot und Mittagessen im Restaurant." }, { "it", "Il tour comprende viaggio in comodo minivan climatizzato a/r, guida egittologa autorizzata nella vostra lingua, biglietti d'ingresso al Tempio di Karnak, Valle dei Re (visita a 3 tombe reali), Tempio della Regina Hatshepsut, Colossi di Memnone, traversata del Nilo in barca a motore e pranzo al ristorante." }, { "fr", "L'excursion comprend le trajet en van tout confort climatisé, un guide égyptologue agréé, les billets d'entrée pour le complexe de Karnak, la Vallée des Rois (visite de 3 tombeaux royaux), le temple d'Hatchepsout, les Colosses de Memnon, la traversée du Nil en bateau et le déjeuner au restaurant." }, { "ru", "В тур входят проезд на небольшом комфортабельном кондиционированном микроавтобусе, лицензированный гид-египтолог, входные билеты в грандиозный Карнакский храм, Долину Царей (посещение 3 королевских гробниц), храм царицы Хатшепсут, колоссы Мемнона, переправа через Нил на катере и обед в ресторане." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the pickup time, travel duration, and return schedule?" }, { "de", "Wie sind Abholzeit, Fahrtdauer und Rückkehrzeit für die Luxor-Tour?" }, { "it", "A che ora è la partenza, quanto dura il viaggio e a che ora si rientra?" }, { "fr", "Quels sont les horaires de départ, le temps de route et l'heure de retour ?" }, { "ru", "Во сколько выезд из отеля, сколько длится дорога и когда возвращение?" } }, Answers = new Dictionary<string, string> { { "en", "Departure from Hurghada is early, between 04:30 and 05:15 AM. The scenic highway drive across the Eastern Desert takes around 4 to 4.5 hours each way with a midway coffee and restroom stop. Sights are toured throughout the day, returning to your resort around 20:30 to 21:30 PM." }, { "de", "Die Abholung erfolgt frühmorgens zwischen 04:30 und 05:15 Uhr. Die Fahrt durch das Wüstengebirge dauert ca. 4 bis 4,5 Stunden pro Strecke mit Kaffeepause. Nach der Besichtigungstour kehren Sie gegen 20:30 bis 21:30 Uhr zurück." }, { "it", "La partenza da Hurghada è prevista tra le 04:30 e le 05:15. Il tragitto attraverso il deserto orientale dura circa 4 - 4,5 ore con sosta ristoro a metà strada. Rientro in hotel per cena tra le 20:30 e le 21:30." }, { "fr", "Le départ a lieu tôt, entre 04h30 et 05h15. Le trajet à travers le désert prend environ 4h à 4h30 par trajet avec halte confort. Visites toute la journée et retour à l'hôtel vers 20h30 - 21h30." }, { "ru", "Выезд из отелей Хургады ранний — в 04:30 - 05:15. Дорога через живописную пустыню занимает около 4-4,5 часов в одну сторону с остановкой в кафе. Возвращение в отель к 20:30 - 21:30." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear and pack for a full day in Luxor?" }, { "de", "Was sollte man für einen Tagesausflug nach Luxor anziehen und einpacken?" }, { "it", "Come vestirsi e cosa portare per la giornata a Luxor?" }, { "fr", "Que porter et emporter pour une journée complète à Louxor ?" }, { "ru", "Что надеть и взять с собой на экскурсию в Луксор?" } }, Answers = new Dictionary<string, string> { { "en", "Wear comfortable walking shoes with good tread, light breathable cotton clothing covering shoulders and knees (respectful for monuments), a sun hat, and sunglasses. Pack your original passports, hotel breakfast box (order at hotel reception the evening before), bottled water, sunscreen, and cash for drinks and tips." }, { "de", "Feste, bequeme Wanderschuhe, atmungsaktive Baumwollkleidung (Schultern und Knie bedeckt), Sonnenhut und Sonnenbrille. Reisepässe im Original, Frühstücksbox aus dem Hotel (am Vorabend anfordern), Wasserflasche, Sonnencreme und Bargeld für Getränke/Trinkgelder mitnehmen." }, { "it", "Scarpe comode da camminata, abiti freschi in cotone che coprano spalle e ginocchia (graditi sui siti storici), cappello e occhiali da sole. Portate passaporti originali, cestino colazione dell'hotel, acqua, crema solare e contanti per bevande e mance." }, { "fr", "Chaussures de marche confortables, vêtements amples et respirants en coton couvrant épaules et genoux, chapeau et lunettes. Prenez vos passeports originaux, boîte petit-déjeuner de l'hôtel, bouteille d'eau, crème solaire et argent pour les boissons et pourboires." }, { "ru", "Удобную обувь для ходьбы, легкую одежду из натуральных тканей, прикрывающую плечи и колени, панаму и очки. Обязательно возьмите оригиналы паспортов, сухой завтрак из отеля (закажите на ресепшн накануне), воду, крем от солнца и наличные." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Can we visit the tomb of King Tutankhamun inside the Valley of the Kings?" }, { "de", "Kann man das Grab von Tutanchamun im Tal der Könige besichtigen?" }, { "it", "È possibile visitare la tomba di Tutankhamon nella Valle dei Re?" }, { "fr", "Peut-on visiter le tombeau de Toutânkhamon dans la Vallée des Rois ?" }, { "ru", "Можно ли посетить гробницу Тутанхамона в Долине Царей?" } }, Answers = new Dictionary<string, string> { { "en", "Yes! The standard Valley of the Kings entry ticket includes access to three magnificent royal tombs (such as Ramses III, Ramses IV, Merenptah). The tomb of King Tutankhamun requires a special extra ticket that can be purchased at the gate with the help of your guide." }, { "de", "Ja! Das normale Ticket beinhaltet den Eintritt in drei beeindruckende Königsgräber (z.B. Ramses III., Ramses IV. oder Merenptah). Für das berühmte Grab von Tutanchamun ist ein Zusatzticket vor Ort an der Kasse erhältlich (Ihr Guide hilft gerne)." }, { "it", "Sì! Il biglietto standard della Valle dei Re include l'ingresso a 3 straordinarie tombe reali (come Ramses III, Ramses IV, Merenptah). La tomba di Tutankhamon richiede un biglietto speciale supplementare acquistabile in biglietteria con l'assistenza della guida." }, { "fr", "Oui ! Le billet classique inclut l'accès à 3 superbes tombeaux de pharaons (comme Ramsès III, Ramsès IV, Mérenptah). Le tombeau de Toutânkhamon nécessite un billet supplémentaire vendu sur place à l'entrée avec l'aide de votre guide." }, { "ru", "Да! Стандартный билет в Долину Царей включает осмотр трех великолепных гробниц (например, Рамсеса III, Рамсеса IV, Мернептаха). В гробницу Тутанхамона требуется отдельный дополнительный билет, который можно купить в кассе с помощью гида." } } } },
