w TourMedia { Url = "/images/tours/5861626853276193273.jpg", Captions = new Dictionary<string, string> { { "en", "Luxor Van - Experience" }, { "de", "Tagesausflug Luxor im Minivan - Erlebnis" }, { "it", "Luxor in Minivan - Esperienza" }, { "fr", "Louxor en Minibus Climatisé - Expérience" }, { "ru", "Экскурсия в Луксор на комфортабельном минивэне - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193274.jpg", Captions = new Dictionary<string, string> { { "en", "Luxor Van - Experience" }, { "de", "Tagesausflug Luxor im Minivan - Erlebnis" }, { "it", "Luxor in Minivan - Esperienza" }, { "fr", "Louxor en Minibus Climatisé - Expérience" }, { "ru", "Экскурсия в Луксор на комфортабельном минивэне - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193277.jpg", Captions = new Dictionary<string, string> { { "en", "Luxor Van - Experience" }, { "de", "Tagesausflug Luxor im Minivan - Erlebnis" }, { "it", "Luxor in Minivan - Esperienza" }, { "fr", "Louxor en Minibus Climatisé - Expérience" }, { "ru", "Экскурсия в Луксор на комфортабельном минивэне - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193283.jpg", Captions = new Dictionary<string, string> { { "en", "Luxor Van - Experience" }, { "de", "Tagesausflug Luxor im Minivan - Erlebnis" }, { "it", "Luxor in Minivan - Esperienza" }, { "fr", "Louxor en Minibus Climatisé - Expérience" }, { "ru", "Экскурсия в Луксор на комфортабельном минивэне - Впечатления" } } } }
