            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Luxor Overnight" }, { "de", "Luxor 2-Tages-Tour mit Übernachtung" }, { "it", "Luxor con Pernottamento (2 Giorni)" }, { "fr", "Louxor 2 Jours avec Nuitée" }, { "ru", "Луксор: 2 дня с ночевкой" } },
                Descriptions = new Dictionary<string, string> { { "en", "Take more time to experience Luxor instead of rushing through a single day. Explore the major temples and tombs, enjoy an overnight stay and continue your sightseeing the following day at a more comfortable pace." }, { "de", "Erleben Sie die Magie von Luxor ganz entspannt mit einer Übernachtung vor Ort. Entdecken Sie die prachtvollen Tempel und Königsgräber ohne Hektik, genießen Sie das abendliche Nil-Panorama und setzen Sie Ihre Besichtigungen am nächsten Tag in aller Ruhe fort." }, { "it", "Concediti il lusso di vivere Luxor senza fretta con un indimenticabile tour di due giorni e una notte. Esplora templi leggendari e tombe reali a un ritmo rilassato, goditi l'incanto serale sul Nilo e prosegui le tue visite il giorno seguente in totale serenità." }, { "fr", "Prenez le temps d'embrasser toute la grandeur de Louxor grâce à cette échappée de deux jours avec nuitée. Loin de la précipitation, explorez les tombes et temples emblématiques, profitez de la douceur du Nil en soirée et poursuivez vos découvertes à un rythme serein." }, { "ru", "Насладитесь величием древнего Луксора без спешки в рамках двухдневной программы с ночевкой. Исследуйте царские гробницы и величественные храмы в комфортном темпе, ощутите вечернюю атмосферу берегов Нила и продолжите знакомство с историей на следующий день." } },
                Price = 280,
                Currency = "EUR",
                Duration = "Approx. 2 days / 1 night",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000012"),
                CategoryId = Guid.Parse("00000000-0000-0000-0000-000000000009"),
                Emoji = "🏛️",
                ImageUrl = "/images/tours/5861626853276193250.jpg",
                MediaUrls = new List<string> { "/images/tours/5861626853276193250.jpg", "/images/tours/5861626853276193194.jpg", "/images/tours/5861626853276193196.jpg" },
                ReserveAndPayLater = true,
                HotelPickup = true,
                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the 2-Day Luxor Overnight tour?" }, { "de", "Was ist in der 2-tägigen Luxor-Übernachtungstour enthalten?" }, { "it", "Cosa comprende il tour di 2 giorni con pernottamento a Luxor?" }, { "fr", "Qu'est-ce qui est inclus dans le circuit de 2 jours à Louxor avec nuit d'hôtel ?" }, { "ru", "Что входит в двухдневный тур с ночевкой в Луксоре (Luxor Overnight)?" } }, Answers = new Dictionary<string, string> { { "en", "This deep-dive itinerary includes private or small-group transport, 1 night in a 4-star Nile-front hotel with breakfast, 2 full days of guided touring with an Egyptologist, entrance tickets to Karnak Temple, Luxor Temple illuminated by night, Valley of the Kings, Hatshepsut Temple, Colossi of Memnon, Valley of the Queens or Medinet Habu, two restaurant lunches, and Nile boat crossing." }, { "de", "Diese umfassende Tour beinhaltet Hin- und Rückfahrt im Minivan, 1 Hotelübernachtung (4-Sterne direkt am Nil inkl. Frühstück), 2 Tage Führung mit Ägyptologen, Eintritt zum Karnak-Tempel, abends beleuchtetem Luxor-Tempel, Tal der Könige, Hatschepsut-Tempel, Memnon-Kolossen, Medinet Habu oder Tal der Königinnen, 2x Mittagessen und Nilfahrt." }, { "it", "Questo itinerario approfondito comprende trasferimenti a/r, 1 notte in hotel 4 stelle affacciato sul Nilo con colazione, 2 intere giornate di visite con egittologo, ingressi a Karnak, Tempio di Luxor illuminato di notte, Valle dei Re, Tempio di Hatshepsut, Colossi di Memnone, Medinet Habu o Valle delle Regine, 2 pranzi e navigazione sul Nilo." }, { "fr", "Ce circuit approfondi comprend les trajets en van confortable, 1 nuitée en hôtel 4 étoiles sur les rives du Nil avec petit-déjeuner, 2 journées de visites guidées avec un égyptologue, entrées à Karnak, temple de Louxor illuminé le soir, Vallée des Rois, Hatchepsout, Colosses de Memnon, Médinet Habou, 2 déjeuners et traversée du Nil." }, { "ru", "Тур включает комфортабельный трансфер, 1 ночь в 4-звездочном отеле на берегу Нила с завтраком, 2 полных дня экскурсий с египтологом, билеты в Карнак, вечерний подсвеченный Луксорский храм, Долину Царей, храм Хатшепсут, колоссы Мемнона, Мединет-Абу или Долину Цариц, 2 обеда и прогулку по Нилу." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Can I add the Sunrise Hot Air Balloon flight to Luxor Overnight?" }, { "de", "Kann man die Heißluftballonfahrt zum Sonnenaufgang zubuchen?" }, { "it", "È possibile abbinare il volo in mongolfiera all'alba nel tour di 2 giorni?" }, { "fr", "Peut-on ajouter le vol en montgolfière au lever du soleil lors de ce séjour de 2 jours ?" }, { "ru", "Можно ли добавить полет на воздушном шаре на рассвете к двухдневному туру?" } }, Answers = new Dictionary<string, string> { { "en", "Yes! The overnight tour is the ideal way to experience the world-famous Luxor Sunrise Hot Air Balloon flight on Day 2 without waking up in Hurghada at 02:00 AM. You depart comfortably from your Luxor hotel directly to the launch field at dawn." }, { "de", "Ja! Die Übernachtungstour ist die perfekte Gelegenheit für die weltberühmte Heißluftballonfahrt an Tag 2 zum Sonnenaufgang – ohne mitten in der Nacht in Hurghada aufstehen zu müssen, da Sie direkt vom Nil-Hotel starten." }, { "it", "Sì! Il tour con pernottamento è l'occasione perfetta per vivere lo spettacolare volo in mongolfiera all'alba del secondo giorno partendo comodamente dal vostro hotel sul Nilo senza levatacce notturne da Hurghada." }, { "fr", "Oui ! Passer la nuit sur place est le moyen rêvé de faire le vol en montgolfière au lever du soleil le matin du 2e jour en partant directement et sereinement de votre hôtel de Louxor." }, { "ru", "Да! Двухдневная поездка — идеальный вариант для полета на воздушном шаре на рассвете во 2-й день. Вам не нужно выезжать глухой ночью из Хургады: вы стартуете прямо из отеля в Луксоре на стартовую площадку шаров." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Why choose the 2-Day Luxor tour over a single day trip?" }, { "de", "Warum sollte man die 2-tägige Tour statt des Tagesausflugs wählen?" }, { "it", "Perché preferire il tour di 2 giorni rispetto all'escursione giornaliera?" }, { "fr", "Pourquoi choisir le tour en 2 jours plutôt que l'excursion sur une seule journée ?" }, { "ru", "Почему стоит выбрать двухдневный тур вместо однодневного?" } }, Answers = new Dictionary<string, string> { { "en", "A 2-day trip eliminates rush and fatigue, splitting sightseeing across two mornings when archaeological sites are cooler and less crowded. You get to witness Luxor Temple by night under floodlights, experience evening local markets, and take in the monuments at an unhurried, enriching pace." }, { "de", "Die 2-Tagestour vermeidet Hektik und Erschöpfung. Sie besichtigen Tempel und Gräber entspannt in den kühleren Morgenstunden, erleben den Luxor-Tempel magisch beleuchtet bei Nacht und schlendern abends durch die Basare." }, { "it", "La formula 2 giorni dimezza la stanchezza, permettendo di visitare i templi nelle ore mattutine più fresche. Include la magica visita notturna del Tempio di Luxor illuminato, la vita serale della città e ritmi rilassati." }, { "fr", "La formule 2 jours permet de savourer l'Égypte antique sans fatigue ni précipitation. Vous visitez les sites à la fraîcheur du matin, admirez le temple de Louxor éclairé de nuit et profitez des ruelles de Louxor." }, { "ru", "Двухдневный тур исключает спешку и усталость. Вы осматриваете храмы в утренней прохладе без толп, видите фантастическую ночную подсветку Луксорского храма, гуляете по вечернему колоритному городу и получаете вдвое больше впечатлений." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I pack for the overnight stay in Luxor?" }, { "de", "Was soll ich für die Übernachtung in Luxor einpacken?" }, { "it", "Cosa mettere nel bagaglio per la notte a Luxor?" }, { "fr", "Que faut-il mettre dans sa valise pour la nuit à Louxor ?" }, { "ru", "Что взять с собой для ночевки в Луксоре?" } }, Answers = new Dictionary<string, string> { { "en", "Pack an overnight daypack or small cabin bag (leave large luggage in your Hurghada hotel storage). Include original passports, a change of clothes, comfortable walking shoes, toiletries, phone charger, light jacket for evening/dawn, and prescription medications." }, { "de", "Packen Sie einen Rucksack oder eine kleine Reisetasche (große Koffer bleiben im Hotel in Hurghada). Original-Reisepässe, Kleidung zum Wechseln, bequeme Schuhe, Kulturbeutel, Ladekabel, eine leichte Jacke für den Abend und persönliche Medikamente einstecken." }, { "it", "Portate un pratico zaino o borsa da weekend (i bagagli pesanti restano al sicuro nel deposito dell'hotel a Hurghada). Includete passaporti originali, un cambio abiti, scarpe comode, caricabatterie, trousse e una felpa leggera per la sera." }, { "fr", "Prenez un petit sac à dos de week-end (vos grosses valises restent à l'hôtel d'Hurghada). Emportez passeports originaux, vêtements de rechange, chaussures confortables, trousse de toilette, chargeurs et petite veste." }, { "ru", "Возьмите небольшой рюкзак или сумку на 1 ночь (основные чемоданы остаются в камере хранения отеля в Хургаде). Паспорта, сменную одежду, удобную обувь, зарядки, туалетные принадлежности, легкую кофту на вечер и личные лекарства." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193250.jpg", Captions = new Dictionary<string, string> { { "en", "Luxor Overnight - Experience" }, { "de", "Luxor 2-Tages-Tour mit Übernachtung - Erlebnis" }, { "it", "Luxor con Pernottamento (2 Giorni) - Esperienza" }, { "fr", "Louxor 2 Jours avec Nuitée - Expérience" }, { "ru", "Луксор: 2 дня с ночевкой - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193194.jpg", Captions = new Dictionary<string, string> { { "en", "Luxor Overnight - Experience" }, { "de", "Luxor 2-Tages-Tour mit Übernachtung - Erlebnis" }, { "it", "Luxor con Pernottamento (2 Giorni) - Esperienza" }, { "fr", "Louxor 2 Jours avec Nuitée - Expérience" }, { "ru", "Луксор: 2 дня с ночевкой - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193196.jpg", Captions = new Dictionary<string, string> { { "en", "Luxor Overnight - Experience" }, { "de", "Luxor 2-Tages-Tour mit Übernachtung - Erlebnis" }, { "it", "Luxor con Pernottamento (2 Giorni) - Esperienza" }, { "fr", "Louxor 2 Jours avec Nuitée - Expérience" }, { "ru", "Луксор: 2 дня с ночевкой - Впечатления" } } } }
