            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Luxor Formula Van" }, { "de", "Luxor Formula im Minivan" }, { "it", "Luxor Formula in Minivan" }, { "fr", "Louxor Formule Minibus" }, { "ru", "Луксор Формула на минивэне" } },
                Descriptions = new Dictionary<string, string> { { "en", "A value-focused Luxor day trip by air-conditioned van, designed to cover the essential highlights of ancient Thebes in one full day. It is ideal for guests who want the key sights at a competitive price." }, { "de", "Ein erstklassig abgestimmter Tagesausflug nach Luxor im klimatisierten Minivan, der die Höhepunkte des antiken Theben kompakt an einem Tag vereint. Die perfekte Wahl für Reisende, die faszinierende Weltgeschichte zu einem ausgezeichneten Preis-Leistungs-Verhältnis erleben möchten." }, { "it", "Un'escursione giornaliera a Luxor in minivan climatizzato con un perfetto rapporto qualità-prezzo, concepita per ammirare i siti imperdibili dell'antica Tebe in un'unica ricca giornata. Ideale per chi cerca i capolavori storici a condizioni vantaggiose." }, { "fr", "Une excursion d'une journée à Louxor en minibus climatisé alliant confort et excellent rapport qualité-prix, pensée pour découvrir les joyaux incontournables de l'ancienne Thèbes en une journée complète." }, { "ru", "Сбалансированная однодневная экскурсия в Луксор на кондиционированном минивэне, охватывающая главные достопримечательности древних Фив за один насыщенный день. Отличный выбор для тех, кто ценит комфорт и ключевые исторические памятники по привлекательной цене." } },
