                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the Luxor Formula Van tour and what does it include?" }, { "de", "Was ist die Luxor Formula Van Tour und was ist darin enthalten?" }, { "it", "Cos'è il tour Luxor Formula Van e cosa comprende?" }, { "fr", "Qu'est-ce que le tour Luxor Formula Van et qu'est-ce qui est inclus ?" }, { "ru", "Что такое тур Luxor Formula Van и что в него входит?" } }, Answers = new Dictionary<string, string> { { "en", "Luxor Formula Van is our high-value small-group day trip designed to deliver essential highlights efficiently. It includes round-trip air-conditioned van travel, Egyptologist guide, admission to Karnak Temple, Valley of the Kings (3 royal tombs), Colossi of Memnon, and a restaurant lunch." }, { "de", "Luxor Formula Van ist unsere preisbewusste Kleingruppentour im klimatisierten Van mit Fokus auf die berühmtesten Highlights: Karnak-Tempel, Tal der Könige (3 Pharaonengräber), Kolosse von Memnon, lizenzierter Guide und Mittagessen im Restaurant." }, { "it", "Luxor Formula Van è il nostro tour per piccoli gruppi che offre il miglior rapporto qualità-prezzo: viaggio in comodo van climatizzato, guida egittologa, ingressi a Karnak, Valle dei Re (3 tombe) e Colossi di Memnone, oltre al pranzo." }, { "fr", "Luxor Formula Van est notre formule avantageuse en petit groupe en van climatisé pour découvrir l'essentiel : temple de Karnak, Vallée des Rois (3 tombeaux), Colosses de Memnon, guide égyptologue et déjeuner inclus." }, { "ru", "Luxor Formula Van — это сбалансированный по цене и комфорту тур в мини-группе на микроавтобусе: трансфер из отеля, гид-египтолог, билеты в Карнакский храм, Долину Царей (3 гробницы), колоссы Мемнона и горячий обед." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "How does Formula Van differ from the classic Luxor Van tour?" }, { "de", "Wie unterscheidet sich die Formula Van Tour von der klassischen Luxor Van Tour?" }, { "it", "In cosa differisce la Formula Van dal classico tour Luxor Van?" }, { "fr", "Quelle est la différence entre la Formula Van et le tour Luxor Van classique ?" }, { "ru", "Чем тариф Formula Van отличается от классического Luxor Van?" } }, Answers = new Dictionary<string, string> { { "en", "Formula Van focuses on the core trio of ancient wonders (Karnak, Valley of the Kings, Memnon) with streamlined routing and a competitive price point, while Classic Luxor Van also includes Hatshepsut Temple and a scenic Nile motorboat crossing." }, { "de", "Formula Van konzentriert sich zu einem besonders attraktiven Preis auf die drei Kernwunder (Karnak, Tal der Könige, Memnon-Kolosse). Die Classic Van Tour umfasst zusätzlich den Terrassentempel der Hatschepsut und die Nil-Motorbootfahrt." }, { "it", "Formula Van offre un prezzo più accessibile concentrandosi sui 3 monumenti principali (Karnak, Valle dei Re, Memnone). Il tour Classic include in più il tempio di Hatshepsut e la traversata in barca sul Nilo." }, { "fr", "La formule Formula Van va droit au but sur les trois sites phares (Karnak, Vallée des Rois, Memnon) à prix très doux. Le circuit Classique comprend en plus le temple d'Hatchepsout et la navigation sur le Nil." }, { "ru", "Formula Van концентрируется на трех главных жемчужинах (Карнак, Долина Царей, колоссы Мемнона) по более доступной цене. В классический же тур Luxor Van дополнительно включены храм Хатшепсут и катер по Нилу." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What are the schedule timings for Luxor Formula Van?" }, { "de", "Wie sind die Abhol- und Rückkehrzeiten bei Luxor Formula Van?" }, { "it", "Quali sono gli orari di partenza e ritorno per Luxor Formula Van?" }, { "fr", "Quels sont les horaires de la visite Luxor Formula Van ?" }, { "ru", "Какое расписание выезда и возвращения в туре Luxor Formula Van?" } }, Answers = new Dictionary<string, string> { { "en", "Pick-up from Hurghada hotels takes place around 04:45 to 05:30 AM. Sights and lunch are completed by mid-afternoon, arriving back at your hotel around 19:30 to 20:30 PM." }, { "de", "Die Abholung im Hotel erfolgt gegen 04:45 bis 05:30 Uhr. Die Besichtigungen enden am Nachmittag und Sie kehren zwischen 19:30 und 20:30 Uhr zu Ihrem Hotel zurück." }, { "it", "Il prelievo si effettua tra le 04:45 e le 05:30. Dopo le visite e il pranzo si riparte nel pomeriggio, con rientro in hotel previsto tra le 19:30 e le 20:30." }, { "fr", "Le départ a lieu entre 04h45 et 05h30. Les visites et le repas s'achèvent l'après-midi, pour un retour à votre hôtel entre 19h30 et 20h30." }, { "ru", "Выезд из отелей Хургады в 04:45 - 05:30. Осмотр достопримечательностей и обед заканчиваются во второй половине дня, возвращение в отель к 19:30 - 20:30." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I bring on this excursion?" }, { "de", "Was sollte ich für diesen Ausflug mitnehmen?" }, { "it", "Cosa portare per questa escursione?" }, { "fr", "Que faut-il apporter pour cette excursion ?" }, { "ru", "Что взять с собой в поездку?" } }, Answers = new Dictionary<string, string> { { "en", "Bring your original passports, hotel breakfast packet, comfortable walking shoes, sun protection (hat, sunscreen, sunglasses), camera, and Egyptian pounds or euros for drinks and driver/guide gratuities." }, { "de", "Original-Pässe, Frühstücksbox aus dem Hotel, bequeme Schuhe, Sonnenschutz (Hut, Creme, Brille), Kamera und Bargeld für Getränke und Trinkgelder einpacken." }, { "it", "Portate passaporto originale, cestino colazione dell'hotel, scarpe da ginnastica, protezione dal sole (cappello, occhiali, crema), fotocamera e contanti per bibite e mance." }, { "fr", "Prenez vos passeports originaux, panier petit-déjeuner de l'hôtel, chaussures de marche, protection solaire (chapeau, crème, lunettes), appareil photo et argent liquide." }, { "ru", "Оригиналы паспортов, сухой завтрак из отеля, удобную обувь, головной убор, солнцезащитный крем, очки, телефон и наличные деньги на напитки и чаевые." } } } },
