                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Luxor Formula Eco tour?" }, { "de", "Was ist im budgetfreundlichen Luxor Formula Eco Ausflug enthalten?" }, { "it", "Cosa comprende l'escursione economica Luxor Formula Eco?" }, { "fr", "Qu'est-ce qui est inclus dans le circuit économique Luxor Formula Eco ?" }, { "ru", "Что входит в эконом-тур в Луксор (Luxor Formula Eco)?" } }, Answers = new Dictionary<string, string> { { "en", "Luxor Formula Eco is our most economical day trip by spacious air-conditioned touring coach. It covers hotel transfers, licensed tour guide, admission tickets to Karnak Temple, the Valley of the Kings (3 tombs), the Colossi of Memnon, and lunch at a local restaurant." }, { "de", "Luxor Formula Eco ist unsere günstigste Tagestour im großen klimatisierten Reisebus. Sie beinhaltet Hoteltransfers, lizenzierten Reiseleiter, Eintritt zum Karnak-Tempel, ins Tal der Könige (3 Gräber), zu den Memnon-Kolossen sowie ein Mittagessen." }, { "it", "Luxor Formula Eco è la nostra escursione più economica in grande pullman turistico climatizzato. Include trasferimenti, guida turistica autorizzata, biglietti per il Tempio di Karnak, Valle dei Re (3 tombe), Colossi di Memnone e pranzo al ristorante." }, { "fr", "Luxor Formula Eco est notre option la plus abordable en grand car grand tourisme climatisé. Elle comprend les transferts, guide officiel, billets pour Karnak, Vallée des Rois (3 tombes), Colosses de Memnon et déjeuner." }, { "ru", "Luxor Formula Eco — самый доступный вариант поездки в Луксор на большом комфортабельном кондиционированном автобусе. Включены трансфер из отеля, гид, билеты в Карнакский храм, Долину Царей (3 гробницы), колоссы Мемнона и горячий обед." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "How is Formula Eco different from Formula Van and classic Luxor Van?" }, { "de", "Wie unterscheidet sich Formula Eco von Formula Van und der Classic Tour?" }, { "it", "In cosa differisce Formula Eco da Formula Van e dal tour Classic?" }, { "fr", "Quelle est la différence entre Formula Eco, Formula Van et le tour Classique ?" }, { "ru", "В чем разница между Formula Eco, Formula Van и классическим Luxor Van?" } }, Answers = new Dictionary<string, string> { { "en", "Formula Eco travels in a large shared tourist coach (30 to 45 guests) ensuring the lowest possible price point, while Formula Van and Classic Van use small intimate vans (8 to 14 guests) that arrive faster and spend less time picking up guests from hotels." }, { "de", "Formula Eco fährt mit einem großen Reisebus (30 bis 45 Gäste) zum unschlagbaren Sparpreis. Formula Van und Classic Van nutzen kleine, wendige Minivans (8 bis 14 Personen) mit kürzeren Abholrunden und schnellerer Fahrt." }, { "it", "Formula Eco viaggia su grandi bus gran turismo (30-45 passeggeri) garantendo il prezzo più basso. Formula Van e Classic impiegano minivan compatti (8-14 passeggeri) con trasferimenti più veloci e gruppi ristretti." }, { "fr", "Formula Eco s'effectue en autocar partagé (30 à 45 passagers) pour un tarif imbattable. Les formules Van utilisent des minibus (8 à 14 personnes) offrant des trajets plus rapides et un accueil plus personnalisé." }, { "ru", "Formula Eco выполняется на большом экскурсионном автобусе (30-45 человек) по самой выгодной цене. Тарифы Van используют небольшие микроавтобусы (8-14 гостей), что ускоряет сбор по отелям и дорогу." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What are the departure hours and return time for Formula Eco?" }, { "de", "Wie sind die Abfahrts- und Rückkehrzeiten bei Formula Eco?" }, { "it", "Quali sono gli orari di partenza e arrivo per Formula Eco?" }, { "fr", "Quels sont les horaires de ramassage pour Formula Eco ?" }, { "ru", "Каковы время отправления и возвращения для тарифа Formula Eco?" } }, Answers = new Dictionary<string, string> { { "en", "Hotel pickups start from 04:15 to 05:00 AM across Hurghada. The day is full of ancient history, returning to Hurghada between 20:30 and 21:30 PM." }, { "de", "Die Abholung beginnt zwischen 04:15 und 05:00 Uhr in den Hotels. Sie erleben einen erfüllten Tag voller Geschichte und kehren gegen 20:30 bis 21:30 Uhr zurück." }, { "it", "I prelievi iniziano tra le 04:15 e le 05:00 del mattino. L'intera giornata è dedicata all'archeologia con rientro in hotel tra le 20:30 e le 21:30." }, { "fr", "Le ramassage a lieu de 04h15 à 05h00. Vous vivez une journée historique complète et rentrez à votre hôtel entre 20h30 et 21h30." }, { "ru", "Сбор туристов по отелям начинается с 04:15 до 05:00. Полный день погружения в древнюю историю, возвращение в отель к 20:30 - 21:30." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I bring along for this trip?" }, { "de", "Was sollte man für diese Tour mitnehmen?" }, { "it", "Cosa portare con sé per questo tour?" }, { "fr", "Que faut-il emporter pour cette excursion ?" }, { "ru", "Что взять с собой в автобусный тур?" } }, Answers = new Dictionary<string, string> { { "en", "Passport original (strictly checked at checkpoints), breakfast box from hotel reception, bottle of water, comfortable walking shoes, sun hat, and cash for drinks or souvenirs." }, { "de", "Reisepass im Original (Polizeikontrollen), Frühstücksbox vom Hotel, Wasserflasche, bequeme Schuhe, Sonnenhut und Bargeld für Getränke und Souvenirs." }, { "it", "Passaporto originale, cestino per la colazione dell'hotel, bottiglietta d'acqua, scarpe comode, cappellino per il sole e contanti per bevande o souvenir." }, { "fr", "Passeport original obligatoire, boîte petit-déjeuner, bouteille d'eau, bonnes chaussures, chapeau et monnaie pour boissons et souvenirs." }, { "ru", "Оригинал паспорта (строго проверяется на КПП), ланч-бокс с завтраком из отеля, бутылку воды, удобную обувь, кепку или панаму и наличные деньги на напитки и сувениры." } } } },
