            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Luxor Balloon" }, { "de", "Heißluftballonfahrt über Luxor" }, { "it", "Volo in Mongolfiera a Luxor" }, { "fr", "Vol en Montgolfière à Louxor" }, { "ru", "Полет на воздушном шаре в Луксоре" } },
                Descriptions = new Dictionary<string, string> { { "en", "Fly over the ancient monuments of Luxor at sunrise in a hot air balloon. Experience aerial views of the West Bank temples and the Nile River." }, { "de", "Schweben Sie bei Sonnenaufgang im Heißluftballon über die monumentalen Wunder von Luxor. Genießen Sie atemberaubende Panoramablicke auf die Tempel des thebanischen Westufers, die Wüstenberge und das smaragdgrüne Band des Nils." }, { "it", "Librati in volo all'alba a bordo di una mongolfiera sopra i leggendari monumenti di Luxor. Vivi una prospettiva aerea spettacolare sui templi della Riva Ovest, sul fiume Nilo e sui paesaggi senza tempo illuminati dalle prime luci del mattino." }, { "fr", "Survolez les merveilles millénaires de Louxor au lever du soleil à bord d'une montgolfière. Admirez un panorama céleste saisissant sur les temples de la rive ouest, la vallée du Nil et les reflets dorés du désert égyptien." }, { "ru", "Встретьте восход солнца на высоте птичьего полета во время незабываемого полета на воздушном шаре над Луксором. Перед вами откроется захватывающая панорама фиванских храмов западного берега, живописной ленты Нила и залитых золотом утренних пейзажей." } },
