                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Luxor Hot Air Balloon experience?" }, { "de", "Was ist beim Heißluftballonflug in Luxor enthalten?" }, { "it", "Cosa comprende l'esperienza del volo in mongolfiera a Luxor?" }, { "fr", "Qu'est-ce qui est inclus dans le vol en montgolfière à Louxor ?" }, { "ru", "Что входит в полет на воздушном шаре в Луксоре (Luxor Balloon)?" } }, Answers = new Dictionary<string, string> { { "en", "The experience includes transfers from your Luxor hotel or Nile dock, a scenic dawn motorboat crossing with hot tea and coffee, safety briefing, a breathtaking 40 to 50 minute sunrise hot air balloon flight soaring above the Valley of the Kings, Hatshepsut Temple, the Ramesseum, and green Nile farm banks, accompanied by a commemorative flight certificate signed by your certified pilot." }, { "de", "Das Erlebnis beinhaltet Abholung vom Luxor-Hotel/Schiff, Nilüberquerung im Motorboot bei Morgendämmerung mit heißem Tee/Kaffee, Sicherheitseinweisung, einen spektakulären 40- bis 50-minütigen Heißluftballonflug bei Sonnenaufgang über dem Tal der Könige, Hatschepsut-Tempel, Ramesseum und Nil-Ufer sowie eine Flugurkunde." }, { "it", "L'esperienza include transfer dall'hotel/nave a Luxor, traversata del Nilo all'alba in barca a motore con tè o caffè caldi, briefing di sicurezza, uno spettacolare volo di 40-50 minuti all'alba sorvolando la Valle dei Re, il tempio di Hatshepsut, il Ramesseum e il verde corso del Nilo, con certificato di volo ricordo firmato dal pilota." }, { "fr", "L'expérience comprend les transferts depuis Louxor, la traversée du Nil à l'aube en bateau avec thé et café chauds, le briefing de sécurité, un vol féerique de 40 à 50 minutes au lever du soleil au-dessus de la Vallée des Rois, d'Hatchepsout et des berges verdoyantes du Nil, avec certificat de vol remis par le pilote." }, { "ru", "В тур входят трансфер из отеля в Луксоре, переправа через Нил на рассвете на катере с горячим чаем/кофе, инструктаж по безопасности, полет на воздушном шаре 40-50 минут на рассвете над Долиной Царей, храмом Хатшепсут, Рамессеумом и зелеными полями Нила, а также памятный сертификат воздухоплавателя." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "How safe is the hot air balloon flight in Luxor?" }, { "de", "Wie sicher ist der Heißluftballonflug in Luxor?" }, { "it", "Quanto è sicuro il volo in mongolfiera a Luxor?" }, { "fr", "Le vol en montgolfière à Louxor est-il sécurisé ?" }, { "ru", "Насколько безопасен полет на воздушном шаре в Луксоре?" } }, Answers = new Dictionary<string, string> { { "en", "Safety is paramount. All balloon operations are strictly monitored by the Egyptian Civil Aviation Authority (ECAA). Balloons only launch when atmospheric wind speed and thermal conditions are certified 100% safe. Every flight is piloted by a veteran, ECAA-licensed commercial balloon master." }, { "de", "Sicherheit hat höchste Priorität. Alle Flüge werden von der ägyptischen Zivilluftfahrtbehörde (ECAA) streng kontrolliert. Starts finden nur bei optimalen Wind- und Wetterbedingungen statt. Jeder Pilot besitzt eine staatliche Verkehrspilotenlizenz mit langjähriger Erfahrung." }, { "it", "La sicurezza è assoluta. Tutti i voli sono autorizzati e monitorati quotidianamente dall'Autorità Egiziana per l'Aviazione Civile (ECAA). Si decolla solo con condizioni meteo e di vento ottimali e i piloti sono professionisti certificati di lunga esperienza." }, { "fr", "La sécurité est la priorité absolue. Les vols sont soumis au contrôle strict de l'Aviation Civile Égyptienne (ECAA). Aucun décollage n'a lieu si le vent dépasse les normes. Tous nos pilotes sont certifiés et chevronnés." }, { "ru", "Безопасность полетов находится под строгим контролем Управления гражданской авиации Египта (ECAA). Разрешение на взлет выдается диспетчерами только при идеальных погодных условиях и скорости ветра. Все пилоты имеют международные лицензии коммерческой авиации." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What time is the flight and can we do it directly from Hurghada?" }, { "de", "Um wie viel Uhr findet der Flug statt und kann man ihn direkt ab Hurghada machen?" }, { "it", "A che ora si vola ed è fattibile partendo direttamente da Hurghada?" }, { "fr", "À quelle heure décolle la montgolfière et peut-on la faire directement depuis Hurghada ?" }, { "ru", "В какое время проходит полет и можно ли полетать с выездом из Хургады?" } }, Answers = new Dictionary<string, string> { { "en", "Balloons launch right as the sun breaches the horizon (around 05:00 to 05:45 AM). If booking from Hurghada as a same-day trip, departure is very early (around 01:30 to 02:00 AM) to reach Luxor before dawn. Alternatively, booking the Luxor Overnight tour allows you to sleep in Luxor and wake up at a relaxed hour for the flight." }, { "de", "Die Ballons steigen exakt bei Sonnenaufgang auf (ca. 05:00 bis 05:45 Uhr). Bei Start ab Hurghada am selben Tag erfolgt die Abholung sehr früh gegen 01:30 bis 02:00 Uhr. Bequemer ist die Buchung der Luxor-Übernachtungstour, bei der Sie bereits vor Ort in Luxor schlafen." }, { "it", "Le mongolfiere decollano al sorgere del sole (ore 05:00 - 05:45). Se si parte da Hurghada in giornata, il prelievo è notturno (ore 01:30 - 02:00). In alternativa, scegliendo il tour con pernottamento a Luxor si pernotta sul posto partendo comodamente al mattino." }, { "fr", "Le décollage a lieu au lever du jour (05h00 - 05h45). Si vous partez d'Hurghada le jour même, le départ se fait vers 01h30 - 02h00 du matin. L'idéal est de combiner le vol avec la formule 2 jours (Overnight) pour dormir sur place." }, { "ru", "Шары взлетают в момент восхода солнца (около 05:00 - 05:45). При однодневной поездке из Хургады выезд очень ранний — около 01:30 - 02:00 ночи. Самый комфортный способ — взять тур Luxor Overnight, переночевать в отеле в Луксоре и встретить рассвет на шаре без ночной дороги." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear and are there age restrictions?" }, { "de", "Was soll ich anziehen und gibt es Altersgrenzen?" }, { "it", "Cosa indossare e quali sono i limiti d'età?" }, { "fr", "Comment s'habiller et y a-t-il un âge minimum ?" }, { "ru", "Что надеть и какие возрастные ограничения действуют на шаре?" } }, Answers = new Dictionary<string, string> { { "en", "Wear comfortable flat shoes (sneakers) and casual pants. Dress in layers with a jacket, as dawn air can be chilly, but the balloon burner overhead radiates gentle warmth. Minimum age is 6 years. The activity is not suitable for pregnant women or individuals with severe vertigo or mobility issues requiring crutches/wheelchairs." }, { "de", "Flache feste Schuhe (Sneaker) und lange Hosen anziehen. Zwiebellook mit einer warmen Jacke für den frühen Morgen (die Brenner über dem Korb wärmen angenehm). Mindestalter 6 Jahre. Nicht geeignet für Schwangere, Personen mit extremer Höhenangst oder Gehbehinderung." }, { "it", "Scarpe basse chiuse (scarpe da ginnastica) e pantaloni comodi. Vestitevi a strati con giacca a vento leggera (il bruciatore riscalda dall'alto). Età minima 6 anni. Non adatto a donne in gravidanza o persone con gravi problemi di vertigini o ridotta mobilità." }, { "fr", "Chaussures plates fermées (baskets) et pantalon confortable. Habillez-vous en couches avec une veste pour la fraîcheur de l'aube. Âge minimum 6 ans. Déconseillé aux femmes enceintes et aux personnes souffrant de vertige aigu ou à mobilité réduite." }, { "ru", "Наденьте закрытую обувь на плоской подошве (кроссовки) и брюки. Одевайтесь многослойно с ветровкой/курткой для утренней прохлады (сверху приятно греет горелка). Дети допускаются с 6 лет. Полет противопоказан беременным женщинам и людям с тяжелыми нарушениями опорно-двигательного аппарата." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193202.jpg", Captions = new Dictionary<string, string> { { "en", "Luxor Balloon - Experience" }, { "de", "Heißluftballonfahrt über Luxor - Erlebnis" }, { "it", "Volo in Mongolfiera a Luxor - Esperienza" }, { "fr", "Vol en Montgolfière à Louxor - Expérience" }, { "ru", "Полет на воздушном шаре в Луксоре - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193223.jpg", Captions = new Dictionary<string, string> { { "en", "Luxor Balloon - Experience" }, { "de", "Heißluftballonfahrt über Luxor - Erlebnis" }, { "it", "Volo in Mongolfiera a Luxor - Esperienza" }, { "fr", "Vol en Montgolfière à Louxor - Expérience" }, { "ru", "Полет на воздушном шаре в Луксоре - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193231.jpg", Captions = new Dictionary<string, string> { { "en", "Luxor Balloon - Experience" }, { "de", "Heißluftballonfahrt über Luxor - Erlebnis" }, { "it", "Volo in Mongolfiera a Luxor - Esperienza" }, { "fr", "Vol en Montgolfière à Louxor - Expérience" }, { "ru", "Полет на воздушном шаре в Луксоре - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Cairo Van" }, { "de", "Tagesausflug Kairo im Minivan" }, { "it", "Il Cairo in Minivan" }, { "fr", "Le Caire en Minibus Climatisé" }, { "ru", "Экскурсия в Каир на комфортабельном минивэне" } },
                Descriptions = new Dictionary<string, string> { { "en", "Travel from Hurghada to Cairo by road for a full-day introduction to Egypt's capital and its ancient treasures. Depending on the selected programme, visit the Giza Pyramids, Sphinx, museum and other major sights." }, { "de", "Reisen Sie im komfortablen Minivan von Hurghada in die Metropole Kairo und entdecken Sie das Herz der ägyptischen Zivilisation. Je nach Programm besichtigen Sie die Pyramiden von Gizeh, die geheimnisvolle Sphinx, das Ägyptische Museum und weitere weltberühmte Wahrzeichen." }, { "it", "Raggiungi Il Cairo da Hurghada in minivan climatizzato per un'immersione di un'intera giornata tra i tesori della capitale egiziana. A seconda dell'itinerario, visita le leggendarie Piramidi di Giza, la Sfinge, il Museo Egizio e i principali capolavori storici." }, { "fr", "Voyagez d'Hurghada au Caire en minibus tout confort pour une journée immersive au cœur des trésors de la capitale égyptienne. Selon le programme choisi, découvrez les pyramides de Gizeh, le Sphinx, le musée égyptien et les grands joyaux historiques." }, { "ru", "Отправьтесь из Хургады в Каир на комфортабельном минивэне в однодневное путешествие к истокам цивилизации. В зависимости от выбранной программы вы увидите пирамиды Гизы, загадочного Сфинкса, экспонаты Египетского музея и другие ключевые достопримечательности столицы." } },
