                ImageUrl = "/images/tours/5861626853276193192.jpg",
                MediaUrls = new List<string> { "/images/tours/5861626853276193192.jpg", "/images/tours/5861626853276193193.jpg", "/images/tours/5861626853276193200.jpg", "/images/tours/5861626853276193201.jpg", "/images/tours/5861626853276193203.jpg", "/images/tours/5861626853276193206.jpg", "/images/tours/5861626853276193207.jpg", "/images/tours/5861626853276193208.jpg", "/images/tours/5861626853276193209.jpg", "/images/tours/5861626853276193213.jpg", "/images/tours/5861626853276193214.jpg", "/images/tours/5861626853276193215.jpg", "/images/tours/5861626853276193216.jpg", "/images/tours/5861626853276193217.jpg", "/images/tours/5861626853276193218.jpg", "/images/tours/5861626853276193219.jpg", "/images/tours/5861626853276193220.jpg", "/images/tours/5861626853276193226.jpg", "/images/tours/5861626853276193227.jpg", "/images/tours/5861626853276193228.jpg", "/images/tours/5861626853276193230.jpg", "/images/tours/5861626853276193234.jpg", "/images/tours/5861626853276193236.jpg", "/images/tours/5861626853276193241.jpg", "/images/tours/5861626853276193244.jpg", "/images/tours/5861626853276193245.jpg", "/images/tours/5861626853276193246.jpg", "/images/tours/5861626853276193247.jpg", "/images/tours/5861626853276193248.jpg", "/images/tours/5861626853276193252.jpg", "/images/tours/5861626853276193253.jpg", "/images/tours/5861626853276193254.jpg", "/images/tours/5861626853276193256.jpg", "/images/tours/5861626853276193258.jpg", "/images/tours/5861626853276193259.jpg", "/images/tours/5861626853276193260.jpg", "/images/tours/5861626853276193261.jpg", "/images/tours/5861626853276193262.jpg", "/images/tours/5861626853276193263.jpg", "/images/tours/5861626853276193265.jpg", "/images/tours/5861626853276193267.jpg", "/images/tours/5861626853276193269.jpg", "/images/tours/5861626853276193271.jpg", "/images/tours/5861626853276193272.jpg", "/images/tours/5861626853276193275.jpg", "/images/tours/5861626853276193276.jpg", "/images/tours/5861626853276193278.jpg", "/images/tours/5861626853276193280.jpg", "/images/tours/5861626853276193282.jpg" },
                ReserveAndPayLater = true,
                HotelPickup = true,
                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What sights are visited and what is included in the Cairo Van tour?" }, { "de", "Welche Sehenswürdigkeiten werden besucht und was ist in der Kairo-Van-Tour enthalten?" }, { "it", "Cosa si visita e cosa comprende il tour Cairo Van in minivan?" }, { "fr", "Quels monuments visite-t-on et qu'est-ce qui est inclus dans le tour Cairo Van ?" }, { "ru", "Какие достопримечательности входят в тур в Каир на микроавтобусе (Cairo Van)?" } }, Answers = new Dictionary<string, string> { { "en", "The tour includes round-trip transport in a modern air-conditioned van, licensed Egyptologist guide, entry tickets to the Giza Plateau (Great Pyramids of Khufu, Khafre, Menkaure), the Great Sphinx and Valley Temple, the world-famous Egyptian Museum in Tahrir Square (housing royal treasures and mummies), a visit to traditional papyrus and perfume craft centers, and a delicious lunch at an oriental restaurant." }, { "de", "Die Tour beinhaltet Hin- und Rückfahrt im modernen klimatisierten Minivan, lizenzierten Ägyptologen, Eintrittskarten zum Gizeh-Plateau (Große Pyramiden von Cheops, Chephren, Mykerinos), zur Sphinx und zum Taltempel, in das Ägyptische Museum am Tahrir-Platz mit Pharaonenschätzen, Besuch traditioneller Papyrus- und Parfümateliers sowie Mittagessen." }, { "it", "Il tour comprende viaggio a/r in moderno van climatizzato, guida egittologa qualificata, biglietti d'ingresso alla Piana di Giza (Piramidi di Cheope, Chefren, Micerino), alla Grande Sfinge e Tempio della Valle, al Museo Egizio di Piazza Tahrir, visita a laboratori di papiro ed essenze profumate e pranzo in ristorante tipico." }, { "fr", "L'excursion comprend le trajet en van climatisé tout confort, guide égyptologue, entrées pour le plateau de Gizeh (pyramides de Khéops, Khéphren, Mykérinos), le Sphinx et le temple de la vallée, le musée égyptien de la place Tahrir, découverte des ateliers de papyrus et parfums et déjeuner au restaurant." }, { "ru", "В тур входят проезд на современном кондиционированном микроавтобусе, профессиональный гид-египтолог, входные билеты на плато Гиза (Великие пирамиды Хеопса, Хефрена, Микерина), к Большому Сфинксу и гранитному храму, в Египетский музей на площади Тахрир, посещение институтов папируса и масел, а также вкусный обед в ресторане." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the pickup schedule and how long is the journey to Cairo?" }, { "de", "Wie sind die Abholzeiten und wie lange dauert die Fahrt nach Kairo?" }, { "it", "Quali sono gli orari e quanto dura il tragitto per Il Cairo?" }, { "fr", "Quels sont les horaires de départ et la durée du voyage vers Le Caire ?" }, { "ru", "Каковы время выезда и сколько занимает дорога до Каира?" } }, Answers = new Dictionary<string, string> { { "en", "Departure from Hurghada is early, between 01:45 and 02:30 AM. Driving along the scenic Red Sea coastal highway to Cairo takes about 5.5 to 6 hours with a comfort stop. You arrive at the pyramids around 08:30 AM, tour throughout the day, and return to Hurghada around 21:00 to 22:30 PM." }, { "de", "Die Abholung in Hurghada erfolgt zwischen 01:45 und 02:30 Uhr. Die Fahrt über die moderne Küstenautobahn dauert ca. 5,5 bis 6 Stunden mit Rastpause. Ankunft an den Pyramiden gegen 08:30 Uhr; Rückkehr zum Hotel gegen 21:00 bis 22:30 Uhr." }, { "it", "La partenza da Hurghada è notturna, tra le 01:45 e le 02:30. Il viaggio lungo la litoranea richiede circa 5,5 - 6 ore con sosta ristoro. Arrivo alle piramidi verso le 08:30 e rientro in hotel a Hurghada in serata tra le 21:00 e le 22:30." }, { "fr", "Départ d'Hurghada entre 01h45 et 02h30 du matin. Le trajet par l'autoroute côtière dure environ 5h30 à 6 heures avec pause café. Arrivée aux pyramides vers 08h30, visites toute la journée et retour à l'hôtel vers 21h00 - 22h30." }, { "ru", "Выезд из отелей Хургады ночью, между 01:45 и 02:30. Дорога по новой скоростной трассе занимает около 5,5-6 часов с остановкой в кафе. Прибытие к пирамидам около 08:30 утра, возвращение в отель к 21:00 - 22:30." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Can I go inside the Great Pyramid of Giza?" }, { "de", "Darf man in das Innere der Cheops-Pyramide hineingehen?" }, { "it", "È possibile entrare all'interno della Grande Piramide di Cheope?" }, { "fr", "Peut-on entrer à l'intérieur de la Grande Pyramide de Khéops ?" }, { "ru", "Можно ли зайти внутрь Великой пирамиды Хеопса?" } }, Answers = new Dictionary<string, string> { { "en", "Yes! Entry into the interior burial chamber of the Great Pyramid of Khufu (or Khafre) is available with an extra special ticket purchased directly at the Giza gate. Note: the interior passage is steep, narrow, and warm, so it is not recommended for individuals with claustrophobia or heart conditions." }, { "de", "Ja! Der Einstieg in die Grabkammer der großen Cheops-Pyramide ist mit einem separaten Ticket an der Kasse möglich. Hinweis: Der aufsteigende Schacht ist eng, steil und warm – nicht empfohlen bei Klaustrophobie oder Herz-Kreislauf-Problemen." }, { "it", "Sì! È possibile accedere alla camera funeraria interna della Grande Piramide acquistando un biglietto extra direttamente all'ingresso. Attenzione: il cunicolo interno è ripido, stretto e caldo, sconsigliato a chi soffre di claustrofobia o problemi cardiaci." }, { "fr", "Oui ! Il est possible de pénétrer au cœur de la Grande Pyramide grâce à un billet supplémentaire acheté à la billetterie. Attention : le boyau est étroit, pentu et chaud, déconseillé aux personnes claustrophobes." }, { "ru", "Да! Зайти в погребальную камеру внутри Великой пирамиды можно по дополнительному билету, который покупается в кассе комплекса. Обратите внимание: проход узкий и душный, поэтому подъем не рекомендуется при клаустрофобии и болезнях сердца." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I pack and wear for Cairo?" }, { "de", "Was sollte ich für Kairo einpacken und anziehen?" }, { "it", "Cosa mettere in valigia e come vestirsi per Il Cairo?" }, { "fr", "Que faut-il emporter et porter pour visiter Le Caire ?" }, { "ru", "Что взять с собой и как одеться в поездку в Каир?" } }, Answers = new Dictionary<string, string> { { "en", "Wear comfortable walking shoes, modest breathable clothing covering shoulders and knees, a hat, and sunglasses. Essential items to pack: original passports, hotel breakfast box (order the evening before), travel pillow for the road, power bank for your phone, and cash for drinks and souvenirs." }, { "de", "Bequeme Schuhe, respektvolle Kleidung (Schultern und Knie bedeckt), Kopfbedeckung und Sonnenbrille. Unbedingt mitnehmen: Original-Pässe, Frühstücksbox vom Hotel, Nackenkissen für die Fahrt, Powerbank für das Smartphone und Bargeld." }, { "it", "Scarpe da ginnastica comode, abiti decorosi che coprano spalle e ginocchia, cappello e occhiali. Indispensabili: passaporti originali, cestino colazione dell'hotel, cuscino da viaggio per il minibus, power bank e contanti." }, { "fr", "Chaussures de marche, vêtements décents couvrant épaules et genoux, chapeau et lunettes. N'oubliez pas : passeports originaux, panier petit-déjeuner de l'hôtel, coussin de voyage, batterie externe et espèces." }, { "ru", "Удобную обувь для прогулок, легкую одежду, прикрывающую плечи и колени, панаму и солнцезащитные очки. С собой обязательно: оригиналы паспортов, сухой паек из отеля, дорожную подушку, повербанк для телефона и наличные деньги." } } } },
                Addons = new List<TourAddon>(),
