                Descriptions = new Dictionary<string, string> { { "en", "Explore Cairo at a more relaxed pace with an overnight stay. Discover the pyramids and major historical attractions, enjoy the atmosphere of the capital and continue sightseeing the following day before returning to the Red Sea." }, { "de", "Erleben Sie Kairo in all seinen Facetten in entspanntem Rhythmus inklusive stilvoller Übernachtung. Bestaunen Sie die Pyramiden und historische Glanzlichter, spüren Sie das faszinierende Flair der Metropole und setzen Sie Ihre Entdeckungsreise am zweiten Tag fort, bevor es zurück ans Rote Meer geht." }, { "it", "Scopri Il Cairo con la dovuta calma grazie a un itinerario di due giorni con pernottamento. Esplora le piramidi e le attrazioni più celebri, assapora l'autentica atmosfera della metropoli e prosegui le visite il giorno seguente prima di fare ritorno sul Mar Rosso." }, { "fr", "Prenez le temps d'apprécier Le Caire grâce à un séjour de deux jours avec nuitée d'exception. Explorez les pyramides et les grands sites historiques à votre rythme, imprégnez-vous de l'effervescence de la capitale et enrichissez votre visite le lendemain avant le retour sur la mer Rouge." }, { "ru", "Познакомьтесь с Каиром в размеренном темпе в рамках двухдневного тура с ночевкой. Осмотрите великие пирамиды и ключевые исторические достопримечательности, прочувствуйте колорит восточной столицы и продолжите экскурсии на следующий день перед возвращением на Красное море." } },
                Price = 265,
                Currency = "EUR",
                Duration = "Approx. 2 days / 1 night",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000013"),
                CategoryId = Guid.Parse("00000000-0000-0000-0000-000000000009"),
                Emoji = "🏛️",
                ImageUrl = "/images/tours/5861626853276193192.jpg",
                MediaUrls = new List<string> { "/images/tours/5861626853276193192.jpg", "/images/tours/5861626853276193193.jpg", "/images/tours/5861626853276193200.jpg" },
                ReserveAndPayLater = true,
                HotelPickup = true,
                FreeCancellation = true,
                IsTopRated = true,
                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What sights are included in the 2-Day Cairo Overnight tour?" }, { "de", "Welche Sehenswürdigkeiten sind in der 2-tägigen Kairo-Tour enthalten?" }, { "it", "Cosa comprende l'itinerario del tour di 2 giorni al Cairo con pernottamento?" }, { "fr", "Quelles visites comprend le circuit de 2 jours au Caire avec nuit d'hôtel ?" }, { "ru", "Какие достопримечательности входят в двухдневный тур в Каир (Cairo Overnight)?" } }, Answers = new Dictionary<string, string> { { "en", "This immersive cultural journey covers round-trip air-conditioned transport, 1 night in a 4-star Cairo hotel with breakfast, two full days of private/small-group Egyptologist guiding, Giza Pyramids and Great Sphinx, Saqqara (the Step Pyramid of Djoser), the Egyptian Museum, Historic Coptic Cairo (the Hanging Church and Church of St. Sergius), the bustling Khan el-Khalili bazaar, and two restaurant lunches." }, { "de", "Diese faszinierende Kulturreise umfasst den Hin- und Rücktransfer im klimatisierten Fahrzeug, 1 Hotelübernachtung (4-Sterne inkl. Frühstück), 2 Tage Führung mit Ägyptologen, Pyramiden von Gizeh und Sphinx, Sakkara mit der Djoser-Stufenpyramide, das Ägyptische Museum, das koptische Viertel (Hängende Kirche), den Basar Khan el-Khalili und 2x Mittagessen." }, { "it", "Questo viaggio affascinante comprende viaggio a/r climatizzato, 1 notte in hotel 4 stelle al Cairo con colazione, 2 intere giornate con guida egittologa, Piramidi di Giza e Sfinge, Saqqara (la piramide a gradoni di Djoser), il Museo Egizio, il Cairo Copto storico (la Chiesa Sospesa), il bazar di Khan el-Khalili e 2 pranzi." }, { "fr", "Ce voyage complet comprend les trajets aller-retour climatisés, 1 nuit en hôtel 4 étoiles avec petit-déjeuner, 2 journées avec guide égyptologue, pyramides de Gizeh et Sphinx, Saqqarah (pyramide à degrés de Djéser), musée égyptien, le Vieux Caire copte (l'Église suspendue), le souk de Khan el-Khalili et 2 déjeuners." }, { "ru", "Этот насыщенный тур включает комфортабельный трансфер, 1 ночь в 4-звездочном отеле в Каире с завтраком, 2 полных дня экскурсий с египтологом, пирамиды Гизы и Сфинкса, Саккару (ступенчатую пирамиду Джосера), Египетский музей, Древний Коптский Каир (Висячую церковь), колоритный восточный базар Хан эль-Халили и 2 обеда." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Why choose the Cairo Overnight tour over the single-day trip?" }, { "de", "Warum sollte man die 2-Tages-Tour nach Kairo dem Tagesausflug vorziehen?" }, { "it", "Quali sono i vantaggi del tour di 2 giorni rispetto all'escursione in giornata?" }, { "fr", "Pourquoi privilégier le séjour de 2 jours par rapport à la journée simple au Caire ?" }, { "ru", "В чем преимущества двухдневного тура в Каир по сравнению с однодневным?" } }, Answers = new Dictionary<string, string> { { "en", "Cairo is a gigantic metropolis with thousands of years of history. The overnight tour cuts daily driving stress in half, unlocks deeper hidden wonders like Saqqara and atmospheric Old Cairo, lets you stroll the exotic Khan el-Khalili market at twilight, and avoids exhaustion." }, { "de", "Kairo ist eine faszinierende Weltmetropole. Die Übernachtungstour halbiert den Fahrstress, ermöglicht exklusive Besichtigungen wie die Stufenpyramide von Sakkara und das koptische Alt-Kairo, und lässt Sie den Basar Khan el-Khalili abends bei orientalischem Flair erleben." }, { "it", "Il Cairo è una metropoli immensa. La formula 2 giorni dimezza la fatica del viaggio su strada, include meraviglie imperdibili come la piramide a gradoni di Saqqara e il fascino senza tempo dei mercati storici di Khan el-Khalili illuminati di sera." }, { "fr", "Le Caire regorge de trésors inestimables. Ce circuit de 2 jours réduit la fatigue de la route, permet de découvrir Saqqarah et le quartier copte, et vous offre une soirée inoubliable au cœur du souk animé de Khan el-Khalili." }, { "ru", "Каир — грандиозный древний мегаполис. Двухдневный тур избавляет от дорожной усталости, позволяет увидеть древнейшую ступенчатую пирамиду в Саккаре, старинный Коптский квартал и ощутить колорит вечернего базара Хан эль-Халили." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Can we book an optional Nile Dinner Cruise on the evening of Day 1?" }, { "de", "Kann man am Abend des ersten Tages eine Nil-Dinner-Kreuzfahrt zubuchen?" }, { "it", "È possibile fare una crociera serale sul Nilo con cena il primo giorno?" }, { "fr", "Peut-on réserver une croisière dîner sur le Nil le soir du 1er jour ?" }, { "ru", "Можно ли заказать вечерний круиз по Нилу с ужином в первый вечер?" } }, Answers = new Dictionary<string, string> { { "en", "Yes! An optional evening Nile Dinner Cruise aboard a floating restaurant is a favorite addition. You enjoy a buffet dinner, live oriental band, belly dance show, and whirling Tanoura performance as Cairo's illuminated bridges glide by." }, { "de", "Ja! Eine abendliche Nil-Dinnerkreuzfahrt auf einem Restaurantschiff ist ein beliebtes Extra. Sie genießen ein Buffet-Abendessen, orientalische Live-Musik, Bauchtanz und eine Tanoura-Show, während die Lichter Kairos vorbeiziehen." }, { "it", "Sì! La crociera serale con cena sul Nilo a bordo di un battello galleggiante è una delle opzioni più amate: cena a buffet, musica dal vivo, spettacolo di danza del ventre e Tanoura con vista sui ponti illuminati del Cairo." }, { "fr", "Oui ! Une croisière dîner sur le Nil à bord d'un bateau restaurant est très prisée en soirée : dîner buffet, orchestre oriental, spectacle de danse orientale et Tanoura avec vue sur les lumières du Caire." }, { "ru", "Да! Вечерний круиз по Нилу на теплоходе с ужином — прекрасное дополнение к программе: вкусный 'шведский стол', живая музыка, танец живота и танура на фоне огней ночного Каира." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I pack for the 2-day trip to Cairo?" }, { "de", "Was soll ich für die 2-tägige Kairo-Reise einpacken?" }, { "it", "Cosa mettere in valigia per il tour di 2 giorni al Cairo?" }, { "fr", "Que faut-il emporter pour ce séjour de 2 jours au Caire ?" }, { "ru", "Что взять с собой в двухдневную поездку в Каир?" } }, Answers = new Dictionary<string, string> { { "en", "Bring a small travel bag (heavy suitcases remain in your Hurghada hotel). Pack original passports, a change of clothes, toiletries, phone charger/power bank, comfortable walking shoes, a light jacket for air-conditioned buses and evening breezes, and cash for market shopping." }, { "de", "Bringen Sie ein kleines Handgepäckstück mit (Hauptgepäck bleibt im Hotel in Hurghada). Original-Pässe, Wechselkleidung, Kulturbeutel, Ladekabel/Powerbank, feste Schuhe, eine Jacke für Bus und Abend sowie Bargeld für den Basar einpacken." }, { "it", "Portate solo un bagaglio a mano leggero (i trolley grandi restano in hotel a Hurghada). Includete passaporti, cambio d'abiti, beauty case, caricatore, scarpe comode, giacca leggera per il pullman e la sera, e contanti per lo shopping." }, { "fr", "Prévoyez un sac de voyage cabine (les valises volumineuses restent à l'hôtel à Hurghada). Passeports originaux, vêtements de rechange, nécessaire de toilette, chargeur, bonnes chaussures, veste et argent de poche pour le souk." }, { "ru", "Возьмите небольшую дорожную сумку (большие чемоданы остаются в отеле в Хургаде). Паспорта, сменную одежду, удобную обувь, зарядки, туалетные принадлежности, легкую куртку и наличные для покупок на восточном базаре." } } } },
                Addons = new List<TourAddon>(),
                Media = new List<TourMedia> { new TourMedia { Url = "/images/tours/5861626853276193192.jpg", Captions = new Dictionary<string, string> { { "en", "Cairo Overnight - Experience" }, { "de", "Kairo 2-Tages-Tour mit Übernachtung - Erlebnis" }, { "it", "Il Cairo con Pernottamento (2 Giorni) - Esperienza" }, { "fr", "Le Caire 2 Jours avec Nuitée - Expérience" }, { "ru", "Каир: 2 дня с ночевкой - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193193.jpg", Captions = new Dictionary<string, string> { { "en", "Cairo Overnight - Experience" }, { "de", "Kairo 2-Tages-Tour mit Übernachtung - Erlebnis" }, { "it", "Il Cairo con Pernottamento (2 Giorni) - Esperienza" }, { "fr", "Le Caire 2 Jours avec Nuitée - Expérience" }, { "ru", "Каир: 2 дня с ночевкой - Впечатления" } } }, new TourMedia { Url = "/images/tours/5861626853276193200.jpg", Captions = new Dictionary<string, string> { { "en", "Cairo Overnight - Experience" }, { "de", "Kairo 2-Tages-Tour mit Übernachtung - Erlebnis" }, { "it", "Il Cairo con Pernottamento (2 Giorni) - Esperienza" }, { "fr", "Le Caire 2 Jours avec Nuitée - Expérience" }, { "ru", "Каир: 2 дня с ночевкой - Впечатления" } } } }
            },
            new Tour {
                Id = Guid.NewGuid(),
                Names = new Dictionary<string, string> { { "en", "Cairo Flight" }, { "de", "Kairo per Flugzeug (Tagesausflug)" }, { "it", "Il Cairo in Volo" }, { "fr", "Le Caire en Avion" }, { "ru", "Экскурсия в Каир на самолете" } },
                Descriptions = new Dictionary<string, string> { { "en", "Save road-travel time by flying from Hurghada to Cairo for a full-day cultural adventure. Visit the Giza Plateau and other major attractions, then return to Hurghada by air according to the booked flight schedule." }, { "de", "Sparen Sie wertvolle Reisezeit und fliegen Sie bequem von Hurghada nach Kairo zu einem hochkarätigen Kulturtag. Erleben Sie das Gizeh-Plateau und bedeutende Metropol-Attraktionen hautnah, bevor Sie am Abend entspannt per Inlandsflug nach Hurghada zurückkehren." }, { "it", "Ottimizza il tuo tempo raggiungendo Il Cairo in aereo da Hurghada per una prestigiosa avventura culturale di un giorno. Esplora l'altopiano di Giza e le meraviglie della capitale per poi rientrare comodamente in volo a Hurghada in serata." }, { "fr", "Gagnez un temps précieux en rejoignant Le Caire par les airs depuis Hurghada pour une journée culturelle d'exception. Admirez le plateau de Gizeh et les trésors de la capitale, puis regagnez Hurghada en avion en toute quiétude selon les horaires réservés." }, { "ru", "Сэкономьте время в пути благодаря быстрому перелету из Хургады в Каир и проведите день среди величайших памятников древности. Исследуйте плато Гиза и главные сокровища столицы, а вечером комфортно вернитесь на курорт обратным авиарейсом." } },
                Price = 275,
                Currency = "EUR",
                Duration = "Approx. 12-16 hours total, depending on flights",
                StartTime = "08:00",
                Rating = 4.9m,
                ReviewCount = 0,
                DestinationId = Guid.Parse("00000000-0000-0000-0000-000000000013"),
                CategoryId = Guid.Parse("00000000-0000-0000-0000-000000000009"),
