                Packages = new List<TourPackage>(),
                Itinerary = new List<TourItinerary>(),
                Inclusions = new List<TourInclusion>(),
                Exclusions = new List<TourInclusion>(),
                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Cairo Flight VIP day trip?" }, { "de", "Was ist im VIP-Tagesausflug 'Kairo per Flugzeug' enthalten?" }, { "it", "Cosa comprende il tour VIP 'Il Cairo in aereo' in giornata?" }, { "fr", "Qu'est-ce qui est inclus dans le tour VIP Le Caire en avion ?" }, { "ru", "Что входит в VIP-тур в Каир на самолете (Cairo Flight)?" } }, Answers = new Dictionary<string, string> { { "en", "The VIP flight tour includes private transfers between your Hurghada hotel and Hurghada Airport, round-trip domestic EgyptAir flight tickets (Hurghada - Cairo - Hurghada), private air-conditioned vehicle in Cairo with chauffeur, dedicated licensed Egyptologist guide, all admissions to the Giza Pyramids and Sphinx, the Egyptian Museum, and an upscale restaurant lunch overlooking the pyramids." }, { "de", "Die VIP-Flugreise beinhaltet Hoteltransfers zum Flughafen Hurghada, EgyptAir-Inlandsflugtickets (Hurghada–Kairo–Hurghada), privates klimatisiertes Fahrzeug mit Chauffeur in Kairo, privaten Ägyptologen als Guide, alle Eintrittskarten zu den Pyramiden von Gizeh, zur Sphinx und ins Ägyptische Museum sowie ein gehobenes Mittagessen mit Pyramidenblick." }, { "it", "Il tour VIP in aereo comprende transfer privati tra hotel e aeroporto di Hurghada, biglietti aerei a/r EgyptAir (Hurghada - Il Cairo - Hurghada), auto privata con autista al Cairo, guida egittologa privata dedicata, ingressi alle Piramidi di Giza, Sfinge e Museo Egizio, e raffinato pranzo in ristorante con vista piramidi." }, { "fr", "Cette journée VIP comprend les transferts aéroport à Hurghada, les billets d'avion aller-retour Hurghada - Le Caire sur vols réguliers, véhicule privé climatisé avec chauffeur au Caire, guide égyptologue privé, entrées aux pyramides de Gizeh, au Sphinx et au musée égyptien, et déjeuner dans un restaurant de qualité avec vue." }, { "ru", "В премиальный тур на самолете входят индивидуальный трансфер в аэропорт Хургады, авиабилеты на регулярные рейсы EgyptAir (Хургада - Каир - Хургада), автомобиль с водителем в Каире, персональный гид-египтолог, все входные билеты на пирамиды Гизы, к Сфинксу и в Египетский музей, а также обед в ресторане с видом на пирамиды." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "Why choose the flight tour over the bus/van excursion?" }, { "de", "Warum sollte man den Flugausflug anstelle des Busses oder Vans wählen?" }, { "it", "Perché scegliere il tour in aereo rispetto a quello in bus o minivan?" }, { "fr", "Pourquoi choisir l'avion plutôt que la route en bus ou van ?" }, { "ru", "Почему стоит выбрать самолет вместо поездки на автобусе или машине?" } }, Answers = new Dictionary<string, string> { { "en", "The flight takes just 55 minutes each way, completely eliminating 11 to 12 hours of highway road travel! You enjoy a relaxed morning wakeup, arrive in Cairo refreshed, tour exclusively in private comfort, and return to your Red Sea resort in time for evening drinks or dinner." }, { "de", "Der Flug dauert nur 55 Minuten pro Strecke und erspart Ihnen 11 bis 12 Stunden Fahrt auf der Autobahn! Sie schlafen morgens länger, reisen völlig entspannt, genießen exklusiven Privat-Service und sind abends rechtzeitig zurück im Strandhotel." }, { "it", "Il volo dura appena 55 minuti, eliminando 11-12 ore di viaggio in autostrada! Potrete partire riposati, visitare i monumenti con la massima tranquillità ed esclusività privata e rientrare nel vostro resort sul Mar Rosso in tempo per la cena." }, { "fr", "Le vol dure seulement 55 minutes au lieu de 11 à 12 heures de route ! Vous partez reposé, profitez d'une visite privée sur mesure sans la foule et rentrez à votre hôtel en bord de mer le soir même en pleine forme." }, { "ru", "Перелет занимает всего 55 минут в одну сторону вместо 11-12 часов утомительной дороги на автобусе! Вы не устаете, высыпаетесь, осматриваете величайшие памятники мира в индивидуальном темпе и возвращаетесь в свой курортный отель к ужину." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What documents are required and what are the baggage limits?" }, { "de", "Welche Dokumente werden benötigt und welche Freigepäckgrenzen gelten?" }, { "it", "Quali documenti servono e quali sono le regole sui bagagli?" }, { "fr", "Quels documents sont nécessaires et quelles sont les règles pour les bagages ?" }, { "ru", "Какие документы необходимы и какие правила перевозки багажа?" } }, Answers = new Dictionary<string, string> { { "en", "You must bring your physical original passport with valid Egypt entry visa stamp (passports are checked at airport security and boarding gates). As this is a day trip, travelers carry a standard hand luggage backpack or small tote bag with personal items and chargers." }, { "de", "Sie müssen Ihren physischen Original-Reisepass mit gültigem Ägypten-Visum mitführen (Sicherheitskontrolle am Flughafen). Für den Tagesausflug genügt ein normales Handgepäck oder ein Rucksack für Wertsachen und Smartphone." }, { "it", "È obbligatorio portare il passaporto originale con visto d'ingresso per l'Egitto in corso di validità (controlli in aeroporto). Trattandosi di un tour giornaliero, è sufficiente un piccolo zaino o borsa a mano per effetti personali e smartphone." }, { "fr", "Vous devez impérativement vous munir de votre passeport original avec visa égyptien en règle. Pour cette journée, un simple sac à dos cabine suffit pour vos effets personnels et appareils photo." }, { "ru", "Обязательно наличие оригинала заграничного паспорта с действующей египетской визой (проверяется службой безопасности аэропорта). Для однодневной поездки достаточно небольшого городского рюкзака для личных вещей, документов и телефона." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I wear on the Cairo Flight excursion?" }, { "de", "Was soll ich für die Flugreise nach Kairo anziehen?" }, { "it", "Come vestirsi per il tour in aereo al Cairo?" }, { "fr", "Comment s'habiller pour cette excursion en avion au Caire ?" }, { "ru", "Что надеть в поездку на самолете в Каир?" } }, Answers = new Dictionary<string, string> { { "en", "Smart-casual, respectful attire (shoulders and knees covered for historic sites and museum visits) with comfortable walking shoes. Carry a light cardigan or scarf for chilled airplane air-conditioning and evening return." }, { "de", "Gepflegte Freizeitkleidung (Schultern und Knie bedeckt für Museen und historische Stätten) und bequeme Schuhe. Eine Strickjacke für das klimatisierte Flugzeug und die kühleren Abendstunden ist ratsam." }, { "it", "Abbigliamento casual curato (spalle e ginocchia coperte per siti e musei) e scarpe comode. Portate una giacca leggera o un foulard per l'aria condizionata dell'aereo e per la sera." }, { "fr", "Tenue soignée et respectueuse (épaules et genoux couverts) avec chaussures confortables. Prévoyez un gilet léger pour la climatisation de l'avion." }, { "ru", "Опрятную и комфортную одежду (плечи и колени закрыты для культурных мест) и удобную обувь. Возьмите легкую кофту для самолета, где работает кондиционер." } } } },
