                ImportantInformation = new ImportantInfo(),
                Faqs = new List<TourFaq> { new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is included in the Cairo Eco bus tour?" }, { "de", "Was ist in der preiswerten Cairo Eco Bustour enthalten?" }, { "it", "Cosa comprende il tour economico in pullman Cairo Eco?" }, { "fr", "Qu'est-ce qui est inclus dans l'excursion économique en bus Cairo Eco ?" }, { "ru", "Что входит в эконом-тур в Каир на автобусе (Cairo Eco)?" } }, Answers = new Dictionary<string, string> { { "en", "Cairo Eco is our most budget-friendly road trip by modern air-conditioned tourist coach. It includes hotel pickup and return, licensed Egyptologist guide, entrance tickets to the Giza Pyramids Plateau, the Great Sphinx, the Egyptian Museum in Tahrir, and lunch at a local restaurant." }, { "de", "Cairo Eco ist unsere günstigste Option im komfortablen, klimatisierten Reisebus. Sie beinhaltet Hoteltransfers, lizenzierten deutschsprachigen Reiseleiter, Eintrittskarten zum Gizeh-Plateau mit den Pyramiden, zur Sphinx, in das Ägyptische Museum sowie ein Mittagessen im Restaurant." }, { "it", "Cairo Eco è la soluzione più conveniente in pullman turistico con aria condizionata. Include trasferimenti dall'hotel a/r, guida egittologa qualificata, biglietti d'ingresso alla Piana delle Piramidi di Giza, Grande Sfinge, Museo Egizio di Piazza Tahrir e pranzo al ristorante." }, { "fr", "Cairo Eco est notre formule la plus économique en grand car grand tourisme climatisé. Elle comprend les transferts, guide officiel, billets pour le plateau des pyramides de Gizeh, le Sphinx, le musée égyptien de la place Tahrir et le déjeuner au restaurant." }, { "ru", "Cairo Eco — самый экономичный вариант посещения Каира на большом туристическом автобусе с кондиционером. В стоимость входят трансфер из отеля, гид-египтолог, входные билеты на пирамиды Гизы, к Сфинксу, в Египетский музей и обед в ресторане." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "How does Cairo Eco differ from Cairo Van and Cairo Flight?" }, { "de", "Wie unterscheidet sich Cairo Eco von Cairo Van und Cairo Flight?" }, { "it", "In cosa differisce Cairo Eco rispetto a Cairo Van e Cairo Flight?" }, { "fr", "Quelle est la différence entre Cairo Eco, Cairo Van et Cairo Flight ?" }, { "ru", "В чем отличие Cairo Eco от Cairo Van и тура на самолете?" } }, Answers = new Dictionary<string, string> { { "en", "Cairo Eco operates on a large shared coach (approx. 35 to 45 passengers), offering maximum affordability. Cairo Van operates in a smaller, faster minibus (8 to 14 guests) with quicker hotel pickups, while Cairo Flight travels by domestic flight in under an hour for maximum speed and luxury." }, { "de", "Cairo Eco nutzt einen großen Reisebus (35 bis 45 Personen) zum besten Sparpreis. Cairo Van reist im kleineren Minivan (8 bis 14 Gäste) mit schnellerer Route, während Cairo Flight den 55-Minuten-Flug für höchsten Komfort wählt." }, { "it", "Cairo Eco viaggia su pullman gran turismo (35-45 passeggeri) garantendo il massimo risparmio. Cairo Van offre gruppi ridotti in minivan (8-14 passeggeri) più rapidi, mentre Cairo Flight utilizza l'aereo per evitare ore di strada con il massimo comfort." }, { "fr", "Cairo Eco s'effectue en grand autocar (35 à 45 passagers) pour un budget imbattable. Cairo Van se fait en petit minibus plus rapide (8 à 14 personnes), tandis que Cairo Flight propose le vol de 55 minutes pour un confort VIP sans fatigue." }, { "ru", "Cairo Eco проводится на большом автобусе (35-45 туристов), что дает самую выгодную цену. Cairo Van проходит на микроавтобусе (8-14 человек), быстрее собирает туристов по отелям, а тур на самолете позволяет долететь всего за 55 минут в VIP-формате." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What is the schedule for the Cairo Eco tour?" }, { "de", "Wie ist der zeitliche Ablauf der Cairo Eco Tour?" }, { "it", "Quali sono gli orari e il programma di Cairo Eco?" }, { "fr", "Quel est le programme et les horaires pour Cairo Eco ?" }, { "ru", "Какое расписание поездки в туре Cairo Eco?" } }, Answers = new Dictionary<string, string> { { "en", "Pick-up from Hurghada resorts begins between 01:30 and 02:15 AM. You reach Cairo around 08:30 AM, explore the Pyramids, Sphinx, and Museum with lunch, and arrive back in Hurghada between 21:30 and 22:30 PM." }, { "de", "Die Abholung erfolgt zwischen 01:30 und 02:15 Uhr. Sie erreichen Kairo gegen 08:30 Uhr, besichtigen Pyramiden, Sphinx und Museum inklusive Mittagessen und kehren gegen 21:30 bis 22:30 Uhr nach Hurghada zurück." }, { "it", "I prelievi in hotel si effettuano tra le 01:30 e le 02:15. Si giunge alle porte del Cairo verso le 08:30, si visitano Piramidi, Sfinge e Museo con pranzo e si rientra a Hurghada in serata tra le 21:30 e le 22:30." }, { "fr", "Départ des hôtels entre 01h30 et 02h15. Arrivée au Caire vers 08h30 pour découvrir les pyramides, le Sphinx et le musée, déjeuner inclus, et retour à Hurghada vers 21h30 - 22h30." }, { "ru", "Выезд из отелей Хургады в 01:30 - 02:15 ночи. Прибытие в Каир около 08:30 утра, экскурсии по пирамидам, Сфинксу и музею, обед и возвращение в Хургаду к 21:30 - 22:30." } } }, new TourFaq { Questions = new Dictionary<string, string> { { "en", "What should I bring on the Cairo Eco bus excursion?" }, { "de", "Was sollte man für die Cairo Eco Busreise mitbringen?" }, { "it", "Cosa portare a bordo del bus per Cairo Eco?" }, { "fr", "Que faut-il emporter dans le car pour Cairo Eco ?" }, { "ru", "Что взять с собой в автобусную поездку Cairo Eco?" } }, Answers = new Dictionary<string, string> { { "en", "Original passports (mandatory for police checkpoints), hotel breakfast box, bottle of water, comfortable walking shoes, a travel neck pillow for sleeping on the bus, a light sweater or jacket for bus air-conditioning, and cash for drinks and tips." }, { "de", "Original-Reisepass (Polizeikontrollen), Frühstückspaket aus dem Hotel, Wasser, bequeme Schuhe, ein Nackenkissen für den Reisebus, eine Jacke gegen die Busklimaanlage und Bargeld für Getränke und Trinkgelder." }, { "it", "Passaporto originale obbligatorio, cestino colazione dell'hotel, acqua, scarpe comode, cuscino da viaggio per dormire in pullman, felpa per l'aria condizionata del bus e contanti per bevande e mance." }, { "fr", "Passeports originaux obligatoires, panier petit-déjeuner de l'hôtel, bouteille d'eau, chaussures confortables, coussin cervical pour le trajet, petite laine pour la clim du bus et argent liquide." }, { "ru", "Оригиналы паспортов (обязательно для дорожных постов), ланч-бокс с завтраком из отеля, питьевую воду, удобную обувь, подушку под шею для сна в автобусе, легкую кофту для кондиционера и наличные деньги на напитки и чаевые." } } } },
